window.BANKS = window.BANKS || {};
window.BANKS.SSA101 = {"topics":[{"name":"Tổng hợp"}],"questions":[{"id":"SSA101_Q001","t":"Which is a characteristic of analytical thinking?","o":[["A","Guessing outcomes",""],["B","Ignoring evidence",""],["C","Verifying sources",""],["D","Avoiding comparison",""]],"a":"C","s":0,"tv":"Đặc điểm nào là đặc trưng của tư duy phân tích?","e":"Analytical thinking requires checking and verifying information sources before drawing conclusions.","ev":"Tư duy phân tích yêu cầu kiểm tra và xác minh nguồn thông tin trước khi đưa ra kết luận."},{"id":"SSA101_Q002","t":"What is one common reason students procrastinate?","o":[["A","Tasks feel unimportant or overwhelming",""],["B","Instructors assign unclear deadlines",""],["C","Students lack intelligence and teamwork",""],["D","College schedules are too flexible",""]],"a":"A","s":0,"tv":"Một lý do phổ biến mà students procrastinate là gì?","e":"When a task feels too difficult or unimportant, students tend to procrastinate.","ev":"Khi công việc quá khó hoặc không quan trọng, sinh viên dễ có xu hướng trì hoãn."},{"id":"SSA101_Q003","t":"Which concept focuses on identifying what tasks truly matter?","o":[["A","Multitasking",""],["B","Time blocking",""],["C","Prioritization",""],["D","Delegation",""]],"a":"C","s":0,"tv":"Khái niệm nào tập trung vào việc xác định những nhiệm vụ thực sự quan trọng?","e":"Prioritization helps identify tasks to focus on first.","ev":"Prioritization (ưu tiên công việc) giúp xác định nhiệm vụ cần tập trung trước tiên."},{"id":"SSA101_Q004","t":"Which habit most weakens critical thinking?","o":[["A","Seeking evidence",""],["B","Reflecting on assumptions and preconceptions",""],["C","Accepting information without evaluation",""],["D","Comparing multiple sources",""]],"a":"C","s":0,"tv":"Thói quen nào làm suy yếu nhất tư duy phản biện?","e":"Accepting information without evaluating or verifying it reduces critical thinking ability.","ev":"Chấp nhận thông tin mà không đánh giá hoặc kiểm chứng sẽ làm giảm khả năng tư duy phản biện."},{"id":"SSA101_Q005","t":"Which Bloom's level requires learners to break information into parts?","o":[["A","Understand",""],["B","Apply",""],["C","Analyze",""],["D","Remember",""]],"a":"C","s":0,"tv":"Mức độ nào trong thang Bloom yêu cầu người học chia nhỏ thông tin thành các phần?","e":"“Analyze” focuses on analyzing and breaking down information to understand it better.","ev":"“Analyze” là mức độ tập trung vào việc phân tích và chia nhỏ thông tin để hiểu rõ hơn."},{"id":"SSA101_Q006","t":"Which behavior most strongly limits creative thinking?","o":[["A","Questioning assumptions",""],["B","Fear of making mistakes",""],["C","Generating multiple solutions",""],["D","Seeking alternative perspectives",""]],"a":"B","s":0,"tv":"Hành vi nào hạn chế mạnh mẽ nhất tư duy sáng tạo?","e":"Fear of mistakes makes people reluctant to experiment and limits new creative ideas.","ev":"Nỗi sợ mắc sai lầm khiến con người ngại thử nghiệm và hạn chế ý tưởng sáng tạo mới."},{"id":"SSA101_Q007","t":"Which type of memory is primarily responsible for temporarily holding information while processing it?","o":[["A","Long-term memory",""],["B","Sensory memory",""],["C","Working memory",""],["D","Episodic memory",""]],"a":"C","s":0,"tv":"Loại trí nhớ nào chịu trách nhiệm chính cho việc temporarily holding information while processing it?","e":"Working memory helps store and process information in the short term.","ev":"Working memory (trí nhớ làm việc) giúp lưu trữ và xử lý thông tin ngắn hạn."},{"id":"SSA101_Q008","t":"Which step typically comes first in effective problem-solving?","o":[["A","Selecting a solution",""],["B","Clearly defining the problem",""],["C","Evaluating outcomes",""],["D","Implementing a plan immediately",""]],"a":"B","s":0,"tv":"Bước nào thường đến đầu tiên trong quá trình giải quyết vấn đề hiệu quả?","e":"Effective problem-solving requires clearly defining the problem first.","ev":"Muốn giải quyết hiệu quả cần xác định rõ vấn đề trước tiên."},{"id":"SSA101_Q009","t":"Analytical thinking is especially useful when students need to:","o":[["A","Memorize large amounts of information",""],["B","Understand complex systems or arguments",""],["C","Express personal opinions creatively",""],["D","Work under strict time pressure",""]],"a":"B","s":0,"tv":"tư duy phân tích is especially useful when students need to:","e":"Analytical thinking helps in understanding complex systems or arguments.","ev":"Tư duy phân tích giúp hiểu các hệ thống hoặc lập luận phức tạp."},{"id":"SSA101_Q010","t":"A student accepts an online claim because it aligns with their beliefs. Which critical thinking skill is missing?","o":[["A","Creativity and problem solving",""],["B","Logical reasoning",""],["C","Evaluation of evidence",""],["D","Time management",""]],"a":"C","s":0,"tv":"A student accepts an online claim because it aligns with their beliefs. Which tư duy phản biện skill is missing?","e":"Evidence must be evaluated instead of believing something merely because it fits a personal viewpoint.","ev":"Cần đánh giá bằng chứng thay vì chỉ tin vì phù hợp với quan điểm cá nhân."},{"id":"SSA101_Q011","t":"Analytical thinking involves:","o":[["A","Trusting intuition",""],["B","Breaking a whole into parts",""],["C","Following emotions",""],["D","Avoiding structure",""]],"a":"B","s":0,"tv":"tư duy phân tích involves:","e":"Analytical thinking breaks a large problem into smaller parts to understand it better.","ev":"Tư duy phân tích là chia một vấn đề lớn thành các phần nhỏ để hiểu rõ hơn."},{"id":"SSA101_Q012","t":"According to Long & Magerko (2020), AI literacy enables individuals to:","o":[["A","Fully automate decision-making",""],["B","Critically evaluate AI technologies",""],["C","Eliminate bias in all AI systems",""],["D","Replace teachers with AI",""]],"a":"B","s":0,"tv":"Theo Long & Magerko (2020), năng lực AI enables individuals to:","e":"AI literacy helps people critically evaluate and use AI technologies.","ev":"AI literacy giúp đánh giá và sử dụng công nghệ AI một cách có phê phán."},{"id":"SSA101_Q013","t":"Critical thinking involves:","o":[["A","Guessing outcomes based on personal experiences",""],["B","Weighing options and data",""],["C","Emotional reactions",""],["D","Blind trust",""]],"a":"B","s":0,"tv":"tư duy phản biện involves:","e":"Critical thinking requires weighing data and options before reaching a conclusion.","ev":"Tư duy phản biện yêu cầu cân nhắc dữ liệu và các lựa chọn trước khi kết luận."},{"id":"SSA101_Q014","t":"Creative thinking involves:","o":[["A","Memorization",""],["B","Generating original ideas",""],["C","Repeating tradition and exploring art",""],["D","Avoiding risk",""]],"a":"B","s":0,"tv":"tư duy sáng tạo involves:","e":"Creative thinking focuses on generating new and unique ideas.","ev":"Tư duy sáng tạo tập trung vào việc tạo ra ý tưởng mới và độc đáo."},{"id":"SSA101_Q015","t":"Cognitive presence in the Community of Inquiry refers mainly to:","o":[["A","Emotional engagement",""],["B","Knowledge construction through thinking",""],["C","Instructor authority",""],["D","Social interaction",""]],"a":"B","s":0,"tv":"“Sự hiện diện nhận thức” trong Community of Inquiry chủ yếu đề cập đến điều gì?","e":"Cognitive presence is the process of constructing knowledge through thinking and critical reflection.","ev":"Cognitive presence là quá trình xây dựng kiến thức thông qua tư duy và phản biện."},{"id":"SSA101_Q016","t":"Critical thinkers should:","o":[["A","Accept everything",""],["B","Question everything",""],["C","Avoid research",""],["D","Being smart in all situations",""]],"a":"B","s":0,"tv":"Những người có tư duy phản biện nên:","e":"Critical thinking requires questioning and evaluating information instead of immediately accepting everything.","ev":"Tư duy phản biện yêu cầu đặt câu hỏi và đánh giá thông tin thay vì chấp nhận mọi thứ ngay lập tức."},{"id":"SSA101_Q017","t":"Goal setting is most effective when goals are:","o":[["A","Ambitious and open-ended",""],["B","Flexible and undefined",""],["C","Specific, realistic, and measurable",""],["D","Focused only on long-term outcomes",""]],"a":"C","s":0,"tv":"Việc đặt mục tiêu hiệu quả nhất khi các mục tiêu:","e":"Specific, realistic, and measurable goals are easier to implement and evaluate.","ev":"Mục tiêu cụ thể, thực tế và đo lường được sẽ dễ thực hiện và đánh giá kết quả hơn."},{"id":"SSA101_Q018","t":"In the Plan-Monitor-Evaluate cycle, monitoring mainly focuses on:","o":[["A","Setting learning goals",""],["B","Checking understanding during learning",""],["C","Grading performance",""],["D","Comparing results with peers",""]],"a":"B","s":0,"tv":"Trong chu trình Plan-Monitor-Evaluate, việc “monitoring” chủ yếu tập trung vào:","e":"Monitoring means tracking understanding and learning progress during study.","ev":"Monitoring là theo dõi mức độ hiểu bài và tiến trình học tập trong quá trình học."},{"id":"SSA101_Q019","t":"Successful students typically view challenges as:","o":[["A","Signs they chose the wrong major",""],["B","Evidence of instructor bias",""],["C","Opportunities for growth and adjustment",""],["D","Reasons to withdraw from courses",""]],"a":"C","s":0,"tv":"Sinh viên thành công thường xem thử thách là:","e":"Challenges are seen as opportunities to develop and improve oneself.","ev":"Thử thách được xem như cơ hội để phát triển và cải thiện bản thân."},{"id":"SSA101_Q020","t":"What is one major difference between high school and college learning?","o":[["A","College instructors monitor students' progress more closely",""],["B","College requires greater student responsibility and self-advocacy",""],["C","College courses require fewer assessments but much more difficult",""],["D","College learning focuses less on independent work",""]],"a":"B","s":0,"tv":"Một khác biệt lớn giữa việc học ở trung học và đại học là gì?","e":"College requires students to be more proactive and responsible for their own learning.","ev":"Học đại học yêu cầu sinh viên chủ động và chịu trách nhiệm nhiều hơn cho việc học của mình."},{"id":"SSA101_Q021","t":"What is the main purpose of self-directed learning in online education?","o":[["A","To reduce instructor workload",""],["B","To help students take control of their learning",""],["C","To eliminate group work",""],["D","To replace assessments with self-study activities",""]],"a":"B","s":0,"tv":"Mục đích chính của self-directed learning in online education là gì?","e":"Self-directed learning helps students actively manage their learning process.","ev":"Học tự định hướng giúp sinh viên chủ động quản lý quá trình học tập của mình."},{"id":"SSA101_Q022","t":"What role does environment play in effective studying?","o":[["A","It has minimal impact",""],["B","It only matters for group study",""],["C","It can significantly affect focus and memory",""],["D","It replaces good study strategies and techniques",""]],"a":"C","s":0,"tv":"Môi trường đóng vai trò gì trong việc học hiệu quả?","e":"The learning environment greatly affects concentration and memory.","ev":"Môi trường học tập ảnh hưởng lớn đến khả năng tập trung và ghi nhớ thông tin."},{"id":"SSA101_Q023","t":"Which skill is NOT explicitly included in digital literacy as described in the book?","o":[["A","Evaluating online information",""],["B","Communicating through digital platforms and social media",""],["C","Understanding neural network architecture in depth",""],["D","Responsible engagement with digital content",""]],"a":"C","s":0,"tv":"Which skill is NOT explicitly included in năng lực kỹ thuật số as described in the book?","e":"Digital literacy focuses on using and evaluating digital technology, without requiring deep understanding of neural network architecture.","ev":"Digital literacy tập trung vào sử dụng và đánh giá công nghệ số, không yêu cầu hiểu sâu kiến trúc mạng nơ-ron."},{"id":"SSA101_Q024","t":"Which of the following is NOT a component of metacognition?","o":[["A","Planning how to approach a task",""],["B","Monitoring understanding during learning",""],["C","Evaluating outcomes after completing a task",""],["D","Memorizing facts without reflection",""]],"a":"D","s":0,"tv":"Điều nào sau đây KHÔNG phải là a component of metacognition?","e":"Metacognition involves planning, monitoring, and evaluating learning, not rote memorization.","ev":"Metacognition liên quan đến lập kế hoạch, theo dõi và đánh giá việc học, không phải học thuộc máy móc."},{"id":"SSA101_Q025","t":"Which of the following is identified as a common barrier to effective communication?","o":[["A","Clear purpose and using technologies",""],["B","Cultural awareness and prejudice",""],["C","Assumptions and misinterpretations",""],["D","Active listening strategies",""]],"a":"C","s":0,"tv":"Lựa chọn nào sau đây là identified as a common barrier to effective communication?","e":"Assumptions and misunderstandings often hinder effective communication.","ev":"Các giả định và hiểu sai thường gây cản trở giao tiếp hiệu quả."},{"id":"SSA101_Q026","t":"Which of the following best describes \"college culture\"?","o":[["A","A fixed set of rules identical across all academic institutions",""],["B","A system focused only on academic performance and science of knowledge",""],["C","Shared expectations, language, and norms within higher education",""],["D","A social environment unrelated to learning",""]],"a":"C","s":0,"tv":"Điều nào mô tả đúng nhất “văn hóa đại học”?","e":"College culture includes shared norms, expectations, and ways of communicating in higher education.","ev":"Văn hóa đại học bao gồm các chuẩn mực, kỳ vọng và cách giao tiếp chung trong môi trường giáo dục đại học."},{"id":"SSA101_Q027","t":"Which of the following best defines time-on-task?","o":[["A","The total time spent thinking about an assignment",""],["B","The actual time required to complete a specific task",""],["C","The time available before a deadline",""],["D","The amount of time scheduled for studying each week",""]],"a":"B","s":0,"tv":"Điều nào mô tả đúng nhất “time-on-task”?","e":"Time-on-task is the actual time spent completing a task.","ev":"Time-on-task là khoảng thời gian thực tế dành để hoàn thành nhiệm vụ."},{"id":"SSA101_Q028","t":"Which of the following best describes retrieval in learning?","o":[["A","Re-reading notes repeatedly",""],["B","Accessing and using stored knowledge when needed",""],["C","Highlighting important sections of a text",""],["D","Uploading materials to an AI chatbot",""]],"a":"B","s":0,"tv":"Điều nào mô tả đúng nhất việc truy xuất thông tin (retrieval) trong học tập?","e":"Retrieval is the process of accessing stored knowledge when needed.","ev":"Retrieval là quá trình lấy lại kiến thức đã lưu trữ khi cần sử dụng."},{"id":"SSA101_Q029","t":"Which of the following best describes encoding in the learning process?","o":[["A","Storing information permanently without effort using long-term memory",""],["B","Processing new information deeply so that memories are formed",""],["C","Recalling information during an exam",""],["D","Translating information into digital formats",""]],"a":"B","s":0,"tv":"Điều nào mô tả đúng nhất việc mã hóa thông tin (encoding) trong quá trình học tập?","e":"Encoding is processing new information to form memories.","ev":"Encoding là xử lý thông tin mới để tạo thành ký ức trong trí nhớ."},{"id":"SSA101_Q030","t":"Which of the following best distinguishes digital literacy from AI literacy?","o":[["A","Digital literacy focuses only on social media skills while AI literacy focuses on academic skills",""],["B","AI literacy includes competencies for understanding and interacting with AI systems",""],["C","AI literacy excludes ethical considerations",""],["D","Digital literacy is limited to hardware usage",""]],"a":"B","s":0,"tv":"Which of the following best distinguishes năng lực kỹ thuật số from năng lực AI?","e":"AI literacy focuses on understanding and interacting with AI systems, beyond basic digital skills.","ev":"AI literacy tập trung vào việc hiểu và tương tác với các hệ thống AI, vượt ngoài kỹ năng số cơ bản."},{"id":"SSA101_Q031","t":"Which of the following is a key step in analytical thinking?","o":[["A","Accepting information at face value and let it be there",""],["B","Separating facts from assumptions before drawing conclusions",""],["C","Generating as many ideas as possible regardless the quality of each idea",""],["D","Prioritizing emotional responses",""]],"a":"B","s":0,"tv":"Lựa chọn nào sau đây là a key step in tư duy phân tích?","e":"Analytical thinking requires distinguishing facts from assumptions before reaching a conclusion.","ev":"Tư duy phân tích yêu cầu phân biệt sự thật với giả định trước khi kết luận."},{"id":"SSA101_Q032","t":"Which activity best demonstrates metacognitive awareness?","o":[["A","Studying longer hours before exams to aim high grades",""],["B","Recognizing which study strategies work best for you",""],["C","Highlighting every paragraph in a textbook",""],["D","Copying notes from slides",""]],"a":"B","s":0,"tv":"Hoạt động nào thể hiện tốt nhất nhận thức siêu nhận thức (metacognitive awareness)?","e":"Metacognition is understanding and evaluating which learning methods work best for oneself.","ev":"Siêu nhận thức là hiểu và đánh giá cách học nào hiệu quả nhất với bản thân."},{"id":"SSA101_Q033","t":"Which factor most strongly affects how a message is interpreted?","o":[["A","The length of the message",""],["B","The context in which communication occurs",""],["C","The communication technology used such as social media",""],["D","The sender's educational background and attitude",""]],"a":"B","s":0,"tv":"Yếu tố nào ảnh hưởng mạnh nhất đến cách một thông điệp được diễn giải?","e":"The communication context greatly affects how the recipient understands a message.","ev":"Ngữ cảnh giao tiếp ảnh hưởng lớn đến cách người nhận hiểu thông điệp."},{"id":"SSA101_Q034","t":"Which question best helps evaluate the credibility of a source?","o":[["A","Is the information easy to read and interpret?",""],["B","Does the author have relevant expertise?",""],["C","Is the source visually appealing?",""],["D","Does the source confirm personal opinions?",""]],"a":"B","s":0,"tv":"Câu hỏi nào giúp đánh giá độ tin cậy của một nguồn thông tin tốt nhất?","e":"The author’s expertise is an important factor in determining a source’s credibility.","ev":"Chuyên môn của tác giả là yếu tố quan trọng để xác định độ tin cậy của nguồn."},{"id":"SSA101_Q035","t":"Which practice best demonstrates responsible use of information?","o":[["A","Copying text when sources are cited without any form of paraphrasing",""],["B","Paraphrasing without attribution",""],["C","Integrating sources while acknowledging original authors",""],["D","Using only one strong source",""]],"a":"C","s":0,"tv":"Thực hành nào thể hiện tốt nhất việc sử dụng thông tin có trách nhiệm?","e":"Original authors must be acknowledged when using information to avoid plagiarism.","ev":"Cần ghi nhận tác giả gốc khi sử dụng thông tin để tránh đạo văn."},{"id":"SSA101_Q036","t":"Which statement best reflects how time management in college differs from high school?","o":[["A","College students have fewer deadlines",""],["B","College schedules are more structured and require more efforts to follow",""],["C","College requires students to independently plan and allocate time",""],["D","Time management is less important in college",""]],"a":"C","s":0,"tv":"Which statement best reflects how quản lý thời gian in college differs from high school?","e":"In college, students are expected to manage their own time: they must plan and allocate it independently, with far less supervision than in high school. Having fewer deadlines or finding time management less important are not true of college.","ev":"Ở đại học, sinh viên phải tự quản lý thời gian: tự lập kế hoạch và phân bổ thời gian, với ít sự giám sát hơn nhiều so với cấp ba. Việc có ít hạn nộp hơn hoặc coi quản lý thời gian ít quan trọng hơn không đúng với môi trường đại học."},{"id":"SSA101_Q037","t":"Which statement best reflects the authors' view of the college transition?","o":[["A","It is primarily academic and rarely emotional",""],["B","It is uniform for all students",""],["C","It involves academic, social, and personal change",""],["D","It ends after the first month",""]],"a":"C","s":0,"tv":"Phát biểu nào phản ánh đúng nhất quan điểm của các tác giả về quá trình chuyển tiếp lên đại học?","e":"The transition to college includes academic, social, and personal changes.","ev":"Việc chuyển tiếp lên đại học bao gồm thay đổi về học tập, xã hội và cá nhân."},{"id":"SSA101_Q038","t":"Which action best represents effective problem-solving?","o":[["A","Selecting the first solution that seems reasonable",""],["B","Ignoring alternative approaches",""],["C","Evaluating possible solutions before implementation",""],["D","Avoiding feedback after solving the problem",""]],"a":"C","s":0,"tv":"Which action best represents effective giải quyết vấn đề?","e":"Solutions need to be evaluated before implementation to choose the most appropriate one.","ev":"Cần đánh giá các giải pháp trước khi áp dụng để chọn phương án phù hợp nhất."},{"id":"SSA101_Q039","t":"Which step typically comes first in effective problem-solving?","o":[["A","Choosing a solution",""],["B","Identifying and defining the problem clearly",""],["C","Evaluating results based on criteria",""],["D","Implementing a strategy using the power of teamwork",""]],"a":"B","s":0,"tv":"Bước nào thường đến đầu tiên trong quá trình giải quyết vấn đề hiệu quả?","e":"To solve a problem correctly, it must first be clearly identified.","ev":"Muốn giải quyết vấn đề đúng cần xác định rõ vấn đề trước tiên."},{"id":"SSA101_Q040","t":"Which question best reflects a critical thinking mindset?","o":[["A","\"Do I agree with this?\"",""],["B","\"Is this information popular?\"",""],["C","\"What evidence supports this claim?\"",""],["D","\"Who benefits from this idea emotionally?\"",""]],"a":"C","s":0,"tv":"Which question best reflects a tư duy phản biện mindset?","e":"Critical thinking focuses on evidence to assess the accuracy of information.","ev":"Tư duy phản biện tập trung vào bằng chứng để đánh giá tính đúng đắn của thông tin."},{"id":"SSA101_Q041","t":"Which activity best demonstrates analytical thinking?","o":[["A","Brainstorming multiple possible essay topics quickly and productively",""],["B","Identifying relevant data while ignoring unnecessary details in a problem",""],["C","Agreeing with the most popular interpretation of an issue",""],["D","Responding emotionally to complex situations",""]],"a":"B","s":0,"tv":"Which activity best demonstrates tư duy phân tích?","e":"Analytical thinking focuses on selecting important information and removing unnecessary details.","ev":"Tư duy phân tích tập trung vào việc chọn lọc thông tin quan trọng và loại bỏ chi tiết không cần thiết"},{"id":"SSA101_Q042","t":"Which strategy is recommended for managing test anxiety?","o":[["A","Avoiding preparation to reduce stress",""],["B","Relying on last-minute cramming",""],["C","Using preparation and familiarity to reduce fear",""],["D","Studying only the night before",""]],"a":"C","s":0,"tv":"Chiến lược nào được khuyến nghị để kiểm soát lo âu khi làm bài kiểm tra?","e":"Thorough preparation and familiarity with the content help reduce stress and anxiety.","ev":"Chuẩn bị kỹ và quen thuộc với nội dung giúp giảm căng thẳng và lo lắng."},{"id":"SSA101_Q043","t":"Which question reflects a metacognitive approach to learning?","o":[["A","\"How many pages do I need to read?\"",""],["B","\"What strategy am I using, and is it effective?\"",""],["C","\"Will this be on the exam and how can I have support?\"",""],["D","\"How long is this assignment?\"",""]],"a":"B","s":0,"tv":"Câu hỏi nào phản ánh cách tiếp cận siêu nhận thức trong học tập?","e":"Metacognition involves self-evaluating learning strategies and their effectiveness.","ev":"Siêu nhận thức là tự đánh giá chiến lược học tập và hiệu quả của nó."},{"id":"SSA101_Q044","t":"Which study habit is least effective for long-term learning?","o":[["A","Self-testing with flashcards, quiz and teaching others",""],["B","Spaced practice combined with interleaving",""],["C","Re-reading notes repeatedly without engagement",""],["D","Reviewing mistakes",""]],"a":"C","s":0,"tv":"Thói quen học tập nào kém hiệu quả nhất cho việc ghi nhớ lâu dài?","e":"Passive rereading without interaction or practice makes long-term retention difficult.","ev":"Chỉ đọc lại thụ động mà không tương tác hay luyện tập sẽ khó ghi nhớ lâu dài."},{"id":"SSA101_Q045","t":"Which condition best supports creative thinking?","o":[["A","Strict adherence to one correct answer",""],["B","Openness to risk and experimentation",""],["C","Avoidance of uncertainty",""],["D","Dependence on authority",""]],"a":"B","s":0,"tv":"Which condition best supports tư duy sáng tạo?","e":"Creative thinking develops when people are willing to experiment and accept risks.","ev":"Tư duy sáng tạo phát triển khi sẵn sàng thử nghiệm và chấp nhận rủi ro."},{"id":"SSA101_Q046","t":"Which situation would most clearly violate ethical guidelines when using AI for assessment?","o":[["A","Using AI to grade multiple-choice quizzes",""],["B","Using AI to provide grammar suggestions",""],["C","Using AI to evaluate student work without students' consent or awareness",""],["D","Using AI to help manage gradebooks",""]],"a":"C","s":0,"tv":"Tình huống nào vi phạm rõ ràng nhất các nguyên tắc đạo đức khi sử dụng AI trong đánh giá?","e":"Using AI without informing learners or obtaining their consent violates ethical principles.","ev":"Sử dụng AI mà không thông báo hoặc không có sự đồng ý của người học là vi phạm đạo đức."},{"id":"SSA101_Q047","t":"Why does the author warn against confusing opinion with evidence?","o":[["A","Opinions are always incorrect and being more effected by emotions",""],["B","Evidence-based reasoning leads to stronger conclusions",""],["C","Opinions slow down decision-making",""],["D","Evidence is difficult to interpret",""]],"a":"B","s":0,"tv":"Tại sao the author warn against confusing opinion with evidence?","e":"Evidence-based reasoning helps produce more reliable conclusions.","ev":"Lập luận dựa trên bằng chứng giúp đưa ra kết luận đáng tin cậy hơn."},{"id":"SSA101_Q048","t":"Why does Chapter 7 emphasize defining the problem accurately?","o":[["A","It reduces the number of possible solutions",""],["B","Incorrect problem definition leads to ineffective solutions",""],["C","It saves time in implementation",""],["D","It limits creative thinking",""]],"a":"B","s":0,"tv":"Tại sao Chapter 7 emphasize defining the problem accurately?","e":"If the problem is identified incorrectly, the resulting solution will be ineffective.","ev":"Nếu xác định sai vấn đề thì giải pháp đưa ra sẽ không hiệu quả."},{"id":"SSA101_Q049","t":"Why is retrieval practice effective for learning?","o":[["A","It reduces the amount of material and knowledge to study",""],["B","It strengthens memory storage and retrieval pathways",""],["C","It replaces the need for review knowledge",""],["D","It prevents forgetting entirely",""]],"a":"B","s":0,"tv":"Tại sao retrieval practice effective for learning?","e":"Retrieval practice strengthens memory and improves the ability to remember and recall information.","ev":"Luyện tập truy xuất giúp củng cố trí nhớ và tăng khả năng ghi nhớ, truy hồi thông tin."},{"id":"SSA101_Q050","t":"Why is relying solely on search engine rankings problematic?","o":[["A","High-ranking results are always outdated",""],["B","Rankings prioritize academic sources only",""],["C","Popularity does not equal accuracy or reliability",""],["D","Search engines limit access to peer-reviewed material",""]],"a":"C","s":0,"tv":"Tại sao relying solely on search engine rankings problematic?","e":"Popular content is not necessarily accurate or reliable.","ev":"Nội dung phổ biến chưa chắc đã chính xác hoặc đáng tin cậy."},{"id":"SSA101_Q051","t":"Why is using AI for personalized feedback considered ethically problematic in some cases?","o":[["A","AI feedback is always inaccurate or inclined towards complementation",""],["B","It may replace meaningful instructor-student learning relationships",""],["C","Students prefer automated feedback",""],["D","AI cannot process written language",""]],"a":"B","s":0,"tv":"Tại sao using AI for personalized feedback considered ethically problematic in some cases?","e":"AI can reduce interaction and learning relationships between instructors and students.","ev":"AI có thể làm giảm sự tương tác và mối quan hệ học tập giữa giảng viên và sinh viên."},{"id":"SSA101_Q052","t":"Why is understanding why you are in college considered foundational for success?","o":[["A","It helps students choose easier and low-cost courses",""],["B","It clarifies long-term goals and increases motivation",""],["C","It allows students to reduce academic workload",""],["D","It guarantees higher grades",""]],"a":"B","s":0,"tv":"Tại sao understanding why you are in college considered foundational for success?","e":"Understanding learning goals increases motivation and provides long-term direction.","ev":"Hiểu mục tiêu học tập giúp tăng động lực và định hướng lâu dài."},{"id":"SSA101_Q053","t":"Why is it important to evaluate bias in sources?","o":[["A","Bias invalidates all arguments and ideas",""],["B","Bias helps identify the strongest position to debate",""],["C","Understanding bias helps interpret information critically",""],["D","Biased sources should never be used",""]],"a":"C","s":0,"tv":"Tại sao it important to evaluate bias in sources?","e":"Recognizing bias helps analyze and evaluate information more objectively.","ev":"Nhận biết sự thiên vị giúp phân tích và đánh giá thông tin khách quan hơn."},{"id":"SSA101_Q054","t":"Why is intentional choice of communication method important?","o":[["A","Different methods require different levels of formality and clarity",""],["B","Face-to-face communication is always superior and productive",""],["C","Digital communication reduces misunderstandings",""],["D","Informal methods save time",""]],"a":"A","s":0,"tv":"Tại sao intentional choice of communication method lại quan trọng?","e":"Each communication method requires different levels of clarity and formality.","ev":"Mỗi hình thức giao tiếp cần mức độ rõ ràng và trang trọng khác nhau."},{"id":"SSA101_Q055","t":"Why is metacognition considered a self-regulation skill?","o":[["A","It controls classroom behavior and course expectation",""],["B","It allows students to manage and direct their learning",""],["C","It reduces dependence on instructors",""],["D","It improves memorization speed",""]],"a":"B","s":0,"tv":"Tại sao metacognition considered a self-regulation skill?","e":"Metacognition helps learners manage and adjust their own learning process.","ev":"Siêu nhận thức giúp người học tự quản lý và điều chỉnh quá trình học tập."},{"id":"SSA101_Q056","t":"Why is multitasking a bad habit for learning?","o":[["A","It increases creativity in complex tasks",""],["B","It often reduces efficiency and quality of work",""],["C","It saves time when deadlines overlap",""],["D","It improves long-term memory",""]],"a":"B","s":0,"tv":"Tại sao multitasking a bad habit for learning?","e":"Doing several things at once often reduces efficiency and work quality.","ev":"Làm nhiều việc cùng lúc thường làm giảm hiệu quả và chất lượng công việc."},{"id":"SSA101_Q057","t":"Why is the process in analytical thinking important?","o":[["A","Because outcomes matter more than understanding",""],["B","Because understanding how parts connect leads to better conclusions",""],["C","Because analytical thinking is slower than other thinking types",""],["D","Because it reduces creativity",""]],"a":"B","s":0,"tv":"Tại sao the process in tư duy phân tích lại quan trọng?","e":"Understanding connections between parts helps produce more accurate conclusions.","ev":"Hiểu mối liên hệ giữa các phần giúp đưa ra kết luận chính xác hơn."},{"id":"SSA101_Q058","t":"Why is transparency in AI systems important?","o":[["A","It increases software profits",""],["B","It allows users to modify algorithms directly",""],["C","It enables accountability and trust",""],["D","It eliminates the need for regulation",""]],"a":"C","s":0,"tv":"Tại sao transparency in AI systems lại quan trọng?","e":"Transparency increases trust and accountability in AI systems.","ev":"Tính minh bạch giúp tăng sự tin cậy và trách nhiệm giải trình của hệ thống AI."},{"id":"SSA101_Q059","t":"Why does the author argue that using AI to do the work instead of the student is problematic?","o":[["A","It violates copyright law automatically",""],["B","It cheats students out of the learning experience",""],["C","It reduces the accuracy of AI systems",""],["D","It increases institutional costs and reduces",""]],"a":"B","s":0,"tv":"Tại sao the author argue that using AI to do the work instead of the student is problematic?","e":"Letting AI do the work deprives students of opportunities to learn and develop skills.","ev":"Việc để AI làm thay khiến sinh viên mất cơ hội học tập và phát triển kỹ năng."},{"id":"SSA101_Q060","t":"Why should we review outcomes after implementing a solution?","o":[["A","To assign blame",""],["B","To determine whether adjustments are needed",""],["C","To prove effort was sufficient and possible",""],["D","To avoid repeating the process",""]],"a":"B","s":0,"tv":"Tại sao chúng ta nên xem xét kết quả sau khi thực hiện một giải pháp?","e":"Evaluating results helps determine whether the solution needs adjustment.","ev":"Đánh giá kết quả giúp xác định có cần điều chỉnh giải pháp hay không."},{"id":"SSA101_Q061","t":"Why does the book emphasize higher-order thinking in online learning?","o":[["A","Exams are more difficult online",""],["B","Surface learning is ineffective for long-term learning",""],["C","Students prefer complex tasks",""],["D","Memorization is no longer needed",""]],"a":"B","s":0,"tv":"Tại sao the book emphasize higher-order thinking in online learning?","e":"Surface learning is ineffective for long-term retention and understanding.","ev":"Học hời hợt không hiệu quả cho việc ghi nhớ và hiểu biết lâu dài."},{"id":"SSA101_Q062","t":"Why should encourage combining creative and analytical thinking be encouraged?","o":[["A","They are interchangeable skills and it is possible to replace each other",""],["B","Creativity generates ideas, while analysis refines them",""],["C","Creativity replaces logic",""],["D","Analysis limits imagination",""]],"a":"B","s":0,"tv":"Why should encourage combining creative and tư duy phân tích be encouraged?","e":"Creativity generates ideas, while analysis helps select and refine them.","ev":"Sáng tạo tạo ra ý tưởng, còn phân tích giúp chọn lọc và hoàn thiện chúng."},{"id":"SSA101_Q063","t":"According to the American Library Association (2011), digital literacy primarily refers to the ability to:","o":[["A","Program artificial intelligence systems to get the most productive information system",""],["B","Use information and communication technologies to find, evaluate, create, and communicate information",""],["C","Detect AI-generated content",""],["D","Replace human judgment with algorithms",""]],"a":"B","s":0,"tv":"Theo the American Library Association (2011), năng lực kỹ thuật số primarily refers to the ability to:","e":"Digital literacy includes using technology to find, evaluate, create, and communicate information.","ev":"Năng lực số bao gồm việc sử dụng công nghệ để tìm kiếm, đánh giá, tạo và truyền đạt thông tin."},{"id":"SSA101_Q064","t":"According to the chapter, creativity is:","o":[["A","A talent only some people are born with",""],["B","Limited to artistic disciplines",""],["C","A skill that can be developed and practiced",""],["D","Incompatible with analytical thinking",""]],"a":"C","s":0,"tv":"Theo the chapter, creativity is:","e":"Creativity is a skill that can be practiced and developed through practice.","ev":"Sáng tạo là kỹ năng có thể rèn luyện và phát triển thông qua thực hành."},{"id":"SSA101_Q065","t":"AI can support memory formation primarily by:","o":[["A","Replacing reading and note-taking entirely by provide main content of every document",""],["B","Providing metaphors, emotional connections, and multisensory learning ideas",""],["C","Automatically storing information in long-term memory",""],["D","Eliminating the need for attention and focus",""]],"a":"B","s":0,"tv":"AI có thể hỗ trợ hình thành trí nhớ chủ yếu bằng cách nào?","e":"AI supports memory by creating emotional connections, images, and multisensory learning.","ev":"AI hỗ trợ ghi nhớ bằng cách tạo liên kết cảm xúc, hình ảnh và nhiều giác quan trong học tập."},{"id":"SSA101_Q066","t":"A student feels overwhelmed during their first semester and avoids contacting professors. Based on Chapter 1, what is the best recommended action?","o":[["A","Focus only on independent study",""],["B","Wait until grades are released",""],["C","Seek support from faculty, advisors, and campus resources",""],["D","Reduce course load immediately",""]],"a":"C","s":0,"tv":"Một sinh viên cảm thấy quá tải trong học kỳ đầu tiên và tránh liên hệ với giảng viên. Theo Chương 1, hành động được khuyến nghị tốt nhất là gì?","e":"Seeking support from instructors and campus resources helps resolve difficulties more effectively.","ev":"Tìm kiếm sự hỗ trợ từ giảng viên và các nguồn lực trong trường giúp giải quyết khó khăn hiệu quả hơn."},{"id":"SSA101_Q067","t":"A student sends an emotional email to a professor late at night and receives a negative response. Based on Chapter 8, what principle was most likely violated?","o":[["A","Choosing the fastest communication method",""],["B","Considering tone, purpose, and audience before sending",""],["C","Using complete sentences and formal grammar",""],["D","Providing sufficient background information",""]],"a":"B","s":0,"tv":"Một sinh viên gửi email đầy cảm xúc cho giảng viên vào đêm muộn và nhận phản hồi tiêu cực. Theo Chương 8, nguyên tắc nào có khả năng bị vi phạm nhất?","e":"Communication requires considering tone, purpose, and audience before sending.","ev":"Khi giao tiếp cần cân nhắc giọng điệu, mục đích và đối tượng nhận trước khi gửi."},{"id":"SSA101_Q068","t":"A student struggles with word problems in math because they focus on every detail. Based on analytical thinking principles, what should they do first?","o":[["A","Practice more similar problems without reflection and revision",""],["B","Identify essential information and ignore irrelevant details",""],["C","Memorize formulas more frequently",""],["D","Seek help only after failing exams",""]],"a":"B","s":0,"tv":"A student struggles with word problems in math because they focus on every detail. Based on tư duy phân tích principles, what should they do first?","e":"Analytical thinking requires identifying important information and removing unnecessary details.","ev":"Tư duy phân tích yêu cầu xác định thông tin quan trọng và loại bỏ chi tiết không cần thiết."},{"id":"SSA101_Q069","t":"A student fails an exam and immediately blames lack of ability. From a problem-solving perspective, what should the student do instead?","o":[["A","Accept failure and move on, hope for better results",""],["B","Clearly identify contributing factors and possible changes",""],["C","Change majors immediately",""],["D","Increase study time without reflection and teamwork",""]],"a":"B","s":0,"tv":"A student fails an exam and immediately blames lack of ability. From a giải quyết vấn đề perspective, what should the student do instead?","e":"The student should analyze the causes and find ways to improve instead of blaming themselves.","ev":"Cần phân tích nguyên nhân và tìm giải pháp cải thiện thay vì tự trách bản thân."},{"id":"SSA101_Q070","t":"According to the text, a major concern for graduate students regarding AI grading tools is that:","o":[["A","AI grading is smarter than human grading and could overshade human's ability in grading",""],["B","AI systems may use their work as training data, affecting future publication",""],["C","AI cannot understand complex arguments",""],["D","AI always produces biased feedback",""]],"a":"B","s":0,"tv":"Theo the text, a major concern for graduate students regarding AI grading tools is that:","e":"Students worry that their work may be used as AI training data, affecting academic ownership.","ev":"Sinh viên lo ngại bài làm của họ bị dùng làm dữ liệu huấn luyện AI mà ảnh hưởng đến quyền sở hữu học thuật."},{"id":"SSA101_Q071","t":"A student avoids sharing unconventional ideas during group discussions. From a creative thinking perspective, what is the main consequence?","o":[["A","Improved efficiency and diverse forms of idea",""],["B","Reduced originality and idea generation",""],["C","Stronger analytical reasoning",""],["D","Clearer communication",""]],"a":"B","s":0,"tv":"A student avoids sharing unconventional ideas during group discussions. From a tư duy sáng tạo perspective, what is the main consequence?","e":"Reluctance to share new ideas reduces creativity and the number of ideas.","ev":"Việc ngại chia sẻ ý tưởng mới làm giảm tính sáng tạo và số lượng ý tưởng."},{"id":"SSA101_Q072","t":"According to the International Society of Academic Integrity (2021), academic integrity is best defined as:","o":[["A","Compliance with university assessment rules only",""],["B","A promise to uphold honesty, fairness, respect, responsibility, and courage",""],["C","The ability to avoid plagiarism through software tools and institutional policies",""],["D","A system of penalties designed to discourage cheating and misconduct",""]],"a":"B","s":0,"tv":"Theo the International Society of liêm chính học thuật (2021), liêm chính học thuật is best defined as:","e":"Academic integrity is based on honesty, fairness, respect, and responsibility.","ev":"Liêm chính học thuật dựa trên các giá trị trung thực, công bằng, tôn trọng và trách nhiệm."},{"id":"SSA101_Q073","t":"According to the chapter, the primary goal of learning is to:","o":[["A","Complete assignments as efficiently as possible using available tools",""],["B","Distill knowledge and skills so they can be applied in new situations",""],["C","Memorize large amounts of information for examinations",""],["D","Reduce cognitive effort through automation and technological support",""]],"a":"B","s":0,"tv":"Theo the chapter, the primary goal of learning is to:","e":"Learning aims to develop knowledge and skills that can be applied in new situations.","ev":"Học tập nhằm phát triển kiến thức và kỹ năng có thể áp dụng vào tình huống mới."},{"id":"SSA101_Q074","t":"According to Chapter 7, analytical thinking primarily involves:","o":[["A","Generating original ideas through imagination and brainstorming techniques",""],["B","Breaking information into components to understand relationships and patterns",""],["C","Evaluating arguments based on personal beliefs and values",""],["D","Solving problems through trial and error without structured steps",""]],"a":"B","s":0,"tv":"Theo Chapter 7, tư duy phân tích primarily involves:","e":"Analytical thinking breaks information into parts to understand their relationships and patterns.","ev":"Tư duy phân tích là chia nhỏ thông tin để hiểu mối liên hệ và quy luật giữa các phần."},{"id":"SSA101_Q075","t":"A student finds an article that supports their argument but is written by an anonymous author on a personal blog. Based on Chapter 7, what should the student do first?","o":[["A","Use the article because it supports the claim",""],["B","Evaluate the author's credibility and evidence provided",""],["C","Replace it with any academic article because journal articles are qualified",""],["D","Ignore online sources entirely",""]],"a":"B","s":0,"tv":"Một sinh viên tìm thấy một bài viết ủng hộ lập luận của mình nhưng được viết bởi một tác giả ẩn danh trên blog cá nhân. Dựa trên Chương 7, trước tiên sinh viên nên làm gì?","e":"Critical thinking requires evaluating the author's credibility and evidence before using a source.","ev":"Tư duy phản biện yêu cầu đánh giá độ tin cậy của tác giả và bằng chứng trước khi sử dụng nguồn thông tin."},{"id":"SSA101_Q076","t":"Creative thinking is described in as the ability to:","o":[["A","Follow established rules precisely",""],["B","Produce original ideas by making new connections",""],["C","Evaluate information objectively and systematically",""],["D","Solve problems using fixed procedures",""]],"a":"B","s":0,"tv":"tư duy sáng tạo is described in as the ability to:","e":"Creative thinking focuses on generating new ideas by connecting different ideas.","ev":"Tư duy sáng tạo tập trung vào việc tạo ra ý tưởng mới thông qua liên kết các ý tưởng khác nhau."},{"id":"SSA101_Q077","t":"Chapter 7 emphasizes that critical thinking requires students to:","o":[["A","Avoid questioning authority and forms of powers",""],["B","Consider multiple perspectives before judging",""],["C","Focus on speed rather than accuracy",""],["D","Rely on intuition",""]],"a":"B","s":0,"tv":"Chapter 7 emphasizes that tư duy phản biện requires students to:","e":"Critical thinking requires considering multiple perspectives before reaching a conclusion.","ev":"Tư duy phản biện đòi hỏi xem xét nhiều góc nhìn trước khi đưa ra kết luận."},{"id":"SSA101_Q078","t":"Communication is best described as:","o":[["A","A simple exchange of spoken words",""],["B","A one-way transfer of information and signals from sender to receiver",""],["C","A complex process influenced by context, purpose, and participants",""],["D","A skill used primarily in professional environments",""]],"a":"C","s":0,"tv":"Giao tiếp được mô tả chính xác nhất là:","e":"Communication is a complex process influenced by context, purpose, and participants.","ev":"Giao tiếp là một quá trình phức tạp chịu ảnh hưởng bởi bối cảnh, mục đích và người tham gia."},{"id":"SSA101_Q079","t":"Digital literacy is described as important because it:","o":[["A","Is only useful for students in technology majors",""],["B","Helps individuals critically evaluate online content",""],["C","Removes the need for critical thinking and metacognition",""],["D","Guarantees employment",""]],"a":"B","s":0,"tv":"năng lực kỹ thuật số is described as important because it:","e":"Digital literacy helps users selectively and critically evaluate online content.","ev":"Năng lực số giúp người dùng đánh giá nội dung trực tuyến một cách có chọn lọc và phản biện."},{"id":"SSA101_Q080","t":"Effective time management in college is important primarily because it:","o":[["A","Reduces the total number of assignments students receive",""],["B","Helps prevent a chain reaction of academic problems",""],["C","Allows students to finish college more quickly",""],["D","Eliminates the need for prioritization",""]],"a":"B","s":0,"tv":"Effective quản lý thời gian in college is important primarily because it:","e":"Good time management helps prevent delays from causing a series of academic problems.","ev":"Quản lý thời gian tốt giúp tránh việc chậm trễ dẫn đến hàng loạt vấn đề học tập."},{"id":"SSA101_Q081","t":"Guerrero-Dib, Portales, and Heredia-Escorza (2020) emphasize that academic integrity extends beyond cheating because it:","o":[["A","Focuses solely on punishment and enforcement",""],["B","Represents a commitment to the learning process and ethical use of resources",""],["C","Is mainly concerned with citation formatting and application of formal structure",""],["D","Applies only to written assignments",""]],"a":"B","s":0,"tv":"Guerrero-Dib, Portales, and Heredia-Escorza (2020) emphasize that liêm chính học thuật extends beyond cheating because it:","e":"Academic integrity shows commitment to learning and the ethical use of resources.","ev":"Trung thực học thuật thể hiện cam kết với quá trình học tập và việc sử dụng tài nguyên một cách đạo đức."},{"id":"SSA101_Q082","t":"Information literacy is defined as the ability to:","o":[["A","Memorize academic content efficiently",""],["B","Locate, evaluate, and use information effectively",""],["C","Rely on digital sources for research and study",""],["D","Avoid biased information entirely and consistently",""]],"a":"B","s":0,"tv":"năng lực thông tin is defined as the ability to:","e":"Information literacy is the ability to find, evaluate, and use information effectively.","ev":"Năng lực thông tin là khả năng tìm kiếm, đánh giá và sử dụng thông tin hiệu quả."},{"id":"SSA101_Q083","t":"Metacognition is best defined as","o":[["A","Thinking critically about academic content",""],["B","Awareness and regulation of one's own thinking and learning",""],["C","Memorizing information efficiently",""],["D","Monitoring other students' performance",""]],"a":"B","s":0,"tv":"Siêu nhận thức được định nghĩa chính xác nhất là:","e":"Metacognition is the ability to recognize and regulate one's own thinking and learning.","ev":"Siêu nhận thức là khả năng nhận thức và điều chỉnh quá trình suy nghĩ và học tập của bản thân."},{"id":"SSA101_Q084","t":"Metacognition helps students mainly by:","o":[["A","Increasing intelligence",""],["B","Making learning automatic",""],["C","Allowing learners to adjust strategies intentionally",""],["D","Reducing academic workload",""]],"a":"C","s":0,"tv":"Siêu nhận thức chủ yếu giúp sinh viên bằng cách:","e":"Metacognition helps learners actively adjust their learning strategies for better results.","ev":"Siêu nhận thức giúp người học chủ động điều chỉnh chiến lược học tập để đạt hiệu quả tốt hơn."},{"id":"SSA101_Q085","t":"One ethical concern about using AI as a grading tool is that it may:","o":[["A","Improve consistency too much",""],["B","Breach students' intellectual property by uploading their work to AI systems",""],["C","Reduce grading speed",""],["D","Require excessive faculty training",""]],"a":"B","s":0,"tv":"Một mối lo ngại về đạo đức khi sử dụng AI như một công cụ chấm điểm là nó có thể:","e":"Uploading students' work to AI systems can create risks to intellectual property and privacy.","ev":"Việc tải bài làm của sinh viên lên hệ thống AI có thể gây rủi ro về quyền sở hữu trí tuệ và quyền riêng tư."},{"id":"SSA101_Q086","t":"Problem-solving is best described as:","o":[["A","Finding the quickest answer to a difficulty",""],["B","Applying a structured process to address challenges",""],["C","Relying on intuition and experience to address normal issues",""],["D","Avoiding situations that seem complex",""]],"a":"B","s":0,"tv":"giải quyết vấn đề is best described as:","e":"Effective problem-solving requires a clear logical process instead of relying only on intuition.","ev":"Giải quyết vấn đề hiệu quả cần có quy trình logic và rõ ràng thay vì chỉ dựa vào trực giác."},{"id":"SSA101_Q087","t":"Procrastination is described as:","o":[["A","A harmless habit with minimal consequences that students usually have",""],["B","A delay that can trigger multiple academic difficulties",""],["C","A strategy for managing stress effectively",""],["D","A result of excessive motivation",""]],"a":"B","s":0,"tv":"Sự trì hoãn được mô tả là:","e":"Procrastination can cause academic difficulties such as deadline pressure and reduced performance.","ev":"Trì hoãn có thể dẫn đến nhiều khó khăn học tập như áp lực deadline và giảm hiệu suất."},{"id":"SSA101_Q088","t":"Problem-solving is described as:","o":[["A","Finding the fastest solution available based on A.I suggestion",""],["B","Applying a structured process to address challenges",""],["C","Using intuition to make decisions",""],["D","Avoiding complex situations",""]],"a":"B","s":0,"tv":"giải quyết vấn đề is described as:","e":"Problem-solving requires a structured approach to find an appropriate solution.","ev":"Giải quyết vấn đề cần cách tiếp cận có cấu trúc để tìm ra giải pháp phù hợp."},{"id":"SSA101_Q089","t":"Studying in college often requires students to:","o":[["A","Study only before exams",""],["B","Modify old habits to meet new academic demands",""],["C","Depend on memorization alone",""],["D","Avoid collaborative learning",""]],"a":"B","s":0,"tv":"Việc học ở đại học thường yêu cầu sinh viên phải:","e":"The college environment requires students to change study habits to adapt to new demands.","ev":"Môi trường đại học đòi hỏi sinh viên thay đổi thói quen học tập để thích nghi với yêu cầu mới."},{"id":"SSA101_Q090","t":"The concept of \"hallucination\" in AI refers to:","o":[["A","Visual misinterpretation by humans",""],["B","AI producing incorrect or fabricated information",""],["C","Emotional responses to AI feedback",""],["D","Errors caused only by user prompts",""]],"a":"B","s":0,"tv":"Khái niệm “hallucination” trong AI đề cập đến:","e":"Hallucination occurs when AI creates false or fabricated information but presents it as factual.","ev":"“Hallucination” là khi AI tạo ra thông tin sai hoặc bịa đặt nhưng trình bày như đúng sự thật."},{"id":"SSA101_Q091","t":"Employers value analytical thinkers because they:","o":[["A","Work alone confidently and work with AI effectively",""],["B","Use logical thinking to solve issues",""],["C","Avoid workplace conflict",""],["D","Prefer routine tasks",""]],"a":"B","s":0,"tv":"Nhà tuyển dụng đánh giá cao những người có tư duy phân tích vì họ:"},{"id":"SSA101_Q092","t":"Analytical thinking is commonly used when:","o":[["A","Writing poetry only",""],["B","Solving complex problems",""],["C","Avoiding decisions",""],["D","Relaxing",""]],"a":"B","s":0,"tv":"tư duy phân tích is commonly used when:"},{"id":"SSA101_Q093","t":"Amazon is significantly successful business based in analytical thinking, which of the following is a sign of applying analytical thinking?","o":[["A","Intuition",""],["B","Hyper organization",""],["C","Random processes",""],["D","Individual memory",""]],"a":"B","s":0,"tv":"Amazon is significantly successful business based in tư duy phân tích, which of the following is a sign of applying tư duy phân tích?"},{"id":"SSA101_Q094","t":"What is time management?","o":[["A","Controlling others",""],["B","Planning time use",""],["C","Working randomly",""],["D","Avoiding tasks and responsibilities",""]],"a":"B","s":0,"tv":"What is quản lý thời gian?"},{"id":"SSA101_Q095","t":"Which of the following best represents an effective use of a planner?","o":[["A","Recording deadlines after they pass",""],["B","Scheduling tasks without estimating duration",""],["C","Planning tasks while considering priorities and time-on-task",""],["D","Using it during exam weeks to cram knowledge in a short period of time",""]],"a":"C","s":0,"tv":"Điều nào sau đây thể hiện việc sử dụng sổ kế hoạch (planner) hiệu quả nhất?"},{"id":"SSA101_Q096","t":"What is scheduling?","o":[["A","Ignoring time",""],["B","Planning activities",""],["C","Avoiding tasks",""],["D","Doing tasks randomly without any structure or order",""]],"a":"B","s":0,"tv":"Scheduling là gì?"},{"id":"SSA101_Q097","t":"What tool helps prioritize tasks?","o":[["A","Calendar only",""],["B","Priority list",""],["C","Social media",""],["D","Email inbox",""]],"a":"B","s":0,"tv":"Công cụ nào giúp ưu tiên các công việc?"},{"id":"SSA101_Q098","t":"A student spends hours on low-priority tasks. What is the issue?","o":[["A","Good planning",""],["B","High productivity",""],["C","Poor prioritization",""],["D","Effective scheduling",""]],"a":"C","s":0,"tv":"Một sinh viên dành nhiều giờ cho các công việc có mức ưu tiên thấp. Vấn đề là gì?"},{"id":"SSA101_Q099","t":"What is \"keyword searching\"?","o":[["A","Writing essays",""],["B","Reading books strategically",""],["C","Using key terms",""],["D","Copying text",""]],"a":"C","s":0,"tv":"\"Keyword searching\" là gì?"},{"id":"SSA101_Q100","t":"What is information literacy?","o":[["A","Reading and present articles professionally",""],["B","Evaluating information",""],["C","Memorizing data",""],["D","Copying content",""]],"a":"B","s":0,"tv":"What is năng lực thông tin?"},{"id":"SSA101_Q101","t":"Why is problem-solving linked with other thinking skills?","o":[["A","Problem-solving replaces analytical thinking and creative thinking",""],["B","Effective problem-solving integrates multiple types of thinking",""],["C","Creative thinking interferes with problem-solving",""],["D","Critical thinking is unnecessary",""]],"a":"B","s":0,"tv":"Tại sao giải quyết vấn đề linked with other thinking skills?"},{"id":"SSA101_Q102","t":"Reviewing results after solving a problem helps students:","o":[["A","Assign blame to less responsible person",""],["B","Improve future problem-solving efforts",""],["C","Prove effort was sufficient to solve any problem",""],["D","Avoid repeating tasks",""]],"a":"B","s":0,"tv":"Việc xem xét lại kết quả sau khi giải quyết một vấn đề giúp sinh viên:"},{"id":"SSA101_Q103","t":"Why is flexibility important in problem-solving?","o":[["A","Problems rarely change once identified",""],["B","Initial solutions may not fully address the problem",""],["C","Flexibility reduces accountability",""],["D","It saves time in decision-making",""]],"a":"B","s":0,"tv":"Tại sao flexibility important in giải quyết vấn đề?"},{"id":"SSA101_Q104","t":"What is clarity in communication?","o":[["A","Long and complex sentences",""],["B","Beautiful and eloquent language",""],["C","Easy understanding",""],["D","Repetition and emphasizing",""]],"a":"C","s":0,"tv":"Sự rõ ràng trong giao tiếp là gì?"},{"id":"SSA101_Q105","t":"Which of the following best reflects the relationship between digital literacy and human agency?","o":[["A","Digital literacy reduces personal responsibility",""],["B","Algorithms fully determine human choices and thinking process",""],["C","Digital literacy helps individuals navigate algorithmic influence",""],["D","Human agency is irrelevant in digital environments",""]],"a":"C","s":0,"tv":"Which of the following best reflects the relationship between năng lực kỹ thuật số and human agency?"},{"id":"SSA101_Q106","t":"Which term describes AI systems producing incorrect or fabricated information?","o":[["A","Automation",""],["B","Optimization",""],["C","Hallucination",""],["D","Simulation",""]],"a":"C","s":0,"tv":"Thuật ngữ nào mô tả việc hệ thống AI tạo ra thông tin sai hoặc bịa đặt?"},{"id":"SSA101_Q107","t":"Which AI-supported strategy best aligns with improving memory storage?","o":[["A","Asking AI to summarize a chapter and skipping the reading",""],["B","Using AI to plan spaced practice after understanding the material",""],["C","Letting AI answer practice questions and remember the answer list",""],["D","Relying on AI-generated notes only",""]],"a":"B","s":0,"tv":"Chiến lược hỗ trợ bởi AI nào phù hợp nhất để cải thiện khả năng ghi nhớ?"},{"id":"SSA101_Q108","t":"Which of the following principle could best guides ethical student use of AI?","o":[["A","Use AI whenever it saves time and when you are too busy",""],["B","Use AI to support learning goals, not replace them",""],["C","Avoid AI entirely in higher education because it causes more harm than benefit",""],["D","Use AI only for graded tasks",""]],"a":"B","s":0,"tv":"Nguyên tắc nào hướng dẫn tốt nhất việc sử dụng AI một cách có đạo đức của sinh viên?"},{"id":"SSA101_Q109","t":"Why is using AI to complete assignments unethical?","o":[["A","It takes too much time",""],["B","It replaces the intended learning process",""],["C","It requires technical skills",""],["D","It reduces collaboration and social learning",""]],"a":"B","s":0,"tv":"Tại sao using AI to complete assignments unethical?"},{"id":"SSA101_Q110","t":"A student skips classes but studies alone. What is the likely issue?","o":[["A","Too much collaboration",""],["B","Low behavioral engagement",""],["C","Overconfidence",""],["D","Excessive motivation",""]],"a":"B","s":0,"tv":"Một sinh viên bỏ học trên lớp nhưng tự học một mình. Vấn đề có khả năng xảy ra là gì?"},{"id":"SSA101_Q111","t":"A student reads the syllabus carefully and plans ahead. This shows:","o":[["A","Passive learning",""],["B","Avoidance behavior",""],["C","Self-management",""],["D","Dependence on teachers",""]],"a":"C","s":0,"tv":"Một sinh viên đọc kỹ đề cương môn học và lập kế hoạch trước. Điều này thể hiện:"},{"id":"SSA101_Q112","t":"Which term describes taking responsibility for your own learning?","o":[["A","Passive learning",""],["B","Academic ownership",""],["C","External motivation",""],["D","Teacher-led learning systems",""]],"a":"B","s":0,"tv":"Thuật ngữ nào mô tả việc chịu trách nhiệm đối với việc học của chính mình?"},{"id":"SSA101_Q113","t":"A student studies extensively but keeps failing quizzes. From a metacognitive perspective, what is the most likely issue?","o":[["A","Lack of motivation",""],["B","Poor time management",""],["C","Ineffective study strategies not being evaluated",""],["D","Insufficient intelligence",""]],"a":"C","s":0,"tv":"Một sinh viên học rất nhiều nhưng vẫn liên tục làm bài kiểm tra không tốt. Theo góc nhìn siêu nhận thức (metacognition), nguyên nhân có khả năng nhất là gì?"},{"id":"SSA101_Q114","t":"Mark Twain compared idea generation to:","o":[["A","A journey",""],["B","A kaleidoscope",""],["C","A puzzle",""],["D","A dream-making machine",""]],"a":"B","s":0,"tv":"Mark Twain đã so sánh quá trình tạo ý tưởng với điều gì?"},{"id":"SSA101_Q115","t":"Tracking ideas enhances creativity because it:","o":[["A","Eliminates imagination",""],["B","Preserves inspiration",""],["C","Avoids reflection and conclusion",""],["D","Reduces novelty",""]],"a":"B","s":0,"tv":"Việc ghi lại các ý tưởng giúp tăng khả năng sáng tạo vì:"},{"id":"SSA101_Q116","t":"What is the key advantage of short, regular study sessions?","o":[["A","Less effort is required",""],["B","Information is memorized faster",""],["C","Focus and retention are improved",""],["D","Assignments become easier and more motivational",""]],"a":"C","s":0,"tv":"Lợi ích chính của những buổi học ngắn nhưng đều đặn là gì?"},{"id":"SSA101_Q118","t":"What is encoding in memory?","o":[["A","Forgetting information",""],["B","Converting information for storage in memory",""],["C","Repeating words and image",""],["D","Skipping details",""]],"a":"B","s":0,"tv":"Mã hóa (encoding) trong trí nhớ là gì?"},{"id":"SSA101_Q119","t":"What is the primary benefit of reviewing graded tests?","o":[["A","Improving GPA immediately",""],["B","Identifying grading errors",""],["C","Strengthening understanding and memory",""],["D","Reducing study time and have more fun if practicing with friends",""]],"a":"C","s":0,"tv":"Lợi ích chính của việc xem lại các bài kiểm tra đã được chấm điểm là gì?"},{"id":"SSA101_Q120","t":"Why are AI detection tools controversial in academic settings?","o":[["A","They could replace teachers in learning any knowledge",""],["B","They are difficult to install",""],["C","They are rarely used productively",""],["D","They may produce inaccurate results and false accusations",""]],"a":"D","s":0,"tv":"Tại sao các công cụ phát hiện AI lại gây tranh cãi trong môi trường học thuật?"},{"id":"SSA101_Q121","t":"Which institutional response best aligns with the ethical approach advocated in the text?","o":[["A","Developing clear AI usage policies and promoting transparency",""],["B","Banning all AI tools immediately because AI will destroy students' independent thinking",""],["C","Ignoring AI-related misconduct",""],["D","Replacing instructors with AI graders",""]],"a":"A","s":0,"tv":"Phản ứng nào của nhà trường phù hợp nhất với cách tiếp cận đạo đức được đề cập trong tài liệu?"},{"id":"SSA101_Q122","t":"Why are universities described as being \"in the process\" of developing AI policies?","o":[["A","AI adoption is declining",""],["B","AI is developing faster than ethical guidelines can be established",""],["C","Faculty resistance has ended and AI become a popular tool accepted everywhere",""],["D","Students no longer use AI",""]],"a":"B","s":0,"tv":"Tại sao các trường đại học được mô tả là đang \"trong quá trình\" xây dựng chính sách về AI?"},{"id":"SSA101_Q123","t":"Recognizing personal bias is part of:","o":[["A","Problem-solving",""],["B","Critical thinking",""],["C","Information literacy",""],["D","Intuition",""]],"a":"B","s":0,"tv":"Việc nhận ra thiên kiến cá nhân là một phần của kỹ năng nào?"},{"id":"SSA101_Q124","t":"Revisiting a resolved issue when conditions change is:","o":[["A","Weakness",""],["B","Critical awareness",""],["C","Confusion",""],["D","Creativity",""]],"a":"B","s":0,"tv":"Xem xét lại một vấn đề đã được giải quyết khi điều kiện thay đổi là biểu hiện của điều gì?"},{"id":"SSA101_Q125","t":"What is active listening?","o":[["A","Hearing only",""],["B","Engaging fully",""],["C","Interrupting to clarify if needed",""],["D","Ignoring speaker",""]],"a":"B","s":0,"tv":"Lắng nghe chủ động (active listening) là gì?"},{"id":"SSA101_Q126","t":"What is nonverbal communication?","o":[["A","Spoken words",""],["B","Body language",""],["C","Written text",""],["D","Grammar rules",""]],"a":"B","s":0,"tv":"Giao tiếp phi ngôn ngữ (nonverbal communication) là gì?"},{"id":"SSA101_Q127","t":"Analytical thinking can help prevent:","o":[["A","Emotional thinking",""],["B","Workplace inefficiency",""],["C","Creativity and overthinking",""],["D","Collaboration and communication",""]],"a":"B","s":0,"tv":"tư duy phân tích can help prevent:"},{"id":"SSA101_Q128","t":"Component parts refer to:","o":[["A","Final conclusions",""],["B","Emotional reactions",""],["C","Separate elements of a problem",""],["D","Examine assumptions and bias that influence thinking",""]],"a":"C","s":0,"tv":"“Component parts” đề cập đến điều gì?"},{"id":"SSA101_Q129","t":"Which skill supports analytical thinking?","o":[["A","Information literacy",""],["B","Ignoring data",""],["C","Emotional reaction and intuition",""],["D","Guesswork",""]],"a":"A","s":0,"tv":"Which skill supports tư duy phân tích?"},{"id":"SSA101_Q130","t":"Assembly lines (in mass production) reduced inefficiency by:","o":[["A","Eliminating thinking",""],["B","Dividing labor",""],["C","Increasing chaos",""],["D","Slowing production",""]],"a":"B","s":0,"tv":"Dây chuyền lắp ráp (assembly lines) trong sản xuất hàng loạt đã giảm sự kém hiệu quả bằng cách nào?"},{"id":"SSA101_Q131","t":"Which factor most strongly contributes to poor time management?","o":[["A","Lack of access to technology",""],["B","Underestimating how long tasks will take",""],["C","Too many group projects",""],["D","Excessive instructor support",""]],"a":"B","s":0,"tv":"Which factor most strongly contributes to poor quản lý thời gian?"},{"id":"SSA101_Q132","t":"What is one benefit of regularly evaluating your time management habits?","o":[["A","It guarantees higher grades",""],["B","It allows continuous adjustment and improvement",""],["C","It eliminates stress permanently",""],["D","It reduces course workload",""]],"a":"B","s":0,"tv":"What is one benefit of regularly evaluating your quản lý thời gian habits?"},{"id":"SSA101_Q133","t":"A student believes being constantly busy means they are managing time well. Based on Chapter 3, why is this assumption flawed?","o":[["A","Being busy always reduces learning quality and knowledge retention",""],["B","Productivity depends on purposeful prioritization, not just activity",""],["C","Time management only applies to academic tasks",""],["D","Busy students are more likely to procrastinate and aske for external support",""]],"a":"B","s":0,"tv":"Một sinh viên cho rằng lúc nào cũng bận rộn nghĩa là họ đang quản lý thời gian tốt. Tại sao giả định này không chính xác?"},{"id":"SSA101_Q134","t":"What is a planner used for?","o":[["A","Organizing time",""],["B","Entertainment",""],["C","Social media",""],["D","Ignoring deadlines",""]],"a":"A","s":0,"tv":"Planner được sử dụng để làm gì?"},{"id":"SSA101_Q135","t":"What is procrastination?","o":[["A","Planning tasks",""],["B","Delaying tasks",""],["C","Completing tasks",""],["D","Prioritizing tasks",""]],"a":"B","s":0,"tv":"Procrastination là gì?"},{"id":"SSA101_Q137","t":"A student copies text without citation. This is:","o":[["A","Research",""],["B","Plagiarism",""],["C","Summary",""],["D","Analysis",""]],"a":"B","s":0,"tv":"Một sinh viên sao chép văn bản mà không trích dẫn nguồn. Đây là hành vi gì?"},{"id":"SSA101_Q139","t":"What is paraphrasing?","o":[["A","Copying text",""],["B","Rewriting ideas",""],["C","Quoting directly",""],["D","Ignoring source",""]],"a":"B","s":0,"tv":"Paraphrasing là gì?"},{"id":"SSA101_Q142","t":"Why is it important to define the problem accurately?","o":[["A","It limits the number of possible solutions and reduces cost accordingly",""],["B","Misidentified problems often lead to ineffective solutions",""],["C","It saves time and energy during implementation",""],["D","It reduces the need for evaluation",""]],"a":"B","s":0,"tv":"Tại sao it important to define the problem accurately?"},{"id":"SSA101_Q143","t":"Which statement best reflects the chapter's view of problem-solving outcomes?","o":[["A","A solution must work perfectly the first time",""],["B","Solutions should be evaluated and adjusted if needed",""],["C","Once a solution is chosen, it should not change because of the financial riks",""],["D","Outcomes matter more than process",""]],"a":"B","s":0,"tv":"Which statement best reflects the chapter's view of giải quyết vấn đề outcomes?"},{"id":"SSA101_Q144","t":"What is effective communication?","o":[["A","Speaking loudly and emotionally",""],["B","Clear message exchange",""],["C","Talking more to express yourself",""],["D","Ignoring feedback",""]],"a":"B","s":0,"tv":"Giao tiếp hiệu quả (effective communication) là gì?"},{"id":"SSA101_Q146","t":"Digital literacy enhances employability mainly because it:","o":[["A","Guarantees higher salaries",""],["B","Enables adaptation to technological change",""],["C","Eliminates workplace stress and enhance mental health",""],["D","Replaces teamwork skills",""]],"a":"B","s":0,"tv":"năng lực kỹ thuật số enhances employability mainly because it:"},{"id":"SSA101_Q148","t":"The book suggests digital literacy programs should include training on:","o":[["A","AI coding only",""],["B","Protecting personal data and digital footprints",""],["C","Eliminating AI tools",""],["D","Memorizing algorithms and how to train data",""]],"a":"B","s":0,"tv":"The book suggests năng lực kỹ thuật số programs should include training on:"},{"id":"SSA101_Q149","t":"AI can support memory formation by:","o":[["A","Replacing reading and note-taking entirely by provide main content of every document",""],["B","Providing metaphors, emotional connections, and multisensory learning ideas",""],["C","Automatically storing information in long-term memory",""],["D","Eliminating the need for attention and focus",""]],"a":"B","s":0,"tv":"AI có thể hỗ trợ quá trình hình thành trí nhớ bằng cách nào?"},{"id":"SSA101_Q152","t":"Which factor contributes most to student success?","o":[["A","Intelligence only",""],["B","Active engagement",""],["C","Memorizing everything",""],["D","Avoiding challenges",""]],"a":"B","s":0,"tv":"Yếu tố nào đóng góp nhiều nhất vào sự thành công của sinh viên?"},{"id":"SSA101_Q154","t":"Which of the following best illustrates monitoring in metacognition?","o":[["A","Creating a study schedule",""],["B","Checking comprehension while reading",""],["C","Reviewing grades at the end of the semester",""],["D","Choosing a major",""]],"a":"B","s":0,"tv":"Điều nào sau đây minh họa rõ nhất cho monitoring (tự giám sát) trong siêu nhận thức (metacognition)?"},{"id":"SSA101_Q156","t":"Why is metacognition linked to academic success?","o":[["A","Successful students study longer and collaboratively",""],["B","Effective learners actively reflect and adapt",""],["C","Intelligence predicts performance",""],["D","Grades depend on effort alone",""]],"a":"B","s":0,"tv":"Tại sao metacognition linked to academic success?"},{"id":"SSA101_Q157","t":"Creativity often combines:","o":[["A","Only new ideas",""],["B","Old ideas in new ways",""],["C","Unrelated facts and information",""],["D","Strict repetition",""]],"a":"B","s":0,"tv":"Sự sáng tạo (creativity) thường kết hợp điều gì?"},{"id":"SSA101_Q158","t":"If a student combines two theories to form a new model, this reflects:","o":[["A","Simple recall",""],["B","Creative synthesis",""],["C","Memorization",""],["D","Avoidance",""]],"a":"B","s":0,"tv":"Nếu một sinh viên kết hợp hai lý thuyết để tạo thành một mô hình mới, điều này phản ánh điều gì?"},{"id":"SSA101_Q160","t":"Creativity improves thinking skills by:","o":[["A","Limiting scope",""],["B","Narrowing vision",""],["C","Expanding possibilities",""],["D","Avoiding challenge",""]],"a":"C","s":0,"tv":"Sự sáng tạo cải thiện kỹ năng tư duy bằng cách nào?"},{"id":"SSA101_Q161","t":"Which learner behavior best reflects metacognitive awareness?","o":[["A","Completing tasks quickly",""],["B","Following instructions exactly",""],["C","Reflecting on what strategies worked or failed",""],["D","Memorizing lecture slides",""]],"a":"C","s":0,"tv":"Hành vi nào của người học phản ánh rõ nhất metacognitive awareness (nhận thức siêu nhận thức)?"},{"id":"SSA101_Q162","t":"Which situation BEST illustrates weak social presence in an online course?","o":[["A","Students debate ideas respectfully",""],["B","Learners avoid responding to peers",""],["C","Instructors provide timely feedback",""],["D","Groups set clear communication rules",""]],"a":"B","s":0,"tv":"Tình huống nào minh họa rõ nhất social presence yếu trong một khóa học trực tuyến?"},{"id":"SSA101_Q164","t":"What is working memory?","o":[["A","Long-term storage",""],["B","Temporary processing space",""],["C","Permanent recall of knowledge",""],["D","Emotional memory system",""]],"a":"B","s":0,"tv":"What is trí nhớ làm việc (working memory)?"},{"id":"SSA101_Q166","t":"A student studies 10 minutes daily instead of cramming. This uses:","o":[["A","Massed practice",""],["B","Spaced learning",""],["C","Passive recall",""],["D","Surface processing",""]],"a":"B","s":0,"tv":"Một sinh viên học 10 phút mỗi ngày thay vì học dồn trước kỳ thi. Phương pháp này sử dụng kỹ thuật nào?"},{"id":"SSA101_Q167","t":"According to the text, a major concern for graduate students regarding AI grading tools is that:","o":[["A","AI grading is smarter than human grading and could overshadow human's ability in grading",""],["B","AI systems may use their work as training data, affecting future publication",""],["C","AI cannot understand complex arguments",""],["D","AI always produces biased feedback",""]],"a":"B","s":0,"tv":"Theo the text, a major concern for graduate students regarding AI grading tools is that:"},{"id":"SSA101_Q168","t":"Which method helps reduce test anxiety?","o":[["A","Avoid studying",""],["B","Ignoring exams",""],["C","Preparation",""],["D","Skipping practice",""]],"a":"C","s":0,"tv":"Phương pháp nào giúp giảm lo lắng khi thi (test anxiety)?"},{"id":"SSA101_Q169","t":"Which action would most directly improve a student's metacognitive skills?","o":[["A","Increasing total study hours",""],["B","Reflecting on why an exam strategy failed",""],["C","Highlighting more information",""],["D","Studying with friends",""]],"a":"B","s":0,"tv":"Hành động nào trực tiếp nhất giúp cải thiện kỹ năng siêu nhận thức (metacognitive skills) của sinh viên?"},{"id":"SSA101_Q170","t":"When planning travel during uncertainty, you should:","o":[["A","Ignore risk",""],["B","Assume success",""],["C","Prepare backup plans",""],["D","Avoid thinking",""]],"a":"C","s":0,"tv":"Khi lập kế hoạch đi lại trong điều kiện không chắc chắn, bạn nên:"},{"id":"SSA101_Q171","t":"Critical thinking forces you to determine:","o":[["A","Actual situation",""],["B","By emotion",""],["C","Preference and research",""],["D","Habit",""]],"a":"A","s":0,"tv":"tư duy phản biện forces you to determine:"},{"id":"SSA101_Q172","t":"Looking at something \"with a different lens\" means:","o":[["A","Reframing perspective",""],["B","Criticizing it",""],["C","Ignoring details",""],["D","Avoiding structure",""]],"a":"A","s":0,"tv":"Nhìn một vấn đề \"with a different lens\" (qua một lăng kính khác) có nghĩa là:"},{"id":"SSA101_Q173","t":"What is one major purpose of college beyond career preparation?","o":[["A","To avoid responsibilities",""],["B","Personal growth",""],["C","To earn money quickly",""],["D","To reduce social interaction",""]],"a":"B","s":0,"tv":"Một mục đích quan trọng của việc học đại học ngoài chuẩn bị cho nghề nghiệp là gì?","e":"Personal growth.","ev":"Phát triển bản thân."},{"id":"SSA101_Q174","t":"A student sets specific study hours daily. This improves:","o":[["A","Confusion",""],["B","Procrastination",""],["C","Consistency",""],["D","Random work habits",""]],"a":"C","s":0,"tv":"Một sinh viên đặt ra giờ học cụ thể mỗi ngày. Điều này cải thiện:"},{"id":"SSA101_Q175","t":"Developing a board game from literature shows:","o":[["A","Recall from the best childhood experiences",""],["B","Memorization",""],["C","Creative transformation",""],["D","Imitation from best practices",""]],"a":"C","s":0,"tv":"Việc phát triển một board game (trò chơi bàn cờ) dựa trên tác phẩm văn học thể hiện:"},{"id":"SSA101_Q176","t":"What is the primary role of a rubric in assignments?","o":[["A","To limit creativity",""],["B","To replace instructor's guideline and comments",""],["C","To explain grading criteria clearly",""],["D","To rank students",""]],"a":"C","s":0,"tv":"Vai trò chính của rubric trong các bài tập là gì?"},{"id":"SSA101_Q177","t":"What risk is associated with uploading dense readings to AI for summaries without reading them?","o":[["A","Reduced chances to practicing English",""],["B","Missing critical thinking required for memory formation",""],["C","Violating institutional AI policies automatically",""],["D","Overloading working memory and risk to pay more for AI premium versions",""]],"a":"B","s":0,"tv":"Rủi ro nào liên quan đến việc đưa các bài đọc khó/dày đặc cho AI tóm tắt mà không tự đọc chúng?"},{"id":"SSA101_Q178","t":"Which factor makes academic integrity a shared responsibility?","o":[["A","Only students submit assignments",""],["B","Institutions must establish clear guidelines and pedagogical practices",""],["C","Faculty are solely responsible for enforcement",""],["D","Internal communication campaign to criticize and condemn case studies of plagiarism",""]],"a":"B","s":0,"tv":"Which factor makes liêm chính học thuật a shared responsibility?"},{"id":"SSA101_Q179","t":"What is a 'Liability' example provided for college students?","o":[["A","A savings account.",""],["B","A student loan or credit card debt.",""],["C","Income from a part-time job.",""],["D","A scholarship.",""]],"a":"B","s":0,"e":"In strict financial terms, a liability represents any legally binding financial obligation or borrowed capital that must eventually be repaid, usually with accrued interest. For the vast majority of college students, the most significant and burdensome liabilities they carry are outstanding federal or private student loans and high-interest consumer credit card balances.","ev":"Xét về mặt tài chính, nợ phải trả là bất kỳ nghĩa vụ tài chính ràng buộc về mặt pháp lý hoặc vốn vay nào mà cuối cùng phải được hoàn trả, thường kèm theo lãi suất. Đối với phần lớn sinh viên [?]"},{"id":"SSA101_Q180","t":"What is the mathematical formula for Net Worth?","o":[["A","Income + Expenses = Net Worth",""],["B","Assets + Liabilities = Net Worth",""],["C","Assets (Owned) – Liabilities (Owed) = Net Worth",""],["D","Savings – Debt = Net Worth",""]],"a":"C","s":0,"e":"The mathematical formula to calculate Net Worth is extremely straightforward but conceptually critical: you take your total Assets (everything you legally own that holds economic value) and subtract your total Liabilities (every single cent of borrowed money or outstanding debt that you owe) to find your true Net Worth.","ev":"Công thức toán học để tính Giá trị tài sản ròng (Net Worth) rất đơn giản nhưng quan trọng về mặt khái niệm: bạn lấy tổng Tài sản (mọi thứ bạn sở hữu hợp pháp có giá trị kinh tế) trừ đi tổng Nợ phải trả (mọi khoản tiền vay hoặc nợ chưa thanh toán) để tìm ra Giá trị tài sản ròng thực sự của mình."},{"id":"SSA101_Q181","t":"What is the first step in the five-step financial planning process?","o":[["A","Monitor and Adjust the Plan",""],["B","Implement the Plan",""],["C","Develop Personal Goals",""],["D","Write My Financial Plan",""]],"a":"C","s":0,"e":"The rigorous five-step financial planning process must logically start with developing specific personal goals. Without clearly articulating what you actually want to achieve—such as eliminating debt or saving for a house—your financial plan will lack direction, making it impossible to create actionable budgets or measure meaningful progress.","ev":"Quy trình lập kế hoạch tài chính nghiêm ngặt gồm năm bước phải bắt đầu bằng việc xác định các mục tiêu cá nhân cụ thể. Nếu không xác định rõ ràng những gì bạn thực sự muốn đạt được—chẳng hạn như xóa nợ hoặc tiết kiệm để mua nhà—kế hoạch tài chính của bạn sẽ thiếu định hướng, khiến việc lập ngân sách khả thi hoặc đo lường tiến độ có ý nghĩa trở nên bất khả thi."},{"id":"SSA101_Q182","t":"Which time management app uses boards to organize obligations and share them with collaborators?","o":[["A","Toggl",""],["B","Trello",""],["C","Sticky Notes",""],["D","Google Calendar",""]],"a":"B","s":0,"tv":"Which quản lý thời gian app uses boards to organize obligations and share them with collaborators?","e":"Trello is a visual time and project management application that utilizes a highly intuitive system of digital boards, lists, and movable cards. It allows you to organize multiple academic obligations, track their progress in real-time, and easily share or assign these tasks with collaborators during group projects to ensure everyone stays on schedule.","ev":"Trello là một ứng dụng quản lý thời gian và dự án trực quan, sử dụng hệ thống bảng kỹ thuật số, danh sách và thẻ di động vô cùng dễ sử dụng. Nó cho phép bạn tổ chức nhiều nghĩa vụ học tập, theo dõi tiến độ trong thời gian thực và dễ dàng chia sẻ hoặc giao nhiệm vụ cho cộng tác viên trong các dự án nhóm để đảm bảo mọi người luôn đúng tiến độ."},{"id":"SSA101_Q183","t":"Which motivation strategy involves adopting the mindset that you alone are responsible for your goals?","o":[["A","Reward Yourself",""],["B","Tap into Other People's Energy",""],["C","Increase Personal Responsibility",""],["D","Visualize the Results",""]],"a":"C","s":0,"e":"The motivation strategy of \"Increasing Personal Responsibility\" requires an internal mindset shift where you fully accept that you are the sole driver of your academic and professional success. By holding yourself entirely accountable for your goals, you eliminate the habit of blaming external factors and empower yourself to take direct control over your learning journey.","ev":"Chiến lược tạo động lực \"Tăng cường trách nhiệm cá nhân\" đòi hỏi sự thay đổi tư duy nội tại, nơi bạn hoàn toàn chấp nhận rằng bạn là người duy nhất chịu trách nhiệm cho thành công học tập và nghề nghiệp của mình. Bằng cách tự chịu trách nhiệm hoàn toàn cho mục tiêu của bản thân, bạn loại bỏ thói quen đổ lỗi cho các yếu tố bên ngoài và tự trao quyền kiểm soát trực tiếp hành trình học tập của mình."},{"id":"SSA101_Q184","t":"Which motivation strategy suggests that moods and emotions can be influenced by those around you?","o":[["A","Visualize the Results.",""],["B","Tap into Other People's Energy.",""],["C","Break the Goal Down.",""],["D","Increase Personal Responsibility.",""]],"a":"B","s":0,"e":"Human emotions and motivation levels are highly contagious via a psychological concept known as \"emotional contagion.\" By intentionally surrounding yourself with driven, positive, and naturally focused peers or mentors, you unconsciously absorb their productive energy and high standards, which actively helps pull you out of academic slumps and reinforces your own commitment to success.","ev":"Cảm xúc và động lực của con người có tính lây lan cao thông qua một khái niệm tâm lý gọi là \"sự lây lan cảm xúc\". Bằng cách chủ động bao quanh mình bởi những người bạn hoặc người hướng dẫn tích cực, có động lực và tập trung, bạn sẽ hấp thụ năng lượng tích cực và tiêu chuẩn cao của họ, giúp bạn thoát khỏi sự sa sút trong học tập và củng cố cam kết thành công của chính mình."},{"id":"SSA101_Q185","t":"Which career assessment tool identifies motivations by ranking different aspects of work?","o":[["A","MAPP Test",""],["B","MyPlan",""],["C","Career Cluster Interest Survey",""],["D","Myers-Briggs Type Indicator",""]],"a":"A","s":0,"e":"The MAPP (Motivational Appraisal Personal Potential) test is a comprehensive career assessment instrument that moves beyond simple skills testing. It uncovers your true intrinsic motivations and natural inclinations by requiring you to rank various distinct aspects of work, daily tasks, and environments, helping align your career path with long-term job satisfaction.","ev":"Bài kiểm tra MAPP (Đánh giá động lực và tiềm năng cá nhân) là một công cụ đánh giá nghề nghiệp toàn diện vượt ra ngoài việc kiểm tra kỹ năng đơn thuần. Nó khám phá động lực nội tại và khuynh hướng tự nhiên của bạn bằng cách yêu cầu bạn xếp hạng các khía cạnh khác nhau của công việc, nhiệm vụ hàng ngày và môi trường làm việc, giúp định hướng nghề nghiệp phù hợp với sự hài lòng lâu dài."},{"id":"SSA101_Q186","t":"Which level of the revised Bloom's cognitive taxonomy is considered the apex (highest level)?","o":[["A","Remembering",""],["B","Analyzing",""],["C","Evaluating",""],["D","Creating",""]],"a":"D","s":0,"e":"In the revised framework of Bloom's Taxonomy, the cognitive process of \"Creating\" represents the absolute maximum apex of human learning. It requires mastering all previous levels in order to seamlessly synthesize independently gathered elements into a completely new, coherent, and highly functional product or original idea.","ev":"Trong khuôn khổ sửa đổi của Phân loại Bloom, quá trình nhận thức \"Sáng tạo\" đại diện cho đỉnh cao tuyệt đối của khả năng học tập của con người. Nó đòi hỏi phải nắm vững tất cả các cấp độ trước đó để tổng hợp một cách liền mạch các yếu tố độc lập thành một sản phẩm hoặc ý tưởng gốc hoàn toàn mới, mạch lạc và có tính ứng dụng cao."},{"id":"SSA101_Q187","t":"Which type of thinking involves generating original and unconventional ideas?","o":[["A","Analytical Thinking",""],["B","Creative Thinking",""],["C","Critical Thinking",""],["D","Metacognition",""]],"a":"B","s":0,"e":"Creative thinking is a cognitive process focused strictly on innovation, originality, and unconventional perspective-taking. Unlike analytical thinking—which breaks down existing data—creative thinking encourages \"out-of-the-box\" brainstorming to synthesize entirely new ideas and design unique solutions to complex problems.","ev":"Tư duy sáng tạo là một quá trình nhận thức tập trung vào sự đổi mới, tính độc đáo và khả năng nhìn nhận vấn đề từ những góc độ khác biệt. Không giống như tư duy phân tích—vốn chia nhỏ dữ liệu hiện có—tư duy sáng tạo khuyến khích việc động não \"vượt ra ngoài khuôn khổ\" để tổng hợp những ý tưởng hoàn toàn mới và thiết kế các giải pháp độc đáo cho những vấn đề phức tạp."},{"id":"SSA101_Q188","t":"Approximately how many hours of reading per week might a full college course load require?","o":[["A","1–2 hours",""],["B","5–7 hours",""],["C","10–15 hours",""],["D","20+ hours",""]],"a":"C","s":0,"e":"Maintaining a full college course load is a significant commitment that demands extensive independent preparation outside the classroom. Because courses rely heavily on diverse academic materials, a student should realistically expect and schedule anywhere from 10 to 15 hours of rigorous assigned reading every single week just to keep pace with the curriculum.","ev":"Việc duy trì chương trình học đại học đầy đủ là một cam kết đáng kể đòi hỏi sự chuẩn bị độc lập sâu rộng ngoài giờ học. Vì các môn học phụ thuộc nhiều vào các tài liệu học thuật đa dạng, sinh viên nên dự kiến và sắp xếp khoảng 10 đến 15 giờ đọc tài liệu được giao mỗi tuần để theo kịp chương trình học."},{"id":"SSA101_Q189","t":"In personal finance, what are 'Liabilities'?","o":[["A","Your monthly income sources",""],["B","The interest earned on savings accounts",""],["C","Borrowed money, or debt, that you owe",""],["D","Your fixed monthly expenses like rent",""]],"a":"C","s":0,"e":"\"Liabilities\" are the direct opposite of assets; they represent binding financial debts, borrowed capital, or formal financial obligations that you legally owe to external entities or creditors. In a standard personal finance context, these typically manifest as high-interest credit card balances, longstanding student loans, auto financing, and home mortgages.","ev":"\"Nợ phải trả\" là hoàn toàn trái ngược với tài sản; chúng đại diện cho các khoản nợ tài chính ràng buộc, vốn vay hoặc các nghĩa vụ tài chính chính thức mà bạn phải trả theo pháp luật cho các tổ chức hoặc chủ nợ bên ngoài. Trong bối cảnh tài chính cá nhân, những khoản này thường thể hiện dưới dạng dư nợ thẻ tín dụng lãi suất cao, các khoản vay sinh viên, vay mua ô tô và vay thế chấp mua nhà."},{"id":"SSA101_Q190","t":"In the SIFT method used to evaluate the accuracy of information on the internet, what does the letter \"I\" stand for?","o":[["A","Identify the initial author.",""],["B","Investigate the source.",""],["C","Imitate the main claim.",""],["D","Inform the general public",""]],"a":"B","s":0,"e":"In the SIFT framework for evaluating digital information (Stop, Investigate the source, Find better coverage, Trace claims to original context), the \"I\" stands for \"Investigate the source.\" This crucial step demands that students pause reading the actual claim and instead rigorously research the author, publisher, and funding behind the website to determine their underlying credibility and potential biases.","ev":"Trong khuôn khổ SIFT để đánh giá thông tin kỹ thuật số (Dừng lại, Điều tra nguồn, Tìm kiếm thông tin đầy đủ hơn, Truy tìm nguồn gốc thông tin), chữ \"I\" viết tắt cho \"Điều tra nguồn\" (Investigate the source). Bước quan trọng này yêu cầu sinh viên tạm dừng việc đọc tuyên bố thực tế mà thay vào đó nghiên cứu kỹ tác giả, nhà xuất bản và nguồn tài trợ đứng sau trang web để xác định độ tin cậy và các thiên kiến tiềm ẩn."},{"id":"SSA101_Q191","t":"In the SMART acronym, what does 'T' usually stand for?","o":[["A","Technical.",""],["B","Tested.",""],["C","Time-bound.",""],["D","Theoretical.",""]],"a":"C","s":0,"e":"The \"T\" in the SMART goal-setting framework stands for \"Time-bound.\" This criterion emphasizes that an effective goal must have a clear, strictly defined deadline or timeframe, which creates a vital sense of urgency, prevents tasks from lingering indefinitely, and forces the individual to prioritize their daily schedule to achieve the goal on time.","ev":"Chữ \"T\" trong khung thiết lập mục tiêu SMART viết tắt cho \"Có thời hạn\" (Time-bound). Tiêu chí này nhấn mạnh rằng một mục tiêu hiệu quả phải có thời hạn hoặc khung thời gian rõ ràng, được xác định nghiêm ngặt, tạo ra cảm giác khẩn cấp cần thiết, ngăn chặn các nhiệm vụ bị trì hoãn vô thời hạn và buộc cá nhân phải ưu tiên lịch trình hàng ngày của mình để đạt được mục tiêu đúng hạn."},{"id":"SSA101_Q192","t":"What is the 'most important' financial rule when buying an education?","o":[["A","Attend the most expensive college you can get into",""],["B","Use credit cards to pay for tuition",""],["C","If you fail to plan, you are planning to fail",""]],"a":"C","s":0,"e":"Financing a college education is one of the largest investments a person will ever make. The principle \"if you fail to plan, you are planning to fail\" emphasizes that entering college without a rigid, highly proactive financial strategy to safely cover tuition and living expenses drastically increases the risk of crippling debt or being forced to abandon the degree.","ev":"Chi trả cho việc học đại học là một trong những khoản đầu tư lớn nhất mà một người sẽ thực hiện trong đời. Nguyên tắc \"nếu bạn không lập kế hoạch, bạn đang lên kế hoạch cho sự thất bại\" nhấn mạnh rằng việc vào đại học mà không có một chiến lược tài chính chủ động và chặt chẽ để trang trải học phí và chi phí sinh hoạt sẽ làm tăng đáng kể nguy cơ mắc nợ chồng chất hoặc phải bỏ dở việc học."},{"id":"SSA101_Q193","t":"What is the primary purpose of recapturing 'lost moments' in a schedule?","o":[["A","To increase the amount of time spent on social media",""],["B","To find time for napping during the day",""],["C","To repurpose that time for studying or completing productive tasks",""],["D","To allow for more travel time between classes",""]],"a":"C","s":0,"e":"In any daily schedule, there are inevitably \"lost moments\"—short 10-to-15-minute pockets of downtime, such as waiting for public transit or transitioning between classes. The primary purpose of identifying these moments is to proactively repurpose them for quick, productive study tasks (like reviewing flashcards), which ultimately maximizes your total daily productivity.","ev":"Trong bất kỳ lịch trình hàng ngày nào, chắc chắn sẽ có những \"khoảnh khắc bị lãng phí\"—những khoảng thời gian ngắn từ 10 đến 15 phút rảnh rỗi, chẳng hạn như chờ phương tiện công cộng hoặc di chuyển giữa các lớp học. Mục đích chính của việc nhận diện những khoảnh khắc này là chủ động tận dụng chúng cho các nhiệm vụ học tập nhanh chóng và hiệu quả (như ôn tập thẻ ghi nhớ), giúp tối đa hóa năng suất hàng ngày."},{"id":"SSA101_Q194","t":"According to the text, what is a 'bad practice' that leads to a 'debt hole'?","o":[["A","Tracking all spending and saving",""],["B","Spending money on wants instead of saving",""],["C","Knowing the difference between needs and wants",""],["D","Paying yourself first",""]],"a":"B","s":0,"tv":"Theo the text, what is a 'bad practice' that leads to a 'debt hole'","e":"A consistently poor financial practice is systematically prioritizing discretionary spending on non-essential \"wants\" before adequately funding essential savings. This behavior inevitably depletes cash reserves, leaving you highly vulnerable during unexpected emergencies and almost guaranteeing a reliance on high-interest credit that creates a deep, inescapable \"debt hole.\"","ev":"Một thói quen quản lý tài chính tồi thường xuyên là ưu tiên chi tiêu tùy ý vào những thứ \"mong muốn\" không thiết yếu trước khi dành đủ tiền tiết kiệm cho những nhu cầu thiết yếu. Hành vi này chắc chắn sẽ làm cạn kiệt quỹ dự phòng, khiến bạn dễ bị tổn thương trong các tình huống khẩn cấp và gần như dẫn đến việc phụ thuộc vào tín dụng lãi suất cao, tạo ra một \"hố nợ\" sâu khó thoát."},{"id":"SSA101_Q195","t":"During a class, what type of questions should a student ask to engage in critical thinking?","o":[["A","Questions about the format of the final exam",""],["B","Questions that distract the professor to use up class time",""],["C","Questions for clarification on areas that are confusing",""],["D","All of the above",""]],"a":"C","s":0,"tv":"During a class, what type of questions should a student ask to engage in tư duy phản biện?","e":"Critical thinking requires students to actively analyze, evaluate, and clarify what they do not yet understand instead of passively receiving information. Asking questions to clarify confusing parts helps students grasp the true essence of the knowledge.","ev":"Critical thinking (tư duy phản biện) đòi hỏi sinh viên phải chủ động phân tích, đánh giá và làm rõ những điều mình chưa hiểu, thay vì chỉ tiếp nhận thông tin một cách thụ động. Việc đặt câu hỏi để làm rõ các phần còn gây nhầm lẫn giúp hiểu đúng bản chất của kiến thức."},{"id":"SSA101_Q196","t":"What is the potential downside of creating overly complex mnemonics?","o":[["A","They are too easy to remember and thus boring.",""],["B","The reminder itself can become more difficult to remember than the information you are trying to relate it to",""],["C","They only work for math problems.",""],["D","Instructors generally forbid their use during exams.",""]],"a":"B","s":0,"e":"The entire functional purpose of a mnemonic device is to act as a simple cognitive shortcut to retrieve complex information. However, if the mnemonic itself is overly complicated or too long, your brain must exert more cognitive effort merely trying to remember the reminder than the actual underlying information, completely defeating its purpose as an effective study aid.","ev":"Mục đích chính của một phương pháp ghi nhớ là hoạt động như một lối tắt nhận thức đơn giản để truy xuất thông tin phức tạp. Tuy nhiên, nếu bản thân phương pháp ghi nhớ quá phức tạp hoặc quá dài, não bộ của bạn phải nỗ lực nhận thức nhiều hơn chỉ để cố gắng nhớ lại lời nhắc hơn là thông tin thực sự cần nhớ, điều này hoàn toàn làm mất đi tác dụng của nó như một công cụ hỗ trợ học tập hiệu quả."},{"id":"SSA101_Q197","t":"What is 'Information Literacy' for college students?","o":[["A","The ability to read very quickly",""],["B","Knowing how to use social media effectively",""],["C","The ability to weigh information, examine it for validity, and determine which information is appropriate to use",""],["D","Knowing how to build a website",""]],"a":"C","s":0,"tv":"What is 'năng lực thông tin' for college students?","e":"In the modern digital age, students are overwhelmed with easily accessible data from countless sources, many of which are unreliable or biased. Information literacy empowers students to critically evaluate these sources for credibility, expertly filter out misinformation, and ethically apply the most accurate and relevant evidence to support their academic arguments or solve complex problems.","ev":"Trong thời đại kỹ thuật số hiện đại, sinh viên bị choáng ngợp bởi lượng dữ liệu dễ dàng tiếp cận từ vô số nguồn, nhiều trong số đó không đáng tin cậy hoặc mang tính thiên vị. Năng lực thông tin trao quyền cho sinh viên đánh giá phản biện độ tin cậy của các nguồn này, lọc bỏ thông tin sai lệch và áp dụng một cách có đạo đức những bằng chứng chính xác, phù hợp nhất để hỗ trợ lập luận học thuật hoặc giải quyết các vấn đề phức tạp."},{"id":"SSA101_Q198","t":"What is a significant technological challenge related to the use of AI detection tools like Turnitin in higher education environments?","o":[["A","These tools have proven to be entirely flawless in distinguishing between human and machine writing, rendering traditional academic grading obsolete",""],["B","These tools are completely incapable of scanning any student essays that have been submitted through standard, school-sponsored learning management systems",""],["C","These tools face reliability issues as new software continually emerges to intentionally bypass detection by artificially mimicking human writing styles",""],["D","These tools deliberately alter the original text of student submissions to artificially inflate similarity scores and arbitrarily justify academic penalties",""]],"a":"C","s":0,"e":"The technological \"arms race\" between generative AI and AI detection tools creates severe reliability issues inside academic grading. As students deliberately adopt sophisticated \"humanizer\" software specifically engineered to artificially insert grammatical variability and bypass detection algorithms, the current scanning tools rapidly become outdated, regularly producing dangerous false positives and false negatives.","ev":"Cuộc \"chạy đua vũ trang\" công nghệ giữa trí tuệ nhân tạo tạo sinh (generative AI) và các công cụ phát hiện AI tạo ra những vấn đề nghiêm trọng về độ tin cậy trong việc chấm điểm học thuật. Khi sinh viên cố tình sử dụng các phần mềm \"nhân hóa\" tinh vi được thiết kế để chèn các biến thể ngữ pháp nhân tạo nhằm vượt qua thuật toán phát hiện, các công cụ quét hiện tại nhanh chóng trở nên lỗi thời và thường xuyên cho ra kết quả dương tính giả hoặc âm tính giả nguy hiểm."},{"id":"SSA101_Q199","t":"What is a major negative environmental impact of developing and training Large Language Models (like ChatGPT-4)?","o":[["A","The continuous execution of complex algorithms actively depletes the overall quality of biodiversity data stored in international environmental databases",""],["B","The physical process of collecting billions of data points causes severe noise pollution and habitat disruption at global server storage centers",""],["C","The training process requires continuous operation on specialized hardware for weeks, consuming massive electricity and creating a large carbon footprint",""],["D","The rapid advancement of models increases electronic waste exponentially due to constant, yearly server and hardware replacements",""]],"a":"C","s":0,"e":"Developing sophisticated AI models fundamentally requires immense computational power, achieved by running thousands of specialized high-performance GPUs continuously for weeks or months. This relentless processing consumes staggering, industrial-level amounts of electricity and generates massive heat, resulting in a tremendously large global carbon footprint and heavily straining local water resources for server cooling.","ev":"Việc phát triển các mô hình AI phức tạp về cơ bản đòi hỏi sức mạnh tính toán khổng lồ, đạt được bằng cách vận hành liên tục hàng nghìn GPU hiệu năng cao chuyên dụng trong nhiều tuần hoặc nhiều tháng. Quá trình xử lý không ngừng này tiêu thụ lượng điện năng khổng lồ ở quy mô công nghiệp và sinh ra lượng nhiệt lớn, dẫn đến dấu chân carbon toàn cầu cực lớn và gây áp lực nặng nề lên nguồn nước địa phương để làm mát máy chủ."},{"id":"SSA101_Q200","t":"What is the greatest risk to students' freedom of expression when universities implement \"AI surveillance\" on school-issued devices?","o":[["A","The students' devices may experience severe performance degradation and battery drain due to the constant running of background monitoring algorithms",""],["B","Students' search histories on sensitive topics (e.g., politics, mental health) could be tracked, creating a persistent fear of being criminalized or exposed",""],["C","A significant loss of diverse academic thinking because students are artificially restricted to only utilizing safe, school-recommended research databases",""],["D","The advanced surveillance algorithms cost too much to maintain, leading directly to increased tuition fees and financial burdens for marginalized students",""]],"a":"B","s":0,"e":"When universities implement pervasive algorithmic surveillance to monitor student activity, it completely strips away digital privacy. The greatest chilling effect is that students become terrified to research highly sensitive, personal, or controversial topics—such as mental health struggles, political activism, or reproductive rights—out of a legitimate fear of institutional backlash or criminalization.","ev":"Khi các trường đại học triển khai hệ thống giám sát thuật toán rộng khắp để theo dõi hoạt động của sinh viên, điều đó hoàn toàn tước đoạt quyền riêng tư kỹ thuật số. Tác động đáng sợ nhất là sinh viên trở nên sợ hãi khi tìm hiểu các chủ đề nhạy cảm, cá nhân hoặc gây tranh cãi—như sức khỏe tâm thần, hoạt động chính trị hay quyền sinh sản—vì lo sợ bị nhà trường trừng phạt hoặc hình sự hóa."},{"id":"SSA101_Q201","t":"What is the 'first year experience' described in the Chapter 1 outline?","o":[["A","A big party held at the end of the school year.",""],["B","A mandatory physical education course.",""],["C","A transitional experience that requires academic, cultural, emotional, financial, intellectual, and social adjustments.",""],["D","A period where grades do not count toward your transcript.",""]],"a":"C","s":0,"e":"The transition into higher education is not merely an academic shift; it represents a massive, total disruption of a student's previous life structure. The \"first year experience\" acknowledges that first-year students must simultaneously navigate enormous adjustments in academic rigor, cultural independence, emotional maturity, financial responsibility, and new complex social dynamics.","ev":"Việc chuyển tiếp lên bậc giáo dục đại học không chỉ đơn thuần là một sự thay đổi về mặt học thuật; nó còn là một sự xáo trộn lớn, hoàn toàn đối với cấu trúc cuộc sống trước đây của sinh viên. \"Trải nghiệm năm nhất\" thừa nhận rằng sinh viên năm nhất phải đồng thời thích nghi với những điều chỉnh to lớn về độ khó học thuật, sự độc lập văn hóa, sự trưởng thành cảm xúc, trách nhiệm tài chính và các mối quan hệ xã hội mới phức tạp."},{"id":"SSA101_Q202","t":"What is the benefit of practicing for interviews with career counselors?","o":[["A","They will tell you the exact questions employers will ask.",""],["B","They will hire you immediately.",""],["C","It helps you prepare mentally, gain experience, and learn how to communicate your skills effectively.",""],["D","It completely replaces submitting a resume.",""]],"a":"C","s":0,"e":"The professional interview process is fundamentally a high-pressure performance that requires specific communication techniques. Practicing with experienced career counselors provides a safe, constructive environment to emotionally prepare, refine body language, and learn how to articulate academic skills and past experiences into highly compelling, employable assets.","ev":"Quá trình phỏng vấn xin việc chuyên nghiệp về cơ bản là một cuộc thi dưới áp lực cao, đòi hỏi các kỹ thuật giao tiếp cụ thể. Việc luyện tập với các chuyên gia tư vấn nghề nghiệp giàu kinh nghiệm mang lại một môi trường an toàn, mang tính xây dựng để chuẩn bị tâm lý, hoàn thiện ngôn ngữ cơ thể và học cách diễn đạt các kỹ năng học thuật cùng kinh nghiệm đã qua thành những điểm mạnh thuyết phục nhà tuyển dụng."},{"id":"SSA101_Q203","t":"What is the average cost of tuition for local community colleges mentioned in the text?","o":[["A","About $50,000 per year.",""],["B","About $100,000 per year.",""],["C","The text does not give an exact figure, but emphasizes that attending a community college for the first two years can save a lot of money.",""],["D","Community colleges are completely free.",""]],"a":"C","s":0,"e":"While precise tuition figures fluctuate by region and institution, local community colleges consistently offer significantly lower credit costs compared to traditional four-year universities. By completing foundational general education requirements at a community college during the first two years of study, students can dramatically reduce their overall student debt burden.","ev":"Mặc dù con số học phí chính xác dao động theo khu vực và cơ sở đào tạo, các trường cao đẳng cộng đồng địa phương luôn có chi phí tín chỉ thấp hơn đáng kể so với các trường đại học bốn năm truyền thống. Bằng cách hoàn thành các môn giáo dục đại cương nền tảng tại trường cao đẳng cộng đồng trong hai năm đầu tiên, sinh viên có thể giảm đáng kể tổng gánh nặng nợ sinh viên của mình."},{"id":"SSA101_Q204","t":"What is the career planning step of 'Self-Awareness'?","o":[["A","Applying for as many jobs as possible.",""],["B","The process of exploring your personal interests, skills, values, and personality traits to find a suitable career path.",""],["C","Negotiating a starting salary.",""],["D","Writing a cover letter.",""]],"a":"B","s":0,"e":"Self-awareness serves as the absolute foundational bedrock of intelligent career planning. Before a student can effectively research job markets or safely select a major, they must deeply introspect to discover exactly what tasks they naturally excel at, what core values define their morality, and what specific environments they thrive in, ensuring their ultimate career choice is truly fulfilling.","ev":"Nhận thức về bản thân là nền tảng tuyệt đối của việc lập kế hoạch nghề nghiệp thông minh. Trước khi sinh viên có thể nghiên cứu thị trường việc làm một cách hiệu quả hoặc lựa chọn chuyên ngành phù hợp, họ phải tự nhìn nhận sâu sắc để khám phá những công việc mình làm tốt tự nhiên, những giá trị cốt lõi định hình đạo đức và môi trường cụ thể mà họ phát triển mạnh, đảm bảo lựa chọn nghề nghiệp cuối cùng thực sự viên mãn."},{"id":"SSA101_Q205","t":"What is one way a nurse might use 'Creative Thinking' on the job?","o":[["A","By ignoring hospital safety protocols.",""],["B","By prescribing untested medication.",""],["C","By finding an original and effective way to convey patient care information to other medical team members.",""],["D","By singing to the patient instead of giving an injection.",""]],"a":"C","s":0,"tv":"What is one way a nurse might use 'tư duy sáng tạo' on the job?","e":"While nursing critically relies on analytical adherence to strict safety protocols, creative thinking is essential for addressing unique human challenges. If a standard communication protocol is repeatedly failing to accurately convey nuances about a patient's condition, a creative nurse will purposefully design an entirely novel, highly efficient communication method to ensure the medical team operates flawlessly.","ev":"Mặc dù nghề điều dưỡng phụ thuộc rất nhiều vào việc tuân thủ nghiêm ngặt các quy trình an toàn, tư duy sáng tạo vẫn rất cần thiết để giải quyết những thách thức đặc thù của con người. Nếu một quy trình giao tiếp tiêu chuẩn liên tục không truyền đạt chính xác các sắc thái về tình trạng bệnh nhân, một điều dưỡng viên sáng tạo sẽ chủ động thiết kế một phương pháp giao tiếp hoàn toàn mới và hiệu quả cao để đảm bảo đội ngũ y tế phối hợp hoàn hảo."},{"id":"SSA101_Q206","t":"What is 'Monitoring' in the financial planning process?","o":[["A","Continually tracking your income, spending, and progress toward your financial goals.",""],["B","Watching the stock market daily.",""],["C","Letting the bank manage all your money.",""],["D","Setting a goal and never looking back.",""]],"a":"A","s":0,"e":"A financial plan is not a static document; it is a dynamic strategy that must adapt directly to reality. Monitoring requires the consistent, ongoing tracking of your daily financial behaviors to ensure your actual spending perfectly matches your projected budget, allowing you to instantly catch deviations and correct your course before missing major financial milestones.","ev":"Kế hoạch tài chính không phải là một văn bản tĩnh; đó là một chiến lược năng động phải thích ứng trực tiếp với thực tế. Việc theo dõi đòi hỏi sự giám sát liên tục, thường xuyên các hành vi tài chính hàng ngày của bạn để đảm bảo chi tiêu thực tế hoàn toàn phù hợp với ngân sách dự kiến, cho phép bạn ngay lập tức phát hiện những sai lệch và điều chỉnh hướng đi trước khi bỏ lỡ các cột mốc tài chính quan trọng."},{"id":"SSA101_Q207","t":"What is the 'Hidden Curriculum' as mentioned in the chapter outlines?","o":[["A","Courses not listed in the course catalog.",""],["B","Test answers hidden in the textbook.",""],["C","The unwritten, unspoken rules and expectations that students must follow to succeed in the college environment",""],["D","A secret club on campus.",""]],"a":"C","s":0,"e":"The \"Hidden Curriculum\" refers to the complex social and academic norms that are rarely explicitly taught but are absolutely crucial for survival in higher education. This includes understanding appropriate email etiquette with professors, knowing exactly when to utilize office hours, seamlessly navigating university bureaucracy, and mastering the unspoken expectations of independent study.","ev":"\"Chương trình học ẩn\" (Hidden Curriculum) đề cập đến các chuẩn mực xã hội và học thuật phức tạp hiếm khi được giảng dạy rõ ràng nhưng lại vô cùng quan trọng để tồn tại ở bậc đại học. Điều này bao gồm việc hiểu quy tắc viết email phù hợp với giảng viên, biết chính xác khi nào nên tận dụng giờ tiếp sinh viên (office hours), xử lý thủ tục hành chính đại học và nắm vững những kỳ vọng bất thành văn của việc tự học."},{"id":"SSA101_Q208","t":"What is the purpose of the 'Rethinking' exercises at the end of textbook chapters?","o":[["A","To provide extra homework assignments.",""],["B","To test your short-term memory.",""],["C","To revisit initial survey questions and reflect on how your understanding has changed after learning.",""],["D","To summarize the chapter instead of reading it.",""]],"a":"C","s":0,"e":"\"Rethinking\" exercises forcefully trigger a metacognitive review process, requiring the student to objectively compare their prior assumptions with their newly acquired knowledge. By directly assessing how deeply the chapter altered or enhanced their perspective, the student actively cements the information into long-term memory and verifies that the core learning objectives were successfully achieved.","ev":"Các bài tập \"Suy nghĩ lại\" (Rethinking) kích hoạt mạnh mẽ quá trình đánh giá siêu nhận thức, yêu cầu sinh viên so sánh một cách khách quan những giả định trước đây của họ với kiến thức mới thu được. Bằng cách đánh giá trực tiếp mức độ chương học đã thay đổi hoặc nâng cao góc nhìn của mình, sinh viên chủ động củng cố thông tin vào trí nhớ dài hạn và xác minh rằng các mục tiêu học tập cốt lõi đã đạt được thành công."},{"id":"SSA101_Q209","t":"What is the 'Occupational Outlook Handbook' used for?","o":[["A","To find the easiest classes in college.",""],["B","To research requirements for careers and identify fields with good job growth prospects.",""],["C","To apply for financial aid.",""],["D","To track your daily schedule.",""]],"a":"B","s":0,"e":"Produced by the government, the Occupational Outlook Handbook is an indispensable, data-driven tool for pragmatic career planning. It provides students with highly accurate statistical profiles on thousands of professions, detailing extreme specifics like median salaries, required educational degrees, daily responsibilities, and projected industry job growth rates over the next decade.","ev":"Được chính phủ biên soạn, Cẩm nang Triển vọng Nghề nghiệp là một công cụ không thể thiếu dựa trên dữ liệu giúp lập kế hoạch nghề nghiệp thực tiễn. Nó cung cấp cho sinh viên những hồ sơ thống kê có độ chính xác cao về hàng nghìn ngành nghề, nêu chi tiết các thông số cụ thể như mức lương trung vị, bằng cấp yêu cầu, trách nhiệm hàng ngày và tỷ lệ tăng trưởng việc làm dự kiến trong thập kỷ tới."},{"id":"SSA101_Q210","t":"What is the risk of setting goals that are not truly your own?","o":[["A","You will complete them too quickly.",""],["B","You will be accused of plagiarism.",""],["C","You will have very little motivation to achieve them because you don't actually care.",""],["D","Your academic advisor will not approve them.",""]],"a":"C","s":0,"e":"True, sustainable motivation must come from within; it requires a deep, personal connection to the ultimate outcome. If you adopt goals dictated entirely by societal pressure, family expectations, or peer influence, you will lack the crucial intrinsic drive required to push through inevitable academic hardships, making you highly susceptible to severe burnout and failure.","ev":"Động lực bền vững thực sự phải đến từ bên trong; nó đòi hỏi một sự kết nối sâu sắc, cá nhân với kết quả cuối cùng. Nếu bạn đặt ra những mục tiêu hoàn toàn do áp lực xã hội, kỳ vọng gia đình hoặc ảnh hưởng của bạn bè chi phối, bạn sẽ thiếu động lực nội tại cần thiết để vượt qua những khó khăn học tập không thể tránh khỏi, khiến bạn rất dễ bị kiệt sức và thất bại nghiêm trọng."},{"id":"SSA101_Q211","t":"What is one common reason people waste time during the day?","o":[["A","They have too many entertainment apps on their phones.",""],["B","Being constrained by schedules and lacking the awareness to effectively repurpose short \"waiting times\" (15-20 minutes).",""],["C","They sleep more than 8 hours a night.",""],["D","They spend too much time planning.",""]],"a":"B","s":0,"tv":"Một lý do phổ biến mà people waste time during the day là gì?","e":"Many students mistakenly believe that productive studying requires uninterrupted blocks of several hours, leading them to completely ignore shorter, 15-to-20-minute gaps between scheduled classes or appointments. This lack of awareness causes them to passively waste these highly valuable \"waiting times,\" significantly reducing their total daily productivity and forcing them to sacrifice their evening rest to catch up.","ev":"Nhiều sinh viên lầm tưởng rằng việc học tập hiệu quả đòi hỏi những khoảng thời gian liên tục kéo dài vài giờ, dẫn đến việc họ hoàn toàn bỏ qua những khoảng thời gian ngắn hơn từ 15 đến 20 phút giữa các tiết học hoặc cuộc hẹn. Sự thiếu nhận thức này khiến họ lãng phí một cách thụ động những \"thời gian chờ\" quý giá, làm giảm đáng kể năng suất hàng ngày và buộc phải hy sinh thời gian nghỉ ngơi buổi tối để học bù."},{"id":"SSA101_Q212","t":"What is the intended outcome of the 'After Class' task of testing yourself?","o":[["A","To start the studying process and assess whether you understand the material.",""],["B","To memorize the textbook word-for-word.",""],["C","To replace taking notes in class.",""],["D","To prepare for an immediate pop quiz.",""]],"a":"A","s":0,"e":"Self-testing immediately after a lecture acts as a highly effective diagnostic tool to measure your actual comprehension versus your assumed comprehension. By proactively challenging your memory without looking at your notes, you instantly identify which specific concepts you have mastered and which areas require immediate review, thereby launching a highly efficient study cycle.","ev":"Việc tự kiểm tra ngay sau bài giảng là một công cụ chẩn đoán cực kỳ hiệu quả để đo lường mức độ hiểu bài thực tế so với mức độ hiểu bài mà bạn cho là đúng. Bằng cách chủ động kiểm tra trí nhớ mà không nhìn vào ghi chú, bạn ngay lập tức xác định được những khái niệm nào mình đã nắm vững và những phần nào cần ôn tập ngay, qua đó khởi động một chu trình học tập hiệu quả cao."},{"id":"SSA101_Q213","t":"What is the primary benefit of being 'financially literate'?","o":[["A","It allows you to become a stockbroker",""],["B","It allows you to do more of what you want with your life by working hard, separating needs from wants, and avoiding debt pitfalls.",""],["C","It guarantees you will be rich immediately after college",""],["D","It eliminates the need to pay taxes",""]],"a":"B","s":0,"e":"The ultimate primary benefit of achieving strong financial literacy is the acquisition of total personal freedom. By deeply understanding how to budget effectively, separate fleeting desires from genuine needs, and aggressively avoid toxic debt pitfalls, you secure the financial stability necessary to confidently pursue your true life goals on your own terms.","ev":"Lợi ích quan trọng nhất của việc đạt được kiến thức tài chính vững chắc là sự tự do cá nhân tuyệt đối. Bằng cách hiểu sâu sắc cách lập ngân sách hiệu quả, phân biệt giữa những mong muốn nhất thời và nhu cầu thực sự, và chủ động tránh những cạm bẫy nợ nần, bạn sẽ đảm bảo được sự ổn định tài chính cần thiết để tự tin theo đuổi mục tiêu cuộc sống thực sự của mình."},{"id":"SSA101_Q214","t":"What is the 'Career Planning Cycle' used for?","o":[["A","To find a job immediately after high school",""],["B","To determine which professors are the easiest graders",""],["C","To apply concrete steps to figure out where you might fit into the work world and to reconsider your approach and progress",""],["D","To guarantee a high salary upon graduation",""]],"a":"C","s":0,"e":"The Career Planning Cycle is a dynamic, ongoing structured framework designed to guide professional development. It forces individuals to apply concrete, actionable steps to continuously assess their evolving skills, explore where they naturally fit into the modern work world, and regularly reconsider their trajectory to ensure long-term career satisfaction.","ev":"Chu trình lập kế hoạch nghề nghiệp là một khuôn khổ có cấu trúc, năng động và liên tục được thiết kế để hướng dẫn sự phát triển chuyên nghiệp. Nó buộc các cá nhân phải áp dụng các bước cụ thể, khả thi để liên tục đánh giá các kỹ năng đang phát triển của mình, khám phá vị trí phù hợp tự nhiên của họ trong thế giới công việc hiện đại và thường xuyên xem xét lại lộ trình để đảm bảo sự hài lòng nghề nghiệp lâu dài."},{"id":"SSA101_Q215","t":"What is the first step in identifying wasted time in a daily schedule?","o":[["A","Asking a friend to track your movements",""],["B","Immediately cutting out all leisure activities",""],["C","Analyzing your schedule to identify areas where you can recapture and repurpose time",""],["D","Downloading a complex time-management app",""]],"a":"C","s":0,"e":"You cannot fix a time management problem if you do not know where your time is actually going. Therefore, the crucial first step is to objectively record and analyze your current daily routine to pinpoint exactly where time is being inefficiently wasted on low-value activities so that you can consciously recapture and repurpose those hours.","ev":"Bạn không thể khắc phục vấn đề quản lý thời gian nếu bạn không biết thời gian của mình thực sự đang đi đâu. Do đó, bước đầu tiên quan trọng là ghi chép và phân tích một cách khách quan thói quen hàng ngày hiện tại để xác định chính xác nơi thời gian đang bị lãng phí vào các hoạt động ít giá trị, từ đó chủ động thu hồi và tái sử dụng những giờ đó."},{"id":"SSA101_Q216","t":"What is the 'simplest way' to manage time according to the text?","o":[["A","Use a digital calendar with automated reminders",""],["B","Multitask by doing several assignments at once",""],["C","Accurately plan how much time a task will take and set aside that amount of time",""],["D","Prioritize tasks based on which are the most enjoyable",""]],"a":"C","s":0,"e":"The simplest and most highly recommended way to manage time is realistic time blocking. By accurately estimating exactly how much time a specific task will take and formally dedicating that block of time to it in your schedule, you prevent tasks from overlapping, reduce the temptation to procrastinate, and ensure steady progress.","ev":"Cách đơn giản và được khuyên dùng nhất để quản lý thời gian là lập kế hoạch thời gian thực tế (time blocking). Bằng cách ước tính chính xác thời gian cần thiết cho một nhiệm vụ cụ thể và dành riêng khoảng thời gian đó cho nó trong lịch trình của bạn, bạn sẽ tránh được tình trạng chồng chéo công việc, giảm bớt cám dỗ trì hoãn và đảm bảo tiến độ ổn định."},{"id":"SSA101_Q217","t":"What is the recommended task regarding reading before a class session begins?","o":[["A","Read the summary of the chapter only to save time",""],["B","Wait until after the lecture to read so you understand the context better",""],["C","Read the assigned material to make the lecture and complex concepts easier to follow",""],["D","Skim the bolded terms and look at the graphics",""]],"a":"C","s":0,"e":"Reading the assigned material before a class session is fundamentally necessary to build a baseline understanding of the topic. This proactive approach ensures that when the instructor presents complex concepts, you already have a foundation. Consequently, the lecture becomes significantly easier to follow, allowing you to transition from simply trying to comprehend the basics to actively engaging with the material.","ev":"Đọc tài liệu được giao trước buổi học là điều cần thiết về mặt cơ bản để xây dựng nền tảng hiểu biết về chủ đề. Cách tiếp cận chủ động này đảm bảo rằng khi giảng viên trình bày các khái niệm phức tạp, bạn đã có sẵn nền tảng, nhờ đó bài giảng trở nên dễ theo dõi hơn nhiều và giúp bạn chuyển từ việc chỉ cố gắng hiểu kiến thức cơ bản sang tích cực tương tác với tài liệu."},{"id":"SSA101_Q218","t":"What was the primary ethical issue discovered in the AI-based recruiting tool that was implemented and subsequently scrapped by Amazon in 2018?","o":[["A","The system required candidates to pay exorbitant processing fees to access the portal, which severely exacerbated existing socioeconomic inequalities",""],["B","The system consistently downgraded the resumes of female candidates because it was trained on ten years of historically male-dominated data",""],["C","The system utilized unauthorized facial recognition algorithms to monitor candidates' expressions and reactions during the virtual interview process",""],["D","The system generated fabricated educational backgrounds for numerous applicants, leading to widespread hallucinations and false credential verifications",""]],"a":"B","s":0,"e":"Machine learning algorithms inevitably inherit the internal biases of their strictly historical training data. Because Amazon's AI recruiting tool was trained on ten years of historically male-dominated tech industry resumes, the software \"learned\" that male candidates were statistically preferable, resulting in the algorithm systematically downgrading and actively penalizing resumes submitted by highly qualified women.","ev":"Các thuật toán học máy chắc chắn thừa hưởng những thiên kiến nội tại từ dữ liệu huấn luyện mang tính lịch sử của chúng. Bởi vì công cụ tuyển dụng AI của Amazon được huấn luyện trên dữ liệu hồ sơ ngành công nghệ trong mười năm vốn do nam giới thống trị, phần mềm đã \"học\" rằng ứng viên nam được ưu tiên hơn về mặt thống kê, dẫn đến việc thuật toán hạ thấp và đánh giá bất lợi đối với hồ sơ của những phụ nữ có trình độ cao."},{"id":"SSA101_Q219","t":"What does the term \"Hallucinations\" in Large Language Models (LLMs) refer to?","o":[["A","The AI generating highly abstract, surreal, and unrealistic visual images when prompted to create realistic photographs",""],["B","Users becoming overly dependent on the software and holding unrealistic illusions about the true technological capabilities of AI",""],["C","The AI producing text responses that sound highly plausible but are actually factually incorrect or entirely fabricated by the system.",""],["D","The AI consistently misidentifying specific human faces or expressions when utilized in advanced facial recognition security tools",""]],"a":"C","s":0,"e":"Large Language Models function by probabilistically predicting the next word in a sequence based on vast training data, not by actually understanding factual reality. A \"hallucination\" occurs when the algorithm strings together highly confident, perfectly grammatical sentences that effectively fabricate historical events, fake academic citations, or entirely false information that sounds flawlessly plausible.","ev":"Các mô hình ngôn ngữ lớn hoạt động bằng cách dự đoán xác suất từ tiếp theo trong một chuỗi dựa trên dữ liệu huấn luyện khổng lồ, chứ không phải bằng cách thực sự hiểu thực tế khách quan. Hiện tượng \"ảo giác\" (hallucination) xảy ra khi thuật toán ghép nối những câu văn đúng ngữ pháp và đầy tự tin nhưng thực chất lại bịa đặt các sự kiện lịch sử, trích dẫn học thuật giả mạo hoặc thông tin hoàn toàn sai lệch nghe có vẻ rất hợp lý."},{"id":"SSA101_Q220","t":"What does 'true learning' mean beyond just earning high grades?","o":[["A","Getting a piece of paper that guarantees a job.",""],["B","Never making a mistake.",""],["C","It is a transformative process that expands your mind, challenges your identity, and helps you handle real-world situations.",""],["D","Memorizing every small detail in the textbook.",""]],"a":"C","s":0,"e":"While grades temporarily measure academic compliance, \"true learning\" permanently alters how a person interacts with the world. It involves developing highly adaptable critical thinking skills, confronting and adjusting personal biases, and synthesizing diverse knowledge to successfully navigate complex, unpredictable challenges in both your professional career and personal life.","ev":"Trong khi điểm số chỉ tạm thời đo lường sự tuân thủ chương trình học, \"việc học thực sự\" sẽ thay đổi vĩnh viễn cách một người tương tác với thế giới. Nó bao gồm việc phát triển các kỹ năng tư duy phản biện linh hoạt, đối mặt và điều chỉnh thiên kiến cá nhân, đồng thời tổng hợp kiến thức đa dạng để xử lý thành công những thách thức phức tạp, khó lường trong cả sự nghiệp lẫn đời sống cá nhân."},{"id":"SSA101_Q221","t":"What should a student do with their notes immediately after a class session?","o":[["A","Put them in a folder and do not look at them until the midterm",""],["B","Review and rewrite them, adding in any missing details or clarifications",""],["C","Type them out word-for-word to ensure they are neat",""],["D","Share them immediately with a classmate who missed the lecture",""]],"a":"B","s":0,"e":"Immediately after a class, while the lecture content is still fresh in your short-term memory, reviewing and rewriting your notes is critical. This practice allows you to spot gaps, fix unclear phrasing, and add valuable context that you mentally remember but didn't have time to write down, creating a highly reliable study resource for future exams.","ev":"Ngay sau giờ học, khi nội dung bài giảng vẫn còn mới mẻ trong trí nhớ ngắn hạn, việc xem lại và viết lại ghi chú là vô cùng quan trọng. Thói quen này giúp bạn phát hiện ra những lỗ hổng, sửa chữa cách diễn đạt chưa rõ ràng và bổ sung ngữ cảnh giá trị mà bạn nhớ trong đầu nhưng chưa kịp ghi lại, tạo thành tài liệu ôn tập đáng tin cậy cho các kỳ thi sau này."},{"id":"SSA101_Q222","t":"What should a student do with their resume throughout college?","o":[["A","Write it once in freshman year and never look at it again.",""],["B","Continuously update it as they acquire new Knowledge, Skills, Abilities (KSAs), and experiences.",""],["C","Copy a friend's resume.",""],["D","Wait until the day before graduation to start writing it.",""]],"a":"B","s":0,"e":"A resume is not a static historical document; it is a continuously evolving professional marketing tool. As students progress through college, they constantly acquire new Knowledge, Skills, Abilities (KSAs), leadership roles, and internship experiences, meaning their resume must be regularly updated to accurately reflect their growing value and readiness for the post-graduation job market.","ev":"Sơ yếu lý lịch không phải là một tài liệu lịch sử tĩnh; nó là một công cụ tiếp thị chuyên nghiệp liên tục phát triển. Khi sinh viên học tập trong suốt quá trình bậc đại học, họ liên tục tiếp thu Kiến thức, Kỹ năng, Khả năng (KSAs) mới, đảm nhận vai trò lãnh đạo và tích lũy kinh nghiệm thực tập, do đó hồ sơ phải được cập nhật thường xuyên để phản ánh chính xác giá trị và mức độ sẵn sàng cho thị trường lao động sau tốt nghiệp."},{"id":"SSA101_Q223","t":"Which of the following is a recommended visual technique for individuals attempting to identify hyper-realistic \"deep fake\" media?","o":[["A","Trusting the emotional resonance of the media content and relying exclusively on mainstream social media platforms for rapid, community-based fact-checking",""],["B","Searching for subtle inconsistencies in lighting, shadows, unnatural facial movements, mismatched lip-syncing, and irregular or absent blinking patterns",""],["C","Assuming that all digital videos featuring high-profile politicians or celebrities are inherently fabricated by advanced generative artificial intelligence algorithms",""],["D","Using strictly text-based large language models to analyze the video files and automatically generate a highly conclusive report on the media's authenticity",""]],"a":"B","s":0,"tv":"Lựa chọn nào sau đây là a recommended visual technique for individuals attempting to identify hyper-realistic \"deep fake\" media?","e":"While generative AI excels at replicating the broad strokes of a human face, it frequently struggles with precise physiological minutiae. To critically identify a \"deep fake,\" digital analysts are trained to systematically search for extremely subtle visual glitches: unnatural lighting artifacts, mismatched lip-syncing, anatomical irregularities, or the complete absence of normal human micro-expressions like blinking.","ev":"Mặc dù trí tuệ nhân tạo tạo sinh (generative AI) rất giỏi trong việc tái tạo những đường nét tổng thể của khuôn mặt người, nhưng nó thường gặp khó khăn với những chi tiết sinh lý chính xác. Để nhận diện một \"deep fake\", các nhà phân tích kỹ thuật số tìm kiếm những lỗi hình ảnh tinh vi như ánh sáng bất thường, khẩu hình không khớp, sự bất thường về giải phẫu hoặc việc thiếu hoàn toàn các biểu cảm tự nhiên như chớp mắt."},{"id":"SSA101_Q224","t":"Which of the following best describes the \"Monitoring\" phase in the Plan-Monitor-Evaluate model of metacognition?","o":[["A","You are continuously assessing what you have already learned, identifying what you do not yet know, and determining if your current study strategies are working effectively",""],["B","You are reflecting on how well you met your overall learning objectives after completely finishing a unit of study or receiving feedback from a recent course assignment",""],["C","You are deciding exactly what material you need to learn for an upcoming exam and selecting the specific active learning strategies you will use to master that material",""],["D","You are reviewing your final exam answers to compare them with the instructor's suggested answers to see which key components were entirely missed during the test",""]],"a":"A","s":0,"e":"Metacognitive monitoring is an active, ongoing, and highly critical self-assessment process that occurs simultaneously with studying. It requires the student to continuously test their own comprehension in real-time—identifying exactly what concepts they have successfully mastered and forcefully questioning whether their current study strategies are actually proving effective or if they need immediate adjustment.","ev":"Giám sát siêu nhận thức là một quá trình tự đánh giá chủ động, liên tục và vô cùng quan trọng diễn ra đồng thời với việc học tập. Nó đòi hỏi sinh viên phải liên tục kiểm tra khả năng hiểu bài của chính mình theo thời gian thực—xác định chính xác những khái niệm đã nắm vững và đánh giá xem các chiến lược học tập hiện tại có thực sự hiệu quả hay cần điều chỉnh ngay lập tức."},{"id":"SSA101_Q225","t":"How does 'Critical Thinking' assist a student in identifying exam material?","o":[["A","By asking the professor to reveal the test questions",""],["B","By using data (like careful class notes) and reasoning to deduce what core content the professor might include on the exam.",""],["C","By blindly guessing the questions.",""],["D","By only studying the hardest questions.",""]],"a":"B","s":0,"tv":"How does 'tư duy phản biện' assist a student in identifying exam material?","e":"Instead of passively trying to memorize the entire textbook, a critical thinker actively analyzes the instructor's behavior, lecture emphasis, repeated themes, and syllabus structure. By logically synthesizing these contextual clues, the student can highly accurately deduce the core concepts most likely to be tested, thereby optimizing their limited study time for maximum efficiency.","ev":"Thay vì thụ động cố gắng ghi nhớ toàn bộ sách giáo khoa, người tư duy phản biện chủ động phân tích hành vi của giảng viên, trọng tâm bài giảng, các chủ đề lặp đi lặp lại và cấu trúc chương trình học. Bằng cách tổng hợp hợp lý những manh mối ngữ cảnh này, sinh viên có thể suy luận khá chính xác các khái niệm cốt lõi có khả năng cao sẽ được kiểm tra, qua đó tối ưu hóa thời gian ôn tập để đạt hiệu quả cao nhất."},{"id":"SSA101_Q226","t":"How do academic advisors help with career exploration?","o":[["A","They guarantee you a job right after graduation.",""],["B","They help you set educational/career goals, choose a major, and connect you with career services.",""],["C","They write your resume and cover letter for you.",""],["D","They provide loans to pay for your tuition.",""]],"a":"B","s":0,"e":"Academic advisors act as vital strategic partners who deeply understand both the university's complex curriculum and the broader professional landscape. They can successfully translate your vague personal interests into concrete educational pathways, ensure you are taking the correct prerequisites for your desired field, and directly connect you with practical campus career resources.","ev":"Cố vấn học thuật đóng vai trò là đối tác chiến lược quan trọng, am hiểu sâu sắc cả chương trình giảng dạy phức tạp của trường đại học và bối cảnh nghề nghiệp rộng lớn hơn. Họ có thể chuyển hóa sở thích cá nhân mơ hồ của bạn thành lộ trình học tập cụ thể, đảm bảo bạn học đúng các môn tiên quyết cho lĩnh vực mong muốn và kết nối trực tiếp bạn với các nguồn lực hỗ trợ nghề nghiệp thiết thực tại trường."},{"id":"SSA101_Q227","t":"How does breaking a goal down into manageable tasks aid in completion?","o":[["A","Accomplishing the whole is easier when each part is tackled individually",""],["B","It makes the goal look larger and more impressive",""],["C","It allows you to procrastinate on the smaller parts",""],["D","It removes the need for a timeline",""]],"a":"A","s":0,"e":"Confronting a massive goal all at once can quickly lead to feelings of overwhelm and paralysis. By breaking the larger goal down into several smaller, highly manageable, and actionable tasks, you create a clear roadmap. Completing each individual step provides immediate psychological rewards and builds positive momentum, making the overarching goal feel significantly more achievable.","ev":"Đối mặt với một mục tiêu khổng lồ cùng một lúc có thể nhanh chóng dẫn đến cảm giác choáng ngợp và tê liệt. Bằng cách chia nhỏ mục tiêu lớn thành nhiều nhiệm vụ nhỏ hơn, dễ quản lý và có tính khả thi cao, bạn tạo ra một lộ trình rõ ràng. Việc hoàn thành từng bước riêng lẻ mang lại phần thưởng tâm lý tức thì và tạo động lực tích cực, khiến mục tiêu tổng thể trở nên khả thi hơn nhiều."},{"id":"SSA101_Q228","t":"How does annotating graphics differ from annotating text?","o":[["A","Graphics do not need any annotations.",""],["B","Deciphering graphics takes time, so you might want to create a copy before annotating to avoid making the information messy.",""],["C","Graphics should only be highlighted in yellow.",""],["D","Graphics should be memorized instead of annotated.",""]],"a":"B","s":0,"e":"Unlike standard text, academic graphics (such as complex charts, graphs, or anatomical diagrams) pack an immense amount of dense, interconnected data into a very small visual space. Because initial attempts to understand and label these visuals can easily become cluttered and illegible, making a separate copy to freely annotate ensures you reliably preserve the pristine original graphic for clear, long-term reference.","ev":"Khác với văn bản thông thường, các hình ảnh học thuật (như biểu đồ phức tạp, đồ thị hoặc sơ đồ giải phẫu) chứa một lượng dữ liệu khổng lồ, dày đặc và liên kết chặt chẽ trong một không gian thị giác rất nhỏ. Vì những nỗ lực ban đầu để hiểu và ghi chú lên các hình ảnh này dễ trở nên lộn xộn và khó đọc, việc tạo một bản sao riêng để thoải mái chú thích sẽ đảm bảo bạn giữ nguyên được bản gốc sạch sẽ để tham khảo lâu dài."},{"id":"SSA101_Q229","t":"How does 'Metacognition' improve problem-solving?","o":[["A","By increasing your reading speed.",""],["B","By practicing self-awareness, helping you recognize knowledge gaps and adjust problem-solving strategies promptly.",""],["C","By relying strictly on emotions to make decisions.",""],["D","By helping you rote-memorize faster.",""]],"a":"B","s":0,"tv":"How does 'Metacognition' improve giải quyết vấn đề?","e":"Because metacognition involves \"thinking about your thinking,\" it allows a student to objectively monitor their own thought processes while tackling a difficult problem. This acute self-awareness ensures that if a specific approach is clearly failing, the student instantly recognizes the impasse, abandons the ineffective method, and strategically pivots to a better solution rather than blindly wasting time.","ev":"Vì siêu nhận thức liên quan đến việc \"suy nghĩ về suy nghĩ của chính mình\", nó cho phép sinh viên theo dõi một cách khách quan quá trình tư duy của bản thân khi giải quyết một vấn đề khó. Sự tự nhận thức sắc bén này đảm bảo rằng nếu một cách tiếp cận rõ ràng đang thất bại, sinh viên ngay lập tức nhận ra bế tắc, từ bỏ phương pháp kém hiệu quả và chuyển sang giải pháp tốt hơn thay vì lãng phí thời gian."},{"id":"SSA101_Q230","t":"How can a balance sheet help a student in the future?","o":[["A","It helps balance their class schedule.",""],["B","It provides a comprehensive picture (\"snapshot\") of assets and liabilities, allowing them to track financial progress at a point in time.",""],["C","It automatically pays bills.",""],["D","It prevents students from getting into debt.",""]],"a":"B","s":0,"e":"A personal balance sheet is a vital financial diagnostic tool that explicitly lists everything a student owns (assets) versus everything they owe (liabilities) on a specific date. By regularly generating this objective \"snapshot,\" students can accurately measure exactly how much their net worth has grown, ensuring their long-term financial strategies are actually working.","ev":"Bảng cân đối tài chính cá nhân là một công cụ chẩn đoán tài chính quan trọng, liệt kê rõ ràng tất cả những gì sinh viên sở hữu (tài sản) so với tất cả những gì họ nợ (nợ phải trả) tại một ngày cụ thể. Bằng cách thường xuyên lập ra \"bức tranh tổng quan\" khách quan này, sinh viên có thể đo lường chính xác mức độ tăng trưởng giá trị tài sản ròng của mình, đảm bảo các chiến lược tài chính dài hạn thực sự hiệu quả."},{"id":"SSA101_Q231","t":"How can 15 to 20 minutes of 'waiting time' be repurposed effectively?","o":[["A","By being organized enough to complete short tasks or review notes during that brief period.",""],["B","By taking a quick nap to catch up on sleep.",""],["C","By scrolling social media to relax the brain.",""],["D","By finishing an entire research paper.",""]],"a":"A","s":0,"e":"If a student actively anticipates these inevitable short delays and keeps portable study materials (like flashcards, a reading assignment, or a digital checklist) easily accessible, they can immediately pivot to productivity. Repurposing these brief, unused pockets of time to complete small, discrete tasks prevents the accumulation of overwhelming workloads at the end of the day.","ev":"Nếu sinh viên chủ động lường trước những khoảng thời gian trì hoãn ngắn không thể tránh khỏi này và luôn chuẩn bị sẵn các tài liệu học tập mang theo bên mình (như thẻ ghi nhớ, bài đọc hoặc danh sách kiểm tra kỹ thuật số), họ có thể ngay lập tức chuyển sang làm việc hiệu quả. Tận dụng những khoảng thời gian rảnh ngắn ngủi này để hoàn thành các nhiệm vụ nhỏ giúp tránh tích tụ khối lượng công việc quá tải vào cuối ngày."},{"id":"SSA101_Q232","t":"How much can on-campus housing and meals add to the annual cost of college?","o":[["A","The exact cost is not stated, but the text recommends living at home (if possible) to save a significant amount of money.",""],["B","It is always cheaper than living at home.",""],["C","An extra $50,000 per year.",""],["D","Universities do not charge for room and board.",""]],"a":"A","s":0,"e":"On-campus room and board represent one of the largest hidden expenses in higher education, often doubling the base cost of tuition alone. The text pragmatically recommends that students live at home if logistically possible, as this entirely eliminates exorbitant dormitory and meal plan fees, saving them tens of thousands of dollars over the course of their degree.","ev":"Chi phí ăn ở trong ký túc xá là một trong những khoản chi phí ẩn lớn nhất trong giáo dục đại học, thường gấp đôi chi phí học phí cơ bản. Văn bản này đưa ra lời khuyên thực tế rằng sinh viên nên sống ở nhà nếu điều kiện cho phép, vì điều này sẽ loại bỏ hoàn toàn các khoản phí ký túc xá và ăn uống đắt đỏ, giúp họ tiết kiệm hàng chục nghìn đô la trong suốt quá trình học."},{"id":"SSA101_Q233","t":"How do supporters of generative AI justify the use of copyrighted works in training data under the \"fair use doctrine\"?","o":[["A","They argue that AI algorithms completely destroy the original market value of the copyrighted works, forcing the creation of entirely new markets",""],["B","They claim the use is \"non-consumptive\" because the tool learns syntax and context without reproducing the central elements of the original work",""],["C","They state that the original creators automatically forfeit their intellectual property rights once their works are uploaded to public internet servers",""],["D","They emphasize that the developers are utilizing the copyrighted materials exclusively for non-profit, government-sponsored educational programs",""]],"a":"B","s":0,"e":"Technology companies heavily argue that scraping copyrighted works to train AI fundamentally qualifies as a \"fair use\" exception. They legally claim the process is strictly \"non-consumptive\"; the AI is not inherently copying the original data to directly pirate it, but rather mathematically analyzing thousands of texts to learn the abstract concepts of syntax, grammar, and contextual relationships.","ev":"Các công ty công nghệ lập luận mạnh mẽ rằng việc thu thập dữ liệu từ các tác phẩm có bản quyền để huấn luyện AI về cơ bản thuộc phạm vi ngoại lệ \"sử dụng hợp lý\" (fair use). Họ khẳng định quá trình này hoàn toàn mang tính \"không tiêu thụ\" (non-consumptive); AI không sao chép dữ liệu gốc để vi phạm bản quyền mà phân tích toán học hàng nghìn văn bản để học các khái niệm trừu tượng về cú pháp, ngữ pháp và quan hệ ngữ cảnh."},{"id":"SSA101_Q234","t":"How can a student most effectively utilize a grading rubric to improve their assignment before submitting the final version to their online instructor?","o":[["A","The student should completely ignore the rubric until after receiving the final grade, using it only to argue for additional points if the instructor made a mistake",""],["B","The student should put themselves in the place of the instructor and grade their own drafted assignment according to the rubric criteria to identify missing elements",""],["C","The student should copy the exact phrasing found within the highest scoring column of the rubric and paste it directly into their assignment to guarantee top marks",""],["D","The student should only read the rubric after finishing the entire writing process to avoid feeling overwhelmed or restricted by the instructor's specific guidelines",""]],"a":"B","s":0,"e":"A grading rubric is essentially a detailed, highly transparent blueprint of exactly what the instructor expects to see in a flawless, top-tier assignment. By proactively adopting the precise perspective of the grader and rigorously evaluating your own rough draft against each specific rubric criterion before submission, you can systematically identify critical missing elements. This objective self-assessment allows you to confidently revise your work and maximize your final score before the teacher ever sees it.","ev":"Bảng tiêu chí chấm điểm (rubric) về cơ bản là một bản thiết kế chi tiết và minh bạch về những gì giảng viên kỳ vọng ở một bài tập xuất sắc. Bằng cách chủ động đặt mình vào vị trí người chấm và tự đánh giá bản nháp của mình theo từng tiêu chí cụ thể trước khi nộp, bạn có thể phát hiện có hệ thống những yếu tố còn thiếu, tự tin chỉnh sửa và tối đa hóa điểm số cuối cùng."},{"id":"SSA101_Q235","t":"Why is 'Evaluating' a necessary step in the financial planning process?","o":[["A","To judge other people's spending habits.",""],["B","To assess your current financial situation (e.g., income, expenses) before making a plan.",""],["C","To calculate bank interest rates.",""],["D","To decide which bank to choose.",""]],"a":"B","s":0,"tv":"Tại sao 'Evaluating' a necessary step in the financial planning process?","e":"You absolutely cannot chart a reliable course to a future financial goal if you do not know your precise starting point. The evaluation step requires a brutally honest audit of your current cash flow, existing debts, and monthly expenses, establishing the necessary factual baseline required to safely build a realistic, mathematically sound financial plan.","ev":"Bạn hoàn toàn không thể vạch ra một lộ trình đáng tin cậy để đạt được mục tiêu tài chính trong tương lai nếu không biết chính xác điểm xuất phát của mình. Bước đánh giá đòi hỏi một cuộc kiểm toán trung thực tuyệt đối về dòng tiền hiện tại, các khoản nợ hiện có và chi phí hàng tháng của bạn, thiết lập cơ sở thực tế cần thiết để xây dựng một kế hoạch tài chính thực tế và vững chắc."},{"id":"SSA101_Q236","t":"Why is it important to research 'job market trends' for a chosen major?","o":[["A","To find the easiest jobs to do.",""],["B","To ensure you are preparing for a growing and promising field, rather than a declining one.",""],["C","To know what clothes to wear to work.",""],["D","To guarantee a six-figure starting salary.",""]],"a":"B","s":0,"tv":"Tại sao it important to research 'job market trends' for a chosen major?","e":"An academic major is a massive investment of time and capital, so it must yield a viable return. Researching long-term job market trends ensures that the specific field you are intensely training for is actually experiencing sustained demand and economic growth, protecting you from graduating into a declining industry with zero realistic employment prospects.","ev":"Việc theo học một chuyên ngành học thuật đòi hỏi đầu tư rất lớn về thời gian và vốn, vì vậy nó phải mang lại lợi ích thiết thực. Nghiên cứu xu hướng thị trường việc làm dài hạn đảm bảo rằng lĩnh vực cụ thể mà bạn đang theo đuổi thực sự có nhu cầu ổn định và tăng trưởng kinh tế, giúp bạn tránh khỏi việc tốt nghiệp vào một ngành đang suy thoái với triển vọng việc làm bằng không."},{"id":"SSA101_Q237","t":"Why is it easy to forget why you set a long-term goal?","o":[["A","Because short-term memory erases long-term goals.",""],["B","Because it is easy to become mired in the drudgery of current difficult tasks and forget the initial reason.",""],["C","Because long-term goals are usually not SMART goals.",""],["D","Because friends and family often distract you.",""]],"a":"B","s":0,"tv":"Tại sao it easy to forget why you set a long-term goal?","e":"Long-term goals, by definition, require months or years of sustained effort, often involving highly repetitive or frustrating daily tasks. As a student becomes exhausted by immediate deadlines, stressful exams, and heavy reading loads, this relentless daily friction can easily obscure the overarching, inspirational \"big picture\" that initially motivated them to start their journey.","ev":"Theo định nghĩa, mục tiêu dài hạn đòi hỏi nhiều tháng hoặc nhiều năm nỗ lực bền bỉ, thường bao gồm các công việc hàng ngày lặp đi lặp lại hoặc gây nản lòng. Khi sinh viên kiệt sức vì những hạn chót sát nút, các kỳ thi căng thẳng và khối lượng bài đọc nặng nề, sự ma sát hàng ngày không ngừng nghỉ này có thể dễ dàng che khuất \"bức tranh lớn\" đầy cảm hứng ban đầu."},{"id":"SSA101_Q238","t":"Why is 'pulling an all-nighter' considered a poor planning method?","o":[["A","It ensures you have too much energy the next day",""],["B","It is the best way to utilize long-term memory",""],["C","It rarely produces the best work and is often a last-minute attempt to make up for poor planning",""],["D","It allows you to finish assignments early so you can socialize",""]],"a":"C","s":0,"tv":"Tại sao 'pulling an all-nighter' considered a poor planning method?","e":"An \"all-nighter\" is a universally recognized poor planning method because severe sleep deprivation drastically impairs critical cognitive functions, including memory retention, focus, and logical problem-solving. As a result, any academic work produced under these exhausting conditions is typically rushed, highly error-prone, and acts as an ineffective last-minute fix for poor time management.","ev":"Việc thức trắng đêm được công nhận rộng rãi là một phương pháp lập kế hoạch kém hiệu quả vì thiếu ngủ trầm trọng làm suy giảm đáng kể các chức năng nhận thức quan trọng, bao gồm ghi nhớ, tập trung và giải quyết vấn đề logic. Do đó, bất kỳ bài tập học thuật nào được tạo ra trong điều kiện kiệt sức này thường vội vàng, dễ mắc lỗi và chỉ là giải pháp chắp vá vào phút chót cho việc quản lý thời gian kém."},{"id":"SSA101_Q239","t":"Why is 'Visualizing the Results' considered an effective motivation strategy?","o":[["A","It helps you fall asleep faster after studying",""],["B","Keeping the benefits and end results in mind is extremely effective in keeping you motivated",""],["C","It allows you to skip the planning phase of goal setting",""],["D","It guarantees you will get an A in the class",""]],"a":"B","s":0,"tv":"Tại sao 'Visualizing the Results' considered an effective motivation strategy?","e":"\"Visualizing the Results\" is an incredibly powerful motivational technique because it directly links your current, often tedious work to a highly desirable future outcome. By vividly keeping the ultimate benefits—such as a degree or a dream career—at the forefront of your mind, you generate strong intrinsic motivation that helps you push through difficult periods and avoid burnout.","ev":"\"Hình dung kết quả\" là một kỹ thuật tạo động lực vô cùng mạnh mẽ bởi vì nó liên kết trực tiếp công việc hiện tại thường tẻ nhạt của bạn với một kết quả tương lai đáng mơ ước. Bằng cách luôn ghi nhớ sống động những lợi ích cuối cùng—như tấm bằng đại học hay sự nghiệp mơ ước—bạn tạo ra động lực nội tại mạnh mẽ giúp vượt qua giai đoạn khó khăn và tránh kiệt sức."},{"id":"SSA101_Q240","t":"Why is 'Learning About Yourself' considered a lifelong process in career planning?","o":[["A","Because career tests are unreliable",""],["B","Because knowing yourself as a professional by discovering interests, skills, and values is something everyone should do on an ongoing basis",""],["C","Because employers require you to retake personality tests every year",""],["D","Because it is required to maintain professional licensure",""]],"a":"B","s":0,"tv":"Tại sao 'Learning About Yourself' considered a lifelong process in career planning?","e":"\"Learning About Yourself\" is universally considered a lifelong process because human beings are highly dynamic. As you age and gain complex real-world experience, your core interests, professional skills, and personal values will inevitably shift. Regular self-reflection ensures that your long-term career choices continue to perfectly align with your current life stage.","ev":"\"Hiểu rõ bản thân\" được coi là một quá trình suốt đời bởi vì con người rất năng động. Khi bạn trưởng thành và tích lũy được nhiều kinh nghiệm thực tế phức tạp, sở thích cốt lõi, kỹ năng chuyên môn và giá trị cá nhân của bạn chắc chắn sẽ thay đổi. Việc thường xuyên tự nhìn nhận bản thân đảm bảo rằng những lựa chọn nghề nghiệp dài hạn của bạn tiếp tục phù hợp với giai đoạn cuộc sống hiện tại."},{"id":"SSA101_Q241","t":"Why is 'Information Literacy' essential for modern careers?","o":[["A","It allows you to read faster than everyone else.",""],["B","It is only required for IT workers.",""],["C","Workers are expected to be proficient, ethical users and producers of information to solve problems in a connected world.",""],["D","It helps you avoid using the internet.",""]],"a":"C","s":0,"tv":"Tại sao 'năng lực thông tin' essential for modern careers?","e":"In today's highly digitized knowledge economy, professionals are constantly bombarded with immense volumes of data. Employers absolutely demand workers who can not only quickly locate credible information but also ethically synthesize it, avoid intellectual property violations, and utilize that accurate data to safely and effectively solve complex organizational problems.","ev":"Trong nền kinh tế tri thức số hóa hiện nay, các chuyên gia liên tục phải đối mặt với khối lượng dữ liệu khổng lồ. Nhà tuyển dụng yêu cầu những người lao động không chỉ có thể nhanh chóng tìm thấy thông tin đáng tin cậy mà còn phải tổng hợp nó một cách có đạo đức, tránh vi phạm sở hữu trí tuệ và sử dụng dữ liệu chính xác để giải quyết các vấn đề phức tạp của tổ chức."},{"id":"SSA101_Q242","t":"Why is it important to bring the book and reading notes to every class session?","o":[["A","To prove to the instructor that you bought the book.",""],["B","To avoid having to listen to the lecture.",""],["C","To engage with the material, avoid distractions, and ask critical or clarifying questions.",""],["D","To read ahead for next week's class.",""]],"a":"C","s":0,"tv":"Tại sao it important to bring the book and reading notes to every class session?","e":"Bringing your annotated textbook and pre-class notes directly into the lecture hall tightly bridges the gap between independent study and active classroom learning. Having these physical resources readily available allows you to immediately reference confusing sections, verify facts as the professor speaks, stay heavily focused on the material, and formulate much deeper, context-rich questions.","ev":"Việc mang sách giáo khoa đã ghi chú và ghi chép trước giờ học trực tiếp vào giảng đường sẽ giúp thu hẹp khoảng cách giữa việc tự học và học tập tích cực trên lớp. Việc có sẵn các tài liệu này cho phép bạn tra cứu ngay các phần khó hiểu, kiểm chứng thông tin khi giảng viên nói, duy trì sự tập trung và đặt ra những câu hỏi sâu sắc hơn."},{"id":"SSA101_Q243","t":"Why is volunteering recommended during the 'Exploring Options' phase of career planning?","o":[["A","Because it pays a very high salary.",""],["B","Because it is required for graduation.",""],["C","Because it allows you to gain additional skills and real-world experience outside the classroom.",""],["D","Because it completely replaces the need for a college degree.",""]],"a":"C","s":0,"tv":"Tại sao volunteering recommended during the 'Exploring Options' phase of career planning?","e":"During the career exploration phase, students are still trying to determine their ideal professional fit. Volunteering provides a low-risk, hands-on opportunity to engage directly with an industry, allowing students to gain highly relevant real-world experience, develop practical new skills, and build professional networks outside the confines of a traditional academic classroom.","ev":"Trong giai đoạn tìm hiểu nghề nghiệp, sinh viên vẫn đang cố gắng xác định lĩnh vực chuyên môn phù hợp nhất với mình. Hoạt động tình nguyện mang đến cơ hội thực tiễn ít rủi ro để tương tác trực tiếp với một ngành nghề, giúp sinh viên tích lũy kinh nghiệm thực tế phù hợp, phát triển kỹ năng mới thiết thực và xây dựng mạng lưới quan hệ ngoài lớp học."},{"id":"SSA101_Q244","t":"Why should a student avoid taking 'short cuts' in the reading and note-taking cycle?","o":[["A","Because instructors will check your notebooks for a grade.",""],["B","Because each step is a building block in the continuous learning process, helping you become a stronger expert.",""],["C","Because taking shortcuts leads directly to academic suspension.",""],["D","Because reading is the only way to pass the course.",""]],"a":"B","s":0,"e":"Effective learning is not a simple transaction; it is a cumulative, structured cognitive process where surveying, reading, annotating, and reviewing interlock to build deep comprehension. Attempting to bypass these foundational steps—such as skimming without taking active notes—creates severe structural gaps in your knowledge base, ultimately guaranteeing poor performance when complex analysis is required on exams.","ev":"Học tập hiệu quả không phải là một giao dịch đơn giản; đó là một quá trình nhận thức tích lũy có cấu trúc, trong đó việc khảo sát, đọc, ghi chú và xem xét đan xen nhau để xây dựng sự hiểu biết sâu sắc. Việc cố gắng bỏ qua các bước nền tảng này—chẳng hạn như đọc lướt mà không ghi chú chủ động—sẽ tạo ra những lỗ hổng nghiêm trọng trong kiến thức nền tảng và dẫn đến kết quả kém khi thi."},{"id":"SSA101_Q245","t":"When creating a highly effective daily task list, which of the following practices is recommended for managing large and complex academic projects?","o":[["A","You should schedule the entire project to be completed in one extended work period to ensure that your train of thought remains entirely uninterrupted",""],["B","You should break the large project down into smaller, specific, and measurable tasks that can each be comfortably completed within a single hour or less",""],["C","You should prioritize the project only after all of your minor, less urgent tasks have been completed to clear your mind of any daily distractions",""],["D","You should leave the project off your daily task list entirely and instead rely strictly on the master semester schedule to track its eventual completion",""]],"a":"B","s":0,"e":"Confronting a massive academic project all at once can quickly lead to feelings of overwhelm, cognitive fatigue, and severe procrastination. By strategically breaking the larger project down into several smaller, highly specific, and measurable tasks that can be comfortably completed in an hour or less, you create a clear, actionable roadmap. This approach ensures steady, consistent daily progress while providing immediate psychological rewards as each individual step is checked off your list.","ev":"Đối mặt với một dự án học thuật khổng lồ cùng một lúc có thể nhanh chóng dẫn đến cảm giác choáng ngợp, mệt mỏi về nhận thức và trì hoãn nghiêm trọng. Bằng cách chia nhỏ dự án lớn thành nhiều nhiệm vụ nhỏ hơn, cụ thể và có thể đo lường được trong vòng một giờ trở xuống, bạn tạo ra một lộ trình rõ ràng, giúp duy trì tiến độ hàng ngày ổn định và mang lại cảm giác thành tựu khi hoàn thành từng bước."},{"id":"SSA101_Q246","t":"When approaching a scholarly journal article for a research project, what is the recommended first step to determine if the article is relevant to your work?","o":[["A","You should immediately read the discussion section in its entirety, as this section contains the most detailed and comprehensive explanation of the research findings",""],["B","You should carefully review the literature review section to gather historical background information and find older reference materials related to your specific topic",""],["C","You should begin by reading the abstract and the provided keywords to quickly decide if the subject matter directly aligns with your current research project's goals",""],["D","You should focus primarily on the methodology section to understand exactly how the researchers gathered their data and determine if their statistical analysis is flawed",""]],"a":"C","s":0,"e":"Scholarly journal articles are exceptionally dense, highly technical documents that can take hours to fully comprehend line-by-line. Because the academic research phase requires rapidly filtering through dozens of potential sources, immediately reading the strictly localized abstract and keywords provides a fast, highly concentrated summary of the entire study. This allows you to instantly determine if the authors' specific subject matter practically aligns with your own research goals before unnecessarily investing hours into reading their complex methodology.","ev":"Các bài báo khoa học trên tạp chí chuyên ngành là những tài liệu cực kỳ cô đọng và mang tính kỹ thuật cao, có thể mất nhiều giờ để đọc hiểu từng dòng. Vì giai đoạn nghiên cứu đòi hỏi phải lọc nhanh hàng chục nguồn tài liệu tiềm năng, việc đọc ngay phần tóm tắt (abstract) và từ khóa (keywords) sẽ cung cấp bản tóm tắt nhanh chóng, giúp bạn xác định ngay bài báo có phù hợp với mục tiêu nghiên cứu của mình hay không."},{"id":"SSA101_Q247","t":"When sending an email to an online instructor, which of the following practices is recommended to ensure the communication is professional and effective?","o":[["A","You should include an informative subject line, use a formal professional greeting, and break your message into multiple paragraphs to ensure optimal readability",""],["B","You should keep the message as short as humanly possible, omitting any greetings or sign-offs, to ensure you do not waste the instructor's highly valuable time",""],["C","You should expect a response within a few hours and send an immediate follow-up email on the exact same day if you have not yet received the requested information",""],["D","You should write in a casual and conversational tone, using abbreviations and slang, to quickly build a friendly, relaxed, and approachable relationship with them",""]],"a":"A","s":0,"e":"Because online instructors manage hundreds of digital communications daily, adhering to strict professional email etiquette is absolutely essential for receiving timely and helpful responses. Including a highly specific subject line ensures your email is prioritized and routed correctly, while utilizing a formal greeting and structuring your request into clear, readable paragraphs demonstrates deep respect for the instructor's time and professional boundaries, fostering a highly positive academic relationship.","ev":"Vì giảng viên trực tuyến phải xử lý hàng trăm thư điện tử mỗi ngày, việc tuân thủ nghiêm ngặt các quy tắc ứng xử email chuyên nghiệp là vô cùng cần thiết để nhận được phản hồi kịp thời và hữu ích. Việc đặt tiêu đề email cụ thể, sử dụng lời chào trang trọng và chia nội dung thành các đoạn văn rõ ràng thể hiện sự tôn trọng thời gian của giảng viên và xây dựng mối quan hệ học thuật tích cực."},{"id":"SSA101_Q248","t":"How does 'Analytical Thinking' differ from 'Creative Thinking'?","o":[["A","Analytical thinking is only for math; creative thinking is only for art",""],["B","Analytical thinking involves systematically breaking a problem into component parts for analysis, while creative thinking involves generating original and unconventional ideas",""],["C","Analytical thinking is optional; creative thinking is mandatory",""],["D","Analytical thinking creates clutter; creative thinking organizes it",""]],"a":"B","s":0,"tv":"How does 'tư duy phân tích' differ from 'tư duy sáng tạo'?","e":"Analytical thinking is a logical, convergent process where you systematically deconstruct complex information into smaller, manageable parts to understand how they function together and identify errors. In contrast, creative thinking is a divergent process that encourages looking fully outside existing frameworks to brainstorm unconventional ideas and synthesize completely original solutions that did not previously exist.","ev":"Tư duy phân tích là một quá trình logic, hội tụ, trong đó bạn phân tích một cách có hệ thống thông tin phức tạp thành các phần nhỏ hơn để hiểu cách chúng hoạt động cùng nhau và phát hiện lỗi. Ngược lại, tư duy sáng tạo là một quá trình phân kỳ khuyến khích việc suy nghĩ vượt ra ngoài khuôn khổ hiện có để đề xuất những ý tưởng độc đáo và tổng hợp các giải pháp hoàn toàn mới."},{"id":"SSA101_Q249","t":"According to the text, what is the link between financial health and personal life?","o":[["A","Financial health only determines what car you drive.",""],["B","Studies show that people with stronger finances are healthier, happier, have better marriages, and better cognitive functioning.",""],["C","There is no connection at all.",""],["D","Having strong finances guarantees you will never be stressed.",""]],"a":"B","s":0,"tv":"Theo the text, what is the link between financial health and personal life","e":"Financial instability is universally recognized as one of the leading causes of chronic, systemic stress in adults. Extensive sociological studies confirm that individuals who maintain strong financial health experience dramatically lower stress levels, leading directly to reduced anxiety, better cognitive functioning, healthier physical bodies, and significantly more stable marriages.","ev":"Tình trạng bất ổn tài chính được công nhận rộng rãi là một trong những nguyên nhân hàng đầu gây ra căng thẳng mãn tính, mang tính hệ thống ở người trưởng thành. Nhiều nghiên cứu xã hội học sâu rộng xác nhận rằng những người duy trì sức khỏe tài chính tốt có mức độ căng thẳng thấp hơn đáng kể, dẫn đến giảm lo âu, chức năng nhận thức tốt hơn, cơ thể khỏe mạnh hơn và hôn nhân ổn định hơn."},{"id":"SSA101_Q250","t":"According to the foundational definitions of AI literacy, how do \"Neural Networks\" primarily function within deep learning systems?","o":[["A","They explicitly program computers to perform a singular task by utilizing rigid rules and completely eliminating the need for ongoing inference.",""],["B","They consist of interconnected nodes organized in layers that process inputs through activation functions to recognize complex patterns",""],["C","They focus exclusively on the direct interaction between advanced computer systems and human language through semantic analysis",""],["D","They generate novel content such as text, imagery, and audio by searching the internet for real-time data and synthesizing it instantly",""]],"a":"B","s":0,"tv":"Theo the foundational definitions of năng lực AI, how do \"Neural Networks\" primarily function within deep learning systems","e":"Neural networks are architecturally inspired by the human brain; they absolutely do not rely on rigid, explicit programming. Instead, they consist of thousands of interconnected artificial \"nodes\" stacked in deep, hierarchical layers that process massive datasets through mathematical activation functions, allowing the system to independently recognize complex visual, audio, or textual patterns.","ev":"Mạng nơ-ron được lấy cảm hứng từ cấu trúc não người; chúng hoàn toàn không dựa vào lập trình cứng nhắc, tường minh. Thay vào đó, chúng bao gồm hàng nghìn \"nút\" nhân tạo được kết nối với nhau thành các lớp phân tầng sâu, xử lý tập dữ liệu lớn thông qua các hàm kích hoạt toán học, cho phép hệ thống tự động nhận diện các mẫu hình ảnh, âm thanh hoặc văn bản phức tạp."},{"id":"SSA101_Q251","t":"According to the Ebbinghaus Forgetting Curve research, what is the most effective method for successfully storing information in long-term memory?","o":[["A","Passively re-reading notes and highlighting textbooks continuously for several hours immediately preceding the scheduled academic examination",""],["B","Utilizing artificial intelligence chatbots to write detailed essays so the student can focus their mental energy entirely on other difficult subjects",""],["C","Actively recalling the information at strategically spaced intervals just before the brain would otherwise naturally forget the educational material",""],["D","Relying exclusively on intrinsic motivation and high attainment value to organically ensure the brain permanently encodes the new information",""]],"a":"C","s":0,"tv":"Theo the Ebbinghaus Forgetting Curve research, what is the most effective method for successfully storing information in trí nhớ dài hạn","e":"The Ebbinghaus Forgetting Curve proves that the human brain naturally discards new information exponentially fast if it is not actively reinforced. The scientifically proven method to effectively combat this is \"spaced repetition\"—the practice of deliberately forcing your brain to actively recall the material at increasingly longer intervals, which permanently encodes the data into long-term memory.","ev":"Đường cong quên lãng Ebbinghaus chứng minh rằng bộ não con người tự nhiên loại bỏ thông tin mới với tốc độ cấp số nhân nếu nó không được củng cố một cách chủ động. Phương pháp khoa học được chứng minh để chống lại điều này là \"lặp lại ngắt quãng\" (spaced repetition)—thực hành chủ động buộc não bộ nhớ lại tài liệu theo những khoảng thời gian dài dần, giúp mã hóa vĩnh viễn dữ liệu vào trí nhớ dài hạn."},{"id":"SSA101_Q252","t":"According to the guidelines for giving positive feedback to a team member, which of the following approaches is the most appropriate and effective?","o":[["A","You should completely avoid asking for permission before delivering the feedback, because waiting might cause the individual to forget the specific negative event",""],["B","You should compare the team member's performance directly to other highly successful students in the group so they have a clear and measurable standard to aim for",""],["C","You should begin and end the discussion by highlighting what is working well, focus on specific behaviors that can be changed, and avoid using absolutes like \"never.\"",""],["D","You should point out everything that went wrong all at once, using generalized statements about their overall attitude to ensure they understand the severe impact",""]],"a":"C","s":0,"tv":"Theo the guidelines for giving positive feedback to a team member, which of the following approaches is the most appropriate and effective","e":"Delivering critical feedback within a collaborative group setting requires immense emotional intelligence to ensure the message is ultimately constructive rather than destructive. By actively \"sandwiching\" the needed corrective behavior between genuine highlights of what the teammate is currently doing well, you significantly lower their natural defensive barriers. Furthermore, explicitly avoiding harsh absolutes like \"always\" or \"never\" ensures the feedback remains entirely focused on actionable improvement rather than feeling like a personal attack.","ev":"Việc đưa ra phản hồi mang tính xây dựng trong môi trường làm việc nhóm đòi hỏi trí tuệ cảm xúc lớn để đảm bảo thông điệp mang tính xây dựng chứ không phải phá hoại. Bằng cách kết hợp góp ý cần cải thiện vào giữa những điểm tích cực mà đồng đội đang làm tốt và tránh các từ tuyệt đối như \"luôn luôn\" hay \"không bao giờ\", bạn giảm bớt rào cản phòng thủ và giúp phản hồi tập trung vào việc cải thiện hành vi cụ thể."},{"id":"SSA101_Q253","t":"According to Bloom's Taxonomy, which of the following activities best demonstrates a student operating at the \"Analyze\" level of the cognitive domain?","o":[["A","The student interprets the meaning of new information by translating it entirely into their own words and linking it to their personal background knowledge",""],["B","The student takes information apart to explore relationships, continuously asks \"why,\" and examines how various independent components interact to form a complete system",""],["C","The student uses the knowledge they have previously acquired to perform required tasks and resolve similar problems within a completely new practical situation",""],["D","The student integrates various pieces of familiar information together to generate a completely new product, perspective, or theoretical framework from the available data",""]],"a":"B","s":0,"tv":"Theo Bloom's Taxonomy, which of the following activities best demonstrates a student operating at the \"Analyze\" level of the cognitive domain","e":"Reaching the \"Analyze\" cognitive level requires moving significantly beyond mere comprehension or basic application. At this advanced tier, the student systematically breaks down complex information into its fundamental underlying components, constantly questions the \"why,\" and critically examines exactly how those distinct individual parts logically interact to construct the broader organizational system.","ev":"Để đạt được trình độ nhận thức \"Phân tích\" cần phải vượt qua sự hiểu biết đơn thuần hoặc ứng dụng cơ bản. Ở cấp độ nâng cao này, sinh viên phân tích một cách có hệ thống thông tin phức tạp thành các thành phần cơ bản, liên tục đặt câu hỏi \"tại sao\" và xem xét kỹ cách các bộ phận riêng lẻ tương tác hợp lý để tạo nên hệ thống tổng thể."},{"id":"SSA101_Q254","t":"Before class, why is it useful to record questions about the assigned reading?","o":[["A","To show the professor you did the work",""],["B","To establish a purpose for reading and to identify areas that need clarification during the lecture",""],["C","To avoid having to take notes during class",""],["D","To memorize the textbook verbatim",""]],"a":"B","s":0,"e":"Actively writing down questions before a lecture forces your brain to engage deeply with the assigned text rather than reading it passively. This practice explicitly identifies your specific knowledge gaps, providing a clear, targeted purpose for listening during class and ensuring you know exactly what concepts to ask the professor to clarify.","ev":"Việc chủ động ghi lại các câu hỏi trước khi nghe giảng sẽ buộc não bộ của bạn phải tương tác sâu sắc với nội dung bài giảng thay vì chỉ đọc một cách thụ động. Cách làm này giúp bạn xác định rõ những lỗ hổng kiến thức cụ thể, tạo mục đích rõ ràng cho việc lắng nghe trong lớp và đảm bảo bạn biết chính xác những khái niệm nào cần hỏi giảng viên để làm rõ."},{"id":"SSA101_Q255","t":"Based on the study by Liang et al. (2023), which group of students is at the highest risk of being falsely accused by \"AI detectors\"?","o":[["A","Students possessing advanced English writing skills and an exceptionally rich vocabulary",""],["B","Minority students who lack digital literacy and have never previously utilized any AI tools",""],["C","Students currently majoring in Computer Science, engineering, or other technology fields",""],["D","Students who are non-native English writers demonstrating lower grammatical variability",""]],"a":"D","s":0,"e":"Because AI text detectors scan for characteristics like low sentence complexity and highly predictable grammatical patterns (low \"perplexity\"), non-native English speakers are disproportionately flagged. These students naturally write with a tighter, more formulaic vocabulary and less structural variability, inadvertently triggering the algorithms and placing them at severe risk of unjust academic penalties.","ev":"Vì các công cụ nhận diện văn bản bằng AI quét các đặc điểm như độ phức tạp câu thấp và các mẫu ngữ pháp dễ đoán (độ \"khó hiểu\" thấp), nên người viết tiếng Anh không phải là người bản ngữ bị gắn cờ với tỷ lệ cao bất cân xứng. Những sinh viên này thường viết với vốn từ vựng khuôn mẫu hơn và ít biến thể cấu trúc, vô tình kích hoạt thuật toán và đối mặt nguy cơ bị phạt học thuật oan uổng."},{"id":"SSA101_Q256","t":"Define the student term 'pulling an all-nighter'.","o":[["A","Spending the entire night socializing with friends in the dorms",""],["B","Going without sleep for the entire night to use that time to finish an assignment",""],["C","Sleeping for more than 12 hours to catch up on rest",""],["D","Working a late-night shift at a part-time job",""]],"a":"B","s":0,"e":"\"Pulling an all-nighter\" refers strictly to the detrimental practice of skipping a full night's sleep to continuously focus on studying or finishing an assignment. It is usually a desperate measure taken by students who have failed to manage their time effectively and have procrastinated to the point where they have no other available hours to meet a strict deadline.","ev":"\"Thức trắng đêm\" thực chất là hành động tai hại khi bỏ qua cả đêm ngủ để tập trung học tập hoặc hoàn thành bài tập. Đây thường là biện pháp tuyệt vọng của những sinh viên không quản lý thời gian hiệu quả và trì hoãn đến mức không còn thời gian nào khác để hoàn thành đúng hạn."},{"id":"SSA101_Q257","t":"During the \"Storming\" phase of Tuckman's Team Development model, what interpersonal and task-related behaviors are a team most likely to experience?","o":[["A","The members establish base-level expectations, identify common similarities, develop initial trust, and depend heavily on the team leader for overall project direction",""],["B","The members encounter anxiety regarding power and control, express differing opinions, challenge leadership, and potentially form small cliques or experience personal conflicts",""],["C","The members successfully negotiate their specific roles, build strong mutual appreciation, establish open feedback channels, and commit to the shared goals of the team",""],["D","The members operate extremely efficiently with high motivation, share leadership roles based on individual strengths, and take tremendous pride in their collective success",""]],"a":"B","s":0,"e":"The \"Storming\" phase is the highly turbulent, yet entirely necessary, second stage of successful team development. Because initial politeness transitions into actual work, team members inevitably encounter anxiety regarding power dynamics, clash over conflicting leadership styles, express wildly differing opinions, and potentially fracture into defensive cliques as they aggressively attempt to establish control and boundaries.","ev":"Giai đoạn \"xung đột\" (Storming) là giai đoạn thứ hai đầy biến động nhưng hoàn toàn cần thiết cho sự phát triển thành công của nhóm. Bởi vì sự lịch sự ban đầu chuyển sang công việc thực tế, các thành viên không tránh khỏi lo âu về quyền lực, va chạm phong cách lãnh đạo, bày tỏ ý kiến trái chiều và có thể hình thành phe nhóm phòng thủ khi cố gắng thiết lập quyền kiểm soát."},{"id":"SSA101_Q258","t":"Define 'Metacognition'.","o":[["A","The process of thinking about how other people think",""],["B","A type of rapid memorization technique",""],["C","The process of thinking about how you think, including planning, tracking, and assessing your own understanding",""],["D","A method for analyzing statistical data",""]],"a":"C","s":0,"e":"Metacognition is formally defined as \"thinking about thinking.\" It is a vital higher-order cognitive skill where a student takes an objective step back to consciously plan their learning strategies, actively track their current level of comprehension, and honestly assess their own academic understanding to adjust their study habits for maximum efficiency.","ev":"Siêu nhận thức được định nghĩa chính thức là \"suy nghĩ về suy nghĩ\". Đó là một kỹ năng nhận thức bậc cao thiết yếu, trong đó học sinh thực hiện một bước lùi khách quan để lên kế hoạch chiến lược học tập, chủ động theo dõi mức độ hiểu bài hiện tại và tự đánh giá trung thực khả năng tiếp thu để điều chỉnh thói quen học tập đạt hiệu quả tối đa."},{"id":"SSA101_Q259","t":"Define 'Net Worth' in the context of personal finance.","o":[["A","The total amount of income you earn in a year",""],["B","The value of your most expensive asset (like a car or house)",""],["C","The total measure of your wealth, calculated by subtracting what you owe from what you own",""],["D","The amount of money you have in your checking account",""]],"a":"C","s":0,"e":"In structured personal finance, \"Net Worth\" is universally considered the single most accurate and comprehensive indicator of an individual's total financial health. It measures the absolute value of your holistic wealth by taking the total monetary value of everything you own and systematically subtracting the total burden of everything you owe.","ev":"Trong tài chính cá nhân có cấu trúc, \"Giá trị tài sản ròng\" được coi là chỉ số chính xác và toàn diện nhất về sức khỏe tài chính tổng thể của một cá nhân. Nó đo lường giá trị tuyệt đối của toàn bộ tài sản bằng cách lấy tổng giá trị tiền tệ của tất cả những gì bạn sở hữu và trừ đi một cách có hệ thống gánh nặng của tất cả những gì bạn nợ."},{"id":"SSA101_Q260","t":"During the \"Norming\" stage of Tuckman's Team Development model, what characteristic behaviors and group dynamics are the team members most likely to exhibit?","o":[["A","The team members begin to experience high anxiety regarding power and control, express differing opinions, challenge leadership, and potentially form exclusive cliques",""],["B","The team members operate extremely efficiently with high motivation, share leadership roles based on individual strengths, and take tremendous pride in collective success",""],["C","The team members establish base-level expectations, identify common similarities, develop initial trust, and depend heavily on the designated team leader for direction",""],["D","The team members reach consensus on roles and problem-solving processes, build mutual trust, provide objective feedback, and commit strongly to shared collective goals.",""]],"a":"D","s":0,"e":"Following the highly turbulent and heavily conflicted \"Storming\" phase, the \"Norming\" stage represents a critical structural stabilization period where the group finally begins functioning as a cohesive unit. During this vital stage, team members successfully negotiate their specific operational roles, freely establish universally accepted problem-solving processes, and build deep mutual trust. This newly established harmony allows them to provide highly objective feedback and strongly commit themselves entirely to their shared collective goals instead of individual egos.","ev":"Sau giai đoạn \"Xung đột\" đầy biến động và mâu thuẫn, giai đoạn \"Ổn định\" (Norming) là thời kỳ ổn định cấu trúc quan trọng khi nhóm bắt đầu hoạt động như một khối thống nhất. Trong giai đoạn này, các thành viên thương lượng thành công vai trò cụ thể, thiết lập quy trình giải quyết vấn đề chung, xây dựng lòng tin sâu sắc, đưa ra phản hồi khách quan và cam kết mạnh mẽ với mục tiêu chung của tập thể."},{"id":"SSA101_Q261","t":"In the context of 'Knowing Yourself' for time management, how does fatigue affect study?","o":[["A","It makes you read faster.",""],["B","It helps your brain absorb information automatically.",""],["C","If you are tired, your attention and retention will be much poorer than if you were well-rested.",""],["D","It prevents test anxiety.",""]],"a":"C","s":0,"tv":"In the context of 'Knowing Yourself' for quản lý thời gian, how does fatigue affect study?","e":"The human brain relies entirely on adequate rest to process, encode, and permanently store complex new information. When a student attempts to study while severely fatigued, their brain's cognitive bandwidth is drastically reduced, meaning their ability to maintain active attention plummets and long-term memory retention becomes almost mathematically impossible.","ev":"Não bộ con người hoàn toàn phụ thuộc vào sự nghỉ ngơi đầy đủ để xử lý, mã hóa và lưu trữ lâu dài những thông tin mới phức tạp. Khi một học sinh cố gắng học tập trong tình trạng mệt mỏi nghiêm trọng, khả năng nhận thức của não bộ sẽ giảm mạnh, dẫn đến khả năng duy trì sự tập trung giảm sút và việc ghi nhớ lâu dài trở nên gần như bất khả thi."},{"id":"SSA101_Q262","t":"In personal finance, what are 'Assets'?","o":[["A","The valuable things you own, such as earnings, savings, and investments",""],["B","The money you owe to banks or credit card companies",""],["C","Your monthly variable expenses",""],["D","The taxes deducted from your paycheck",""]],"a":"A","s":0,"e":"In the realm of personal finance, \"Assets\" refer strictly to measurable resources or items of significant economic value that you own outright or tightly control. Because they hold objective value, assets—which include cash savings, investments, real estate, and valuable physical property—can be reliably liquidated or leveraged to generate future financial benefits.","ev":"Trong lĩnh vực tài chính cá nhân, \"Tài sản\" được hiểu chính xác là các nguồn lực có thể đo lường được hoặc các vật phẩm có giá trị kinh tế đáng kể mà bạn sở hữu hoàn toàn hoặc kiểm soát chặt chẽ. Bởi vì chúng có giá trị khách quan, tài sản—bao gồm tiền tiết kiệm, đầu tư, bất động sản và tài sản vật chất có giá trị—có thể được thanh lý hoặc sử dụng để tạo ra lợi ích tài chính trong tương lai."},{"id":"SSA101_Q263","t":"In the context of AI-assisted educational assessments, how is \"Criterion Validity\" formally defined by the scientific evaluation community?","o":[["A","It assesses whether the AI tool truly measures the underlying theoretical concept or specific academic trait that it was originally intended to measure",""],["B","It examines whether the content of the AI assessment comprehensively covers the entire mathematical or literary range of the subject being evaluated",""],["C","It evaluates whether the overall user interface of the AI tool appears friendly and intuitively aligned with the superficial goals of the standardized test",""],["D","It involves directly comparing the specific results generated by the AI assessment against other proven, established measures or actual real-world outcomes",""]],"a":"D","s":0,"e":"In psychometric testing and educational evaluation, criterion validity is incredibly specific: it determines how well the results of an assessment predict or align with an external, already-established standard of success. Therefore, to ensure an AI grading tool is valid, developers must directly compare its automated scores against proven human evaluations or actual real-world student outcomes.","ev":"Trong kiểm tra tâm lý và đánh giá giáo dục, tính hiệu lực theo tiêu chí (criterion validity) xác định mức độ chính xác của kết quả đánh giá trong việc dự đoán hoặc phù hợp với một tiêu chuẩn thành công đã được thiết lập sẵn từ bên ngoài. Do đó, để đảm bảo công cụ chấm điểm AI hợp lệ, nhà phát triển phải so sánh trực tiếp điểm số tự động của nó với đánh giá của con người hoặc kết quả thực tế của sinh viên."},{"id":"SSA101_Q264","t":"In the SQ3R strategic reading method, what specific actions should a student take during the \"Recite\" (or second \"R\") phase?","o":[["A","The student should skim the learning objectives, read the chapter summary, and review the end-of-chapter study questions to get a general overview of the text",""],["B","The student should create a list of \"who, what, where, when, and why\" questions based directly on the primary headings found throughout the chapter text",""],["C","The student should read the text continuously without pausing until they have located all the specific answers to the questions they formulated in the previous step",""],["D","The student should say the answer to their question out loud and then write it down in their notes using their own personal words and phrasing",""]],"a":"D","s":0,"e":"The SQ3R reading strategy (Survey, Question, Read, Recite, Review) is meticulously designed to maximize advanced reading comprehension and long-term retention. During the \"Recite\" phase, actively saying the answer out loud and then manually writing it down in your own entirely personal phrasing forces your brain to deeply process the information rather than just passively scanning it. This crucial step immediately tests your real understanding and securely encodes the newly acquired knowledge into your memory.","ev":"Chiến lược đọc SQ3R (Khảo sát, Đặt câu hỏi, Đọc, Tóm tắt, Ôn tập) được thiết kế tỉ mỉ để tối đa hóa khả năng đọc hiểu nâng cao và ghi nhớ lâu dài. Trong giai đoạn \"Tóm tắt\" (Recite), việc chủ động nói to câu trả lời rồi tự viết lại bằng ngôn từ của riêng mình buộc não bộ phải xử lý sâu thông tin, kiểm tra ngay mức độ hiểu thực sự và mã hóa kiến thức vào trí nhớ."},{"id":"SSA101_Q265","t":"In the context of financial goals, what does it mean to 'align personal and financial goals'?","o":[["A","Recognizing that personal behaviors have financial consequences and planning your finances to support what you want to achieve in life.",""],["B","Putting all your money into a savings account.",""],["C","Borrowing as much money as possible to fund your personal lifestyle.",""],["D","Choosing a career based solely on salary.",""]],"a":"A","s":0,"e":"Money is not an end in itself; it is simply a tool used to facilitate your desired lifestyle. Aligning these goals means deeply understanding that your daily financial habits directly dictate your ability to achieve major personal milestones—like traveling, buying a home, or retiring comfortably—and deliberately structuring your budget to prioritize funding those specific aspirations.","ev":"Tiền bạc không phải là mục đích tự thân; nó chỉ đơn giản là một công cụ để hỗ trợ lối sống mà bạn mong muốn. Việc điều chỉnh các mục tiêu này có nghĩa là hiểu sâu sắc rằng thói quen tài chính hàng ngày của bạn trực tiếp quyết định khả năng đạt được các cột mốc cá nhân lớn—như du lịch, mua nhà hoặc nghỉ hưu thoải mái—và chủ động lập ngân sách để ưu tiên tài trợ cho những khát vọng đó."},{"id":"SSA101_Q266","t":"In the cases of Ellen Rae and Kris Kashtanova, why did the U.S. Copyright Office grant limited copyright to Rae but completely deny Kashtanova?","o":[["A","Because Rae used a text-generating AI (ChatGPT) while Kashtanova used an image-generating AI (Midjourney)",""],["B","Because Rae significantly shifted, arranged, and manipulated the AI-generated outputs, while Kashtanova simply used the raw AI images with minor editing.",""],["C","Because Rae transparently declared her use of AI tools from the very beginning of the process, whereas Kashtanova deliberately attempted to hide her use of the software.",""],["D","Because ChatGPT allows commercial rights, whereas Midjourney does not.",""]],"a":"B","s":0,"e":"Under current U.S. Copyright guidelines, the core doctrine demands a sufficient amount of human authorship to grant legal protection. The Copyright Office completely denied Kashtanova because her AI-generated images were simply raw outputs with minimal editing, whereas Rae successfully proved she engaged in extensive, highly transformational human manipulation and substantial arrangement of the AI's generated elements.","ev":"Theo hướng dẫn hiện hành về bản quyền của Hoa Kỳ, nguyên tắc cốt lõi đòi hỏi phải có đủ sự can thiệp của con người để được bảo hộ pháp lý. Văn phòng Bản quyền đã hoàn toàn từ chối Kashtanova vì hình ảnh do AI tạo ra của cô chỉ là sản phẩm thô với chỉnh sửa tối thiểu, trong khi Rae đã chứng minh được sự thao tác và sắp xếp mang tính chuyển đổi sâu rộng của con người đối với các yếu tố do AI tạo ra."},{"id":"SSA101_Q267","t":"In the 'Seven Ways to Stay Motivated', why is 'Rewarding Yourself' important?","o":[["A","It allows you to spend more money.",""],["B","Humans are motivated by rewards, so rewarding yourself for a job well done helps maintain motivation and avoid procrastination.",""],["C","It replaces the need for setting long-term goals.",""],["D","It guarantees you will get an A in the class.",""]],"a":"B","s":0,"e":"Human psychology is fundamentally driven by positive reinforcement; completing difficult or tedious academic tasks safely drains our willpower if it is not adequately replenished. By scheduling intentional, meaningful rewards after intense study sessions, you create a powerful neurological incentive that actively combats the temptation to procrastinate and helps sustain long-term academic endurance.","ev":"Tâm lý con người về cơ bản được thúc đẩy bởi sự củng cố tích cực; việc hoàn thành các nhiệm vụ học tập khó khăn hoặc tẻ nhạt sẽ làm cạn kiệt ý chí của chúng ta nếu không được bổ sung đầy đủ. Bằng cách lên lịch những phần thưởng có ý nghĩa sau các buổi học căng thẳng, bạn tạo ra động lực thần kinh mạnh mẽ giúp chống lại sự trì hoãn và duy trì sức bền học tập lâu dài."},{"id":"SSA101_Q268","t":"Within the Community of Inquiry (CoI) model, what is the primary function of \"Social Presence\" in an online learning environment?","o":[["A","It requires the instructor to curate the course content carefully and design meaningful activities that will lead students toward professional and intellectual development",""],["B","It demands that learners maintain a continuous process of critical thinking to construct new knowledge through direct interaction with the provided course materials",""],["C","It creates a safe and supportive communication environment where students feel trusted enough to express their personal ideas and collaborate with their classmates",""],["D","It involves the instructor directly answering student questions during office hours and challenging the students' assumptions to help them grow in their given field",""]],"a":"C","s":0,"e":"The Community of Inquiry model asserts that effective online learning is impossible without genuine human connection. Social presence represents the ability of participants to project their actual personal characteristics into the digital space, creating a highly empathetic, safe, and deeply supportive environment where students feel emotionally secure enough to openly express ideas, take academic risks, and freely collaborate.","ev":"Mô hình Cộng đồng Tìm tòi khẳng định rằng việc học trực tuyến hiệu quả là không thể thiếu sự kết nối thực sự giữa người với người. Sự hiện diện xã hội thể hiện khả năng của người tham gia trong việc bộc lộ cá tính thực sự vào không gian số, tạo ra một môi trường đồng cảm, an toàn và hỗ trợ sâu sắc để sinh viên tự tin bày tỏ ý tưởng, chấp nhận rủi ro học thuật và tự do hợp tác."},{"id":"SSA101_Q269","t":"According to the text, what plays a central role in developing an effective identity as an online learner?","o":[["A","Time management skills",""],["B","Information management",""],["C","Social networking",""],["D","Memorization techniques",""]],"a":"B","s":0,"tv":"Theo the text, what plays a central role in developing an effective identity as an online learner"},{"id":"SSA101_Q270","t":"Which of the following is NOT mentioned as a key benefit of using an online notebook like OneNote or Evernote?","o":[["A","Synchronize notes across multiple devices",""],["B","Clip and save relevant information from web sources",""],["C","Automatically grade assignments",""],["D","Store PDFs and course documents for long-term access",""]],"a":"C","s":0,"tv":"Điều nào sau đây KHÔNG phải là mentioned as a key benefit of using an online notebook like OneNote or Evernote?"},{"id":"SSA101_Q271","t":"Why might online learners experience information overload?","o":[["A","Too few digital resources are available",""],["B","The large volume of readings and abundance of digital resources",""],["C","Lack of internet connection",""],["D","Limited course materials provided by instructors",""]],"a":"B","s":0},{"id":"SSA101_Q272","t":"In online learning, the role of the instructor is best described as:","o":[["A","The central figure who determines all content and direction",""],["B","A guide who directs students toward learning experiences aligned with their goals",""],["C","The person solely responsible for grading",""],["D","Someone who replaces peer support entirely",""]],"a":"B","s":0},{"id":"SSA101_Q273","t":"Which skill is NOT listed as a core skill for self-directed (independent) learning?","o":[["A","Define clear learning goals",""],["B","Seek necessary support when required",""],["C","Memorize all lecture slides word-for-word",""],["D","Choose learning strategies that support personal understanding",""]],"a":"C","s":0},{"id":"SSA101_Q274","t":"Metacognition is best defined as:","o":[["A","Memorizing facts quickly",""],["B","Thinking about your thinking",""],["C","Group discussion skills",""],["D","Using advanced software tools",""]],"a":"B","s":0},{"id":"SSA101_Q275","t":"In the Plan-Monitor-Evaluate model, the \"Monitoring\" stage primarily involves:","o":[["A","Setting initial learning goals",""],["B","Asking \"How am I doing at learning this?\"",""],["C","Reflecting after receiving final grades",""],["D","Choosing which course to enroll in",""]],"a":"B","s":0},{"id":"SSA101_Q276","t":"Which question is an example from the \"Evaluating\" stage of the Plan-Monitor-Evaluate model?","o":[["A","What do I need to learn?",""],["B","How am I going to learn the material?",""],["C","Did I learn the material effectively?",""],["D","What remains unclear right now?",""]],"a":"C","s":0},{"id":"SSA101_Q277","t":"According to Bloom's Taxonomy, which level comes immediately after \"Understanding\"?","o":[["A","Remembering",""],["B","Applying",""],["C","Analyzing",""],["D","Creating",""]],"a":"B","s":0,"tv":"Theo Bloom's Taxonomy, which level comes immediately after \"Understanding\""},{"id":"SSA101_Q278","t":"A question such as \"What is the definition of global warming?\" belongs to which level of Bloom's Taxonomy?","o":[["A","Understanding",""],["B","Applying",""],["C","Remembering",""],["D","Evaluating",""]],"a":"C","s":0},{"id":"SSA101_Q279","t":"Which type of question is associated with the \"Analyze\" level of Bloom's Taxonomy?","o":[["A","What is the definition of…?",""],["B","What is the relationship between… and …?",""],["C","What are my own examples of…?",""],["D","What will happen if temperatures continue to rise?",""]],"a":"B","s":0},{"id":"SSA101_Q280","t":"An \"Evaluate\" level question typically includes judgment using criteria such as:","o":[["A","What are the steps to…?",""],["B","Effective or ineffective? Why?",""],["C","How does the process occur?",""],["D","Who discovered…?",""]],"a":"B","s":0},{"id":"SSA101_Q281","t":"The \"Create\" level of Bloom's Taxonomy involves:","o":[["A","Simply listing facts",""],["B","Generating new ideas or establishing new connections",""],["C","Explaining in your own words",""],["D","Comparing two theories",""]],"a":"B","s":0},{"id":"SSA101_Q282","t":"Which reading strategy is recommended depending on the objective of the reading activity?","o":[["A","Always doing close reading for every text",""],["B","Skimming, focusing on key sections, or close reading",""],["C","Only reading summaries written by others",""],["D","Ignoring the purpose and reading everything fully",""]],"a":"B","s":0},{"id":"SSA101_Q283","t":"The text suggests that university-level learning especially emphasizes:","o":[["A","Memorization of all details",""],["B","Higher-order thinking skills (applying, analyzing, evaluating, creating)",""],["C","Passive listening only",""],["D","Copying notes from classmates",""]],"a":"B","s":0},{"id":"SSA101_Q284","t":"According to the text, which stage of team development is often misunderstood as dysfunction but is actually a normal part?","o":[["A","Forming",""],["B","Storming",""],["C","Norming",""],["D","Performing",""]],"a":"B","s":0,"tv":"Theo the text, which stage of team development is often misunderstood as dysfunction but is actually a normal part"},{"id":"SSA101_Q285","t":"In the \"Forming\" stage, which characteristic is NOT typically present?","o":[["A","Low commitment to the team",""],["B","Unclear roles and responsibilities",""],["C","High trust among members",""],["D","Lack of group history",""]],"a":"C","s":0},{"id":"SSA101_Q286","t":"During the \"Storming\" stage, what tends to increase among team members?","o":[["A","Trust and appreciation",""],["B","Conflict and competition",""],["C","Efficient operations",""],["D","Shared leadership",""]],"a":"B","s":0},{"id":"SSA101_Q287","t":"Which action step is recommended to move from \"Norming\" to \"Performing\"?","o":[["A","Define the team mission and goals",""],["B","Encourage shared leadership and responsibility",""],["C","Clarify roles during initial meetings",""],["D","Actively reinforce positive behavior to reduce conflict",""]],"a":"B","s":0},{"id":"SSA101_Q288","t":"In the Community of Inquiry framework, what are the two key roles learners assume?","o":[["A","Teaching presence and content creation",""],["B","Maintaining cognitive presence and developing social presence",""],["C","Instructor guidance and peer competition",""],["D","Memorization and individual testing",""]],"a":"B","s":0},{"id":"SSA101_Q289","t":"Cognitive presence in a learning community primarily involves:","o":[["A","Using emoticons to express emotions",""],["B","An ongoing process of critical thinking and constructing new knowledge",""],["C","Focusing only on individual exams",""],["D","Avoiding discussions with peers",""]],"a":"B","s":0},{"id":"SSA101_Q290","t":"Social presence is supported online by strategies such as:","o":[["A","Ignoring group work",""],["B","Using emoticons to convey nuances and emotions",""],["C","Limiting communication to the instructor",""],["D","Focusing solely on task completion",""]],"a":"B","s":0},{"id":"SSA101_Q291","t":"Which of the following is NOT one of the five basic elements of effective teamwork mentioned in the text?","o":[["A","Positive interdependence",""],["B","Individual accountability",""],["C","Group processing",""],["D","Financial incentives",""]],"a":"D","s":0,"tv":"Điều nào sau đây KHÔNG phải là one of the five basic elements of effective teamwork mentioned in the text?"},{"id":"SSA101_Q292","t":"Positive interdependence means that team members believe:","o":[["A","Individual success is possible without group success",""],["B","They are linked together in a shared outcome; success is mutual",""],["C","Only the leader is responsible for results",""],["D","Competition among members drives performance",""]],"a":"B","s":0},{"id":"SSA101_Q293","t":"What does \"group processing\" involve at the end of a working period?","o":[["A","Ignoring past performance",""],["B","Evaluating the group's functioning and identifying improvements",""],["C","Assigning blame to individuals",""],["D","Focusing only on final grades",""]],"a":"B","s":0},{"id":"SSA101_Q294","t":"In the \"Performing\" stage, teams demonstrate:","o":[["A","High dependency on the leader",""],["B","A strong \"we\" orientation and superior performance",""],["C","Frequent unresolved conflicts",""],["D","Unclear shared goals",""]],"a":"B","s":0},{"id":"SSA101_Q295","t":"When planning for successful teamwork, what should teams do in the \"Forming\" stage regarding interpersonal tasks?","o":[["A","Express differences aggressively",""],["B","Initiate contact, build connections, and develop trust",""],["C","Delegate all tasks immediately",""],["D","Focus only on project deadlines",""]],"a":"B","s":0},{"id":"SSA101_Q296","t":"A team charter, as mentioned for effective communication, typically includes commitments to:","o":[["A","Blame individuals for problems",""],["B","Respect, active listening, and constructive feedback",""],["C","Avoid conflict at all costs",""],["D","Work independently without discussion",""]],"a":"B","s":0},{"id":"SSA101_Q297","t":"In the framework for working together, a \"shared vision\" is described as:","o":[["A","A past-oriented summary of achievements",""],["B","A future-oriented statement of purpose aligned with members' values",""],["C","An administrative job description",""],["D","A list of unrelated personal goals",""]],"a":"B","s":0},{"id":"SSA101_Q298","t":"Continuous improvement in teamwork is achieved through:","o":[["A","Large, drastic changes only",""],["B","Small, incremental changes with planning, implementation, and verification",""],["C","Avoiding any evaluation of progress",""],["D","Focusing solely on individual rewards",""]],"a":"B","s":0},{"id":"SSA101_Q299","t":"According to the text, building an effective relationship with instructors primarily supports:","o":[["A","Avoiding all course assignments",""],["B","Success in an online learning environment",""],["C","Reducing the need for feedback",""],["D","Limiting communication to email only",""]],"a":"B","s":0,"tv":"Theo the text, building an effective relationship with instructors primarily supports:"},{"id":"SSA101_Q300","t":"Why is it important to understand the purpose behind learning activities designed by the instructor?","o":[["A","To skip unnecessary readings",""],["B","To increase motivation, improve focus, and stay aligned with course expectations",""],["C","To memorize content faster",""],["D","To avoid participating in discussions",""]],"a":"B","s":0,"tv":"Tại sao it important to understand the purpose behind learning activities designed by the instructor?"},{"id":"SSA101_Q301","t":"Which of the following is recommended as a way to engage through direct interaction with instructors?","o":[["A","Ignoring office hours completely",""],["B","Taking advantage of face-to-face meetings or online office hours",""],["C","Only contacting instructors after the course ends",""],["D","Relying solely on classmates for clarification",""]],"a":"B","s":0,"tv":"Lựa chọn nào sau đây là recommended as a way to engage through direct interaction with instructors?"},{"id":"SSA101_Q302","t":"The text suggests using email to contact instructors because it is considered:","o":[["A","An informal and casual tool",""],["B","A professional communication tool",""],["C","Unnecessary in online courses",""],["D","Only for submitting late assignments",""]],"a":"B","s":0},{"id":"SSA101_Q303","t":"What is the main benefit of carefully reviewing instructor feedback on assignments?","o":[["A","To argue against the grade received",""],["B","To identify areas for improvement and support continuous skill development",""],["C","To avoid future assignments",""],["D","To compare feedback with classmates only",""]],"a":"B","s":0},{"id":"SSA101_Q304","t":"In an online course, the instructor's \"teaching presence\" primarily involves:","o":[["A","Avoiding all student questions",""],["B","Designing meaningful learning experiences and supporting student engagement",""],["C","Letting students design the course structure",""],["D","Focusing only on final exams",""]],"a":"B","s":0},{"id":"SSA101_Q305","t":"Which role of the online instructor involves guiding students by answering questions and challenging assumptions?","o":[["A","Designer",""],["B","Facilitator",""],["C","Director",""],["D","Evaluator",""]],"a":"C","s":0},{"id":"SSA101_Q306","t":"In the \"Designer\" role, instructors primarily:","o":[["A","Ignore course objectives",""],["B","Design the course structure and guide students to relevant, accurate learning resources",""],["C","Only grade assignments",""],["D","Avoid selecting readings",""]],"a":"B","s":0},{"id":"SSA101_Q307","t":"The \"Facilitator\" role of an online instructor focuses on:","o":[["A","Creating unstructured activities",""],["B","Designing assignments and activities to support intellectual, personal, and professional growth",""],["C","Limiting student interaction",""],["D","Focusing only on theoretical content",""]],"a":"B","s":0},{"id":"SSA101_Q308","t":"Which action demonstrates active participation and interest in the course material?","o":[["A","Checking the course site only once a month",""],["B","Participating actively in discussions and activities",""],["C","Submitting assignments without reviewing instructions",""],["D","Avoiding all contact with the instructor",""]],"a":"B","s":0},{"id":"SSA101_Q309","t":"To stay aware of course expectations and changes, students should:","o":[["A","Ignore announcements",""],["B","Check the course site frequently for updates",""],["C","Rely only on classmates for information",""],["D","Wait until the end of the term",""]],"a":"B","s":0},{"id":"SSA101_Q310","t":"Office hours are useful for:","o":[["A","Socializing unrelated to the course",""],["B","Clarifying academic difficulties and strengthening professional relationships",""],["C","Submitting all assignments late",""],["D","Avoiding feedback on work",""]],"a":"B","s":0},{"id":"SSA101_Q311","t":"The text emphasizes that effective communication with instructors helps students:","o":[["A","Avoid learning the content",""],["B","Fully benefit from instructional support throughout the learning process",""],["C","Reduce the amount of work required",""],["D","Focus only on grades",""]],"a":"B","s":0},{"id":"SSA101_Q312","t":"In the Community of Inquiry model mentioned in Part 3, the instructor's role supports:","o":[["A","Passive learning only",""],["B","Student engagement and the active role of learners in the environment",""],["C","Elimination of all assignments",""],["D","Instructor-centered lectures exclusively",""]],"a":"B","s":0},{"id":"SSA101_Q313","t":"Each course component in an online environment, according to the instructor's Facilitator role, is chosen:","o":[["A","Randomly without purpose",""],["B","Intentionally to contribute to student development",""],["C","Only for entertainment",""],["D","To increase student workload unnecessarily",""]],"a":"B","s":0},{"id":"SSA101_Q314","t":"Why is flexibility in online courses particularly important for many learners?","o":[["A","It eliminates the need for any schedule",""],["B","It allows balancing work, family, or other commitments while studying",""],["C","It reduces the total workload automatically",""],["D","It requires less effort in planning",""]],"a":"B","s":0,"tv":"Tại sao flexibility in online courses particularly important for many learners?"},{"id":"SSA101_Q315","t":"What is the main purpose of creating a master semester schedule?","o":[["A","To focus only on daily tasks",""],["B","To provide an \"overview at a glance\" of all academic requirements and stay on track",""],["C","To replace weekly reviews completely",""],["D","To avoid using course presentations",""]],"a":"B","s":0,"tv":"Mục đích chính của creating a master semester schedule là gì?"},{"id":"SSA101_Q316","t":"In Step 1 of designing a semester schedule, what should the table include?","o":[["A","Only one column for all days",""],["B","Seven columns for days of the week and one row for each week of the semester",""],["C","Rows for months instead of weeks",""],["D","No labels for days or weeks",""]],"a":"B","s":0},{"id":"SSA101_Q317","t":"When populating the semester schedule (Step 3), what should be recorded for graded assignments?","o":[["A","Only the due date",""],["B","The course name, task details, and its value (points/weight)",""],["C","Personal opinions about the task",""],["D","Only personal events",""]],"a":"B","s":0},{"id":"SSA101_Q318","t":"According to the text, approximately how many hours per week should each university course require for study?","o":[["A","3–5 hours",""],["B","9–12 hours",""],["C","20+ hours",""],["D","Only during class time",""]],"a":"B","s":0,"tv":"Theo the text, approximately how many hours per week should each university course require for study"},{"id":"SSA101_Q319","t":"Why is it recommended to plan multiple shorter study sessions rather than one long block?","o":[["A","To increase cognitive overload",""],["B","To improve focus and retention",""],["C","To avoid any routine",""],["D","To reduce the total study time",""]],"a":"B","s":0,"tv":"Tại sao it recommended to plan multiple shorter study sessions rather than one long block?"},{"id":"SSA101_Q320","t":"What should be included in a weekly schedule to support well-being?","o":[["A","No time for rest",""],["B","Daily time for physical activity and time blocks for rest/recreation on weekends",""],["C","Only academic tasks",""],["D","Unlimited OPEN blocks without limits",""]],"a":"B","s":0},{"id":"SSA101_Q321","t":"The weekly review (WR) for each course is best scheduled:","o":[["A","At the beginning of the week",""],["B","Preferably at the end of the week",""],["C","Only once per month",""],["D","During class time only",""]],"a":"B","s":0},{"id":"SSA101_Q322","t":"Studying in smaller blocks of time helps primarily by:","o":[["A","Increasing cognitive overload",""],["B","Covering material in manageable segments and reducing overload",""],["C","Focusing on the entire workload at once",""],["D","Eliminating the need for planning",""]],"a":"B","s":0},{"id":"SSA101_Q323","t":"Which strategy is suggested for using small blocks of time productively during commuting?","o":[["A","Ignoring study completely",""],["B","Scanning/skimming readings, using flash cards, or listening to audio recordings",""],["C","Watching full-length movies",""],["D","Only social media browsing",""]],"a":"B","s":0},{"id":"SSA101_Q324","t":"When creating a daily to-do list, which three key questions should be considered for each task?","o":[["A","Who, what, where",""],["B","When to complete, how much time required, is it a priority",""],["C","Why, how, if",""],["D","Cost, location, people involved",""]],"a":"B","s":0},{"id":"SSA101_Q325","t":"At the end of the day, what should be done with incomplete tasks on the to-do list?","o":[["A","Ignore them permanently",""],["B","Evaluate, reschedule to another day if necessary, or remove if no longer important",""],["C","Blame external factors only",""],["D","Double the workload tomorrow",""]],"a":"B","s":0},{"id":"SSA101_Q326","t":"Which is NOT listed as an advantage of a paper planner for daily task management?","o":[["A","Does not require learning new technology",""],["B","Reduces distractions from digital apps",""],["C","Easy to share tasks during group projects",""],["D","Flexible and adaptable to preferences",""]],"a":"C","s":0},{"id":"SSA101_Q327","t":"One key benefit of an online calendar (e.g., Google Calendar) mentioned in the text is:","o":[["A","It cannot be accessed on multiple devices",""],["B","It integrates tasks and commitments into a single view and facilitates sharing events",""],["C","It only handles small tasks well",""],["D","It requires payment for basic use",""]],"a":"B","s":0},{"id":"SSA101_Q328","t":"Online forums in courses primarily contribute to the development of:","o":[["A","Only cognitive presence",""],["B","Social presence and cognitive presence within the learning community",""],["C","Teaching presence exclusively",""],["D","Individual memorization skills",""]],"a":"B","s":0},{"id":"SSA101_Q329","t":"According to the Level 3 (Most Successful) rubric criteria, a good forum post should:","o":[["A","Be posted only once per course",""],["B","Reflect thoughtful reflection on readings, engage with colleagues' postings, and contribute to class understanding",""],["C","Focus solely on personal opinions without references",""],["D","Contain multiple grammatical errors for authenticity",""]],"a":"B","s":0,"tv":"Theo the Level 3 (Most Successful) rubric criteria, a good forum post should:"},{"id":"SSA101_Q330","t":"Which tip is NOT recommended for participating effectively in online forums?","o":[["A","Establish a regular posting schedule",""],["B","Use overly informal language to build rapport",""],["C","Make explicit connections between posts and course content",""],["D","Respond respectfully and constructively, even with alternative viewpoints",""]],"a":"B","s":0},{"id":"SSA101_Q331","t":"Effective feedback when giving it must include all of the following EXCEPT:","o":[["A","Identify what is being done correctly and well",""],["B","Explain how performance can be improved",""],["C","Suggest possible next steps",""],["D","Compare the person's work to others in the class",""]],"a":"D","s":0},{"id":"SSA101_Q332","t":"When receiving feedback, why is it important to suspend immediate reactions?","o":[["A","To avoid understanding the feedback",""],["B","Emotional reactions like defensiveness can interfere with fully understanding the information",""],["C","To immediately argue against the feedback",""],["D","Because feedback is always negative",""]],"a":"B","s":0},{"id":"SSA101_Q333","t":"Positive feedback is most effective when it is:","o":[["A","Based on rumours rather than facts",""],["B","Offered at an appropriate time, includes recognition of strengths and suggestions, targets changeable behavior, and addresses one point at a time",""],["C","Given without prior agreement or permission",""],["D","Delivered under high stress conditions",""]],"a":"B","s":0},{"id":"SSA101_Q334","t":"Before giving feedback, it is important to:","o":[["A","Offer it without gathering facts",""],["B","Obtain mutual agreement to engage in feedback and gather relevant facts/perspectives",""],["C","Use absolute language like \"always\" or \"never\"",""],["D","Compare the recipient to classmates",""]],"a":"B","s":0},{"id":"SSA101_Q335","t":"ePortfolios emphasize reflection on:","o":[["A","Only the final product or grade",""],["B","The learning process rather than focusing solely on final products",""],["C","Technical tool usage exclusively",""],["D","Competition with other students",""]],"a":"B","s":0},{"id":"SSA101_Q336","t":"Which of the following is a key benefit of maintaining an ePortfolio?","o":[["A","It replaces the need for any course assignments",""],["B","It provides documented evidence of learning for future study programs or employment",""],["C","It focuses only on weekly grades",""],["D","It eliminates the need for reflection",""]],"a":"B","s":0,"tv":"Lựa chọn nào sau đây là a key benefit of maintaining an ePortfolio?"},{"id":"SSA101_Q337","t":"Commonly mentioned tools for creating ePortfolios in the text are:","o":[["A","Microsoft Word and Excel",""],["B","Mahara and WordPress",""],["C","Email and forums only",""],["D","Paper notebooks",""]],"a":"B","s":0},{"id":"SSA101_Q338","t":"Email is described as a primary method of communication in online learning because it is:","o":[["A","Always requiring instant replies",""],["B","Familiar, convenient, easy to access, and supports active participation with instructors",""],["C","Only used for formal complaints",""],["D","Informal and casual in tone",""]],"a":"B","s":0},{"id":"SSA101_Q339","t":"When writing professional emails to instructors, which practice should be avoided?","o":[["A","Using a clear and informative subject line",""],["B","Sending excessively brief messages that may seem impolite",""],["C","Proofreading for grammar and organizing into clear paragraphs",""],["D","Maintaining a formal and professional tone",""]],"a":"B","s":0},{"id":"SSA101_Q340","t":"Before sending an email to an instructor, students should first:","o":[["A","Immediately send without checking",""],["B","Review course materials such as the syllabus, assignment descriptions, or lecture notes",""],["C","Ask classmates for the answer instead",""],["D","Wait until the last minute",""]],"a":"B","s":0},{"id":"SSA101_Q341","t":"Regarding email response times from instructors, the text advises:","o":[["A","Expecting immediate replies within minutes",""],["B","Responses may take 1–3 days, and follow-up only after at least 5 days",""],["C","Sending multiple follow-ups the same day",""],["D","Assuming no response means the question is ignored",""]],"a":"B","s":0},{"id":"SSA101_Q342","t":"In forum participation, Level 1 (Unsuccessful) posts are characterized by:","o":[["A","Consistent posting and clear writing",""],["B","Lack of understanding of readings, no engagement with classmates, irrelevance, inconsistency, and poor writing structure",""],["C","Strong contributions to class understanding",""],["D","Regular interaction and professional style",""]],"a":"B","s":0},{"id":"SSA101_Q343","t":"According to the text, what should be done immediately upon receiving an assignment?","o":[["A","Start writing without reading it fully",""],["B","Read the assignment carefully right away",""],["C","Wait until the deadline approaches",""],["D","Ask classmates for the requirements",""]],"a":"B","s":0,"tv":"Theo the text, what should be done immediately upon receiving an assignment"},{"id":"SSA101_Q344","t":"If any part of the assignment requirements is unclear, the recommended action is to:","o":[["A","Ignore it and proceed anyway",""],["B","Request clarification from the instructor",""],["C","Assume your own interpretation",""],["D","Change the assignment topic",""]],"a":"B","s":0},{"id":"SSA101_Q345","t":"Which of the following is NOT listed as a key question to ask when interpreting an assignment?","o":[["A","What is the required task?",""],["B","What is the purpose of the task?",""],["C","How much will this affect my final grade?",""],["D","What referencing style must be used?",""]],"a":"C","s":0,"tv":"Điều nào sau đây KHÔNG phải là listed as a key question to ask when interpreting an assignment?"},{"id":"SSA101_Q346","t":"The term \"analyze\" falls under which category of common academic task terms?","o":[["A","Identification terms",""],["B","Description terms",""],["C","Relation terms",""],["D","Evaluation terms",""]],"a":"C","s":0},{"id":"SSA101_Q347","t":"Which category of academic task terms includes \"justify,\" \"prove,\" and \"demonstrate\"?","o":[["A","Description terms",""],["B","Demonstration terms",""],["C","Evaluation terms",""],["D","Identification terms",""]],"a":"B","s":0},{"id":"SSA101_Q348","t":"A rubric is best defined as:","o":[["A","A list of optional suggestions for the assignment",""],["B","An assessment tool outlining how the work will be graded and the criteria for success",""],["C","The final grade sheet from the instructor",""],["D","A template for formatting the paper",""]],"a":"B","s":0},{"id":"SSA101_Q349","t":"When should the rubric be reviewed for the first time according to the text?","o":[["A","Only after submitting the assignment",""],["B","Carefully before beginning the assignment",""],["C","During the final proofreading stage",""],["D","After receiving the graded feedback",""]],"a":"B","s":0},{"id":"SSA101_Q350","t":"After completing a draft, the rubric should primarily be used for:","o":[["A","Ignoring minor issues",""],["B","Self-evaluation by grading the work against each criterion and revising weak areas",""],["C","Sharing with classmates only",""],["D","Calculating the expected grade without changes",""]],"a":"B","s":0},{"id":"SSA101_Q351","t":"One major benefit of regularly using a rubric for self-assessment is that it helps:","o":[["A","Avoid all instructor feedback",""],["B","Develop accurate self-assessment skills and align self-evaluation closer to instructor expectations over time",""],["C","Reduce the need to revise work",""],["D","Focus only on final products",""]],"a":"B","s":0},{"id":"SSA101_Q352","t":"When breaking down a large assignment (e.g., a research paper), each step should be:","o":[["A","As broad and general as possible",""],["B","Specific, realistic, and achievable within one day or a single work session",""],["C","Combined into one massive task",""],["D","Left unplanned until the deadline",""]],"a":"B","s":0},{"id":"SSA101_Q353","t":"Why are broad goals like \"work on research paper\" considered insufficient?","o":[["A","They are too specific",""],["B","They are insufficiently defined and may increase procrastination",""],["C","They guarantee high grades",""],["D","They require no planning",""]],"a":"B","s":0},{"id":"SSA101_Q354","t":"Typical steps in a research paper assignment plan include all of the following EXCEPT:","o":[["A","Reviewing instructions and selecting a topic",""],["B","Conducting research and taking notes",""],["C","Drafting sections, revising, and submitting",""],["D","Waiting for classmates to finish first",""]],"a":"D","s":0},{"id":"SSA101_Q355","t":"According to the text, feedback from instructors should be viewed primarily as:","o":[["A","Pure criticism to be ignored",""],["B","An opportunity for development and personal growth rather than just criticism",""],["C","A final judgment with no room for improvement",""],["D","Only relevant for the current assignment",""]],"a":"B","s":0,"tv":"Theo the text, feedback from instructors should be viewed primarily as:"},{"id":"SSA101_Q356","t":"Mid-course reflection (e.g., after midterm exams or major assignments) is useful for:","o":[["A","Avoiding any changes to study habits",""],["B","Evaluating current performance, target grades, and effectiveness of preparation strategies, then revising approaches",""],["C","Focusing only on past successes",""],["D","Ignoring available support resources",""]],"a":"B","s":0},{"id":"SSA101_Q357","t":"The quote \"We all need people who will give us feedback. That's how we improve.\" (Bill Gates) is used in the text to emphasize that:","o":[["A","Feedback is unnecessary in online learning",""],["B","Feedback is an essential component of the learning process for improvement",""],["C","Only grades matter, not comments",""],["D","Feedback should be avoided to prevent stress",""]],"a":"B","s":0},{"id":"SSA101_Q358","t":"Why is taking structured notes considered more effective than simply re-reading online content?","o":[["A","Re-reading is always faster",""],["B","Notes enable faster review of key concepts, require critical engagement, and strengthen retention",""],["C","Notes eliminate the need to access the original text",""],["D","Re-reading requires no intentional effort",""]],"a":"B","s":0,"tv":"Tại sao taking structured notes considered more effective than simply re-reading online content?"},{"id":"SSA101_Q359","t":"Which of the following is NOT mentioned as a possible note-taking method for online readings?","o":[["A","Handwritten notes with underlining and margin annotations",""],["B","Typewritten notes in an electronic notebook",""],["C","Recording audio summaries only",""],["D","Digital annotation tools like Hypothes.is",""]],"a":"C","s":0,"tv":"Điều nào sau đây KHÔNG phải là mentioned as a possible note-taking method for online readings?"},{"id":"SSA101_Q360","t":"To use Hypothes.is for annotating online texts, what is the first step after installing the Chrome extension?","o":[["A","Start annotating without an account",""],["B","Create a free account with email, username, password, and activate via email confirmation",""],["C","Purchase a premium subscription",""],["D","Share annotations publicly without login",""]],"a":"B","s":0},{"id":"SSA101_Q361","t":"In Hypothes.is, annotations are public by default, but users can control visibility by:","o":[["A","Deleting them after use",""],["B","Creating private groups for collaborative or personal notes",""],["C","Making all annotations invisible",""],["D","Avoiding highlighting altogether",""]],"a":"B","s":0},{"id":"SSA101_Q362","t":"When highlighting in online texts, the text advises to avoid:","o":[["A","Highlighting any key information",""],["B","Over-highlighting; limit to essential content only",""],["C","Using annotations alongside highlights",""],["D","Collaborating on highlights",""]],"a":"B","s":0},{"id":"SSA101_Q363","t":"In online learning, why is there typically a larger volume of written material compared to traditional courses?","o":[["A","To reduce reading time",""],["B","It supports development of lifelong learning skills through purposeful selection and management",""],["C","To make courses more difficult",""],["D","Reading is optional in online courses",""]],"a":"B","s":0},{"id":"SSA101_Q364","t":"Before beginning any text, learners should first:","o":[["A","Read the entire document sequentially",""],["B","Clearly define their purpose for reading to determine the appropriate strategy",""],["C","Skip to the conclusion",""],["D","Highlight everything immediately",""]],"a":"B","s":0},{"id":"SSA101_Q365","t":"The SQ3R method is recommended because it:","o":[["A","Encourages passive reading",""],["B","Provides a structured approach for efficient, purposeful, and active reading",""],["C","Requires reading every word in sequence",""],["D","Eliminates the need for notes",""]],"a":"B","s":0},{"id":"SSA101_Q366","t":"In the \"Survey\" step of SQ3R, what should learners do first?","o":[["A","Read the entire chapter in detail",""],["B","Skim the chapter, starting with Learning Objectives, headings, diagrams, and the chapter summary",""],["C","Create questions without overview",""],["D","Recite the content aloud immediately",""]],"a":"B","s":0},{"id":"SSA101_Q367","t":"The \"Question\" step in SQ3R involves:","o":[["A","Ignoring headings",""],["B","Formulating questions based on headings and key concepts to guide focused reading",""],["C","Only reading without questions",""],["D","Reciting answers before reading",""]],"a":"B","s":0},{"id":"SSA101_Q368","t":"During the \"Read\" step of SQ3R, learners should:","o":[["A","Read passively for enjoyment",""],["B","Read actively to locate answers to formulated questions, focusing on key paragraphs and terms",""],["C","Skip sections that seem difficult",""],["D","Highlight everything uniformly",""]],"a":"B","s":0},{"id":"SSA101_Q369","t":"In the \"Recite\" step, what is the key action after reading a section?","o":[["A","Immediately move to the next section",""],["B","Restate main ideas in your own words (paraphrase) before recording notes",""],["C","Copy the text verbatim",""],["D","Avoid any note-taking",""]],"a":"B","s":0},{"id":"SSA101_Q370","t":"The final \"Review\" step of SQ3R involves:","o":[["A","Never revisiting the chapter",""],["B","Revisit notes for the entire chapter, identify connections, and address gaps in understanding",""],["C","Only reviewing highlights",""],["D","Starting a new chapter immediately",""]],"a":"B","s":0},{"id":"SSA101_Q371","t":"After determining a journal article is relevant, what is a recommended next step before detailed reading?","o":[["A","Read the full text sequentially",""],["B","Scan by reviewing headings, bold/italic terms, charts/graphs, and record bibliographic information",""],["C","Skip to the references only",""],["D","Annotate without scanning",""]],"a":"B","s":0},{"id":"SSA101_Q372","t":"In the Plan-Monitor-Evaluate model of metacognitive learning, what specific activity takes place during the \"Evaluation\" phase of the learning cycle?","o":[["A","You identify the specific steps you must take to move toward your goal, choose the learning strategies you will use, and actively reach out for support when necessary",""],["B","You continuously track what you have successfully learned, recognize what you do not yet know, and assess whether your current study strategies are functioning properly",""],["C","You reflect on how well you met your learning objectives after completing a unit of study and consider how your exam preparation strategies could be improved next time",""],["D","You carefully curate the course content and design meaningful collaborative activities that will lead your fellow team members toward professional and personal growth",""]],"a":"C","s":0,"e":"The \"Evaluation\" phase acts as the critical final step in the metacognitive learning cycle, occurring strictly after an academic task, unit, or rigorous exam is fully completed. During this phase, a student must brutally and honestly reflect on whether they actually achieved their initial learning objectives. By objectively analyzing exactly what study strategies worked and which preparation methods completely failed, the student can highly effectively adapt and optimize their approach for the next academic challenge.","ev":"Giai đoạn \"Đánh giá\" đóng vai trò là bước cuối cùng quan trọng trong chu trình học tập siêu nhận thức, diễn ra ngay sau khi một nhiệm vụ học tập, một học phần hoặc một kỳ thi kết thúc. Trong giai đoạn này, sinh viên phải tự suy ngẫm trung thực xem mình có đạt được mục tiêu học tập ban đầu hay không và phân tích chiến lược nào hiệu quả hoặc thất bại để tối ưu hóa cho lần tiếp theo."}],"mocks":[]};
